window.COURSE = {"version":"bc072c9084","units":[{"id":1,"title":"Neu in der Gemeinde","subtitle":"Sich bei der Einwohnerkontrolle anmelden","level":"A2","theme":"Behörden","focus":"Perfekt mit haben und sein","goals":[{"de":"Ich kann mich bei der Gemeinde anmelden und Fragen zu meiner Person beantworten.","en":"I can register with the municipality and answer questions about myself."},{"de":"Ich kann erzählen, was ich letzte Woche gemacht habe.","en":"I can say what I did last week."},{"de":"Ich kann nachfragen, wenn ich etwas nicht verstehe.","en":"I can ask when I don't understand something."}],"vocab":[{"id":"1-0","de":"die Einwohnerkontrolle","forms":"-n","en":"residents' registration office (CH)","ex":"Ich muss mich bei der Einwohnerkontrolle anmelden.","exEn":"I have to register at the residents' office.","aw":"54ab7aa3fc0f","ae":"cf5c77c20b0c"},{"id":"1-1","de":"sich anmelden","forms":"hat sich angemeldet","en":"to register","ex":"Ich habe mich gestern angemeldet.","exEn":"I registered yesterday.","aw":"652bb141a34f","ae":"9d0ece2a4582"},{"id":"1-2","de":"umziehen","forms":"ist umgezogen","en":"to move (house)","ex":"Wir sind im August nach Winterthur umgezogen.","exEn":"We moved to Winterthur in August.","aw":"c209995e1e57","ae":"60db82422d80"},{"id":"1-3","de":"der Umzug","forms":"Umzüge","en":"move, relocation","ex":"Der Umzug war sehr anstrengend.","exEn":"The move was very tiring.","aw":"c77e788b36f7","ae":"8ea8759b57e3"},{"id":"1-4","de":"der Wohnsitz","forms":"-e","en":"place of residence","ex":"Mein neuer Wohnsitz ist in Winterthur.","exEn":"My new residence is in Winterthur.","aw":"d1e6c14b0e91","ae":"8d870709d833"},{"id":"1-5","de":"der Mietvertrag","forms":"Mietverträge","en":"rental contract","ex":"Bitte bringen Sie den Mietvertrag mit.","exEn":"Please bring the rental contract.","aw":"765889a06069","ae":"0a92b8648f14"},{"id":"1-6","de":"der Ausweis","forms":"-e","en":"ID card, permit card","ex":"Haben Sie einen Ausweis dabei?","exEn":"Do you have ID with you?","aw":"62348c4e78cd","ae":"037dd0dcb173"},{"id":"1-7","de":"der Pass","forms":"Pässe","en":"passport","ex":"Mein Pass ist noch zwei Jahre gültig.","exEn":"My passport is valid for two more years.","aw":"5dfc6b607e0b","ae":"747bf73acb27"},{"id":"1-8","de":"das Formular","forms":"-e","en":"form","ex":"Füllen Sie bitte dieses Formular aus.","exEn":"Please fill in this form.","aw":"646882abc1e7","ae":"56cbeb77d61c"},{"id":"1-9","de":"ausfüllen","forms":"hat ausgefüllt","en":"to fill in","ex":"Ich habe das Formular zu Hause ausgefüllt.","exEn":"I filled in the form at home.","aw":"4916027928be","ae":"6bef193869c8"},{"id":"1-10","de":"unterschreiben","forms":"hat unterschrieben","en":"to sign","ex":"Unterschreiben Sie bitte hier unten.","exEn":"Please sign down here.","aw":"098f898484c6","ae":"7402f01958f6"},{"id":"1-11","de":"die Unterschrift","forms":"-en","en":"signature","ex":"Hier fehlt noch Ihre Unterschrift.","exEn":"Your signature is still missing here.","aw":"ca5b1df3fab9","ae":"d228daf229ce"},{"id":"1-12","de":"der Familienstand","forms":"–","en":"marital status","ex":"Was ist Ihr Familienstand?","exEn":"What is your marital status?","aw":"eeaf0534b50f","ae":"653f011071ec"},{"id":"1-13","de":"ledig","forms":"–","en":"single (not married)","ex":"Ich bin ledig.","exEn":"I am single.","aw":"0d64e195782a","ae":"d2d0e03c4999"},{"id":"1-14","de":"verheiratet","forms":"–","en":"married","ex":"Sind Sie verheiratet?","exEn":"Are you married?","aw":"ca0b72686167","ae":"80ac433ed6dd"},{"id":"1-15","de":"die Gebühr","forms":"-en","en":"fee","ex":"Die Gebühr beträgt vierzig Franken.","exEn":"The fee is forty francs.","aw":"577ea3cd1b70","ae":"f7f17b5c8135"},{"id":"1-16","de":"der Schalter","forms":"-","en":"counter (service desk)","ex":"Gehen Sie bitte zu Schalter drei.","exEn":"Please go to counter three.","aw":"1d2033354e9d","ae":"4fa77def2ae7"},{"id":"1-17","de":"die Krankenkasse","forms":"-n","en":"health insurance (CH)","ex":"In der Schweiz braucht jede Person eine Krankenkasse.","exEn":"In Switzerland every person needs health insurance.","aw":"10102c412dbd","ae":"e591f930f1bd"},{"id":"1-18","de":"die Bestätigung","forms":"-en","en":"confirmation","ex":"Die Bestätigung bekommen Sie per Post.","exEn":"You will receive the confirmation by post.","aw":"85eb5036a01a","ae":"ba8cdaf581da"},{"id":"1-19","de":"zuständig","forms":"–","en":"responsible, in charge","ex":"Wer ist hier für die Anmeldung zuständig?","exEn":"Who is in charge of registration here?","aw":"a1f77cc52a15","ae":"4f170c4ebb13"}],"swiss":[{"ch":"Grüezi","std":"Guten Tag","en":"hello (formal greeting in German-speaking Switzerland)"},{"ch":"die Einwohnerkontrolle","std":"das Einwohnermeldeamt","en":"residents' registration office"},{"ch":"der Franken","std":"–","en":"Swiss franc (CHF)"}],"dialogue":{"title":"Am Schalter der Einwohnerkontrolle","intro":"Carla kommt aus Porto. Sie ist neu in Winterthur und meldet sich bei der Gemeinde an.","speakers":{"F":"Carla","M":"Herr Meier"},"lines":[{"s":"M","de":"Guten Tag. Was kann ich für Sie tun?","en":"Good day. What can I do for you?","audio":"6e1a0b2645b1"},{"s":"F","de":"Guten Tag. Ich möchte mich anmelden. Ich bin letzte Woche nach Winterthur umgezogen.","en":"Good day. I would like to register. I moved to Winterthur last week.","audio":"1ef4034acae3"},{"s":"M","de":"Herzlich willkommen! Woher sind Sie gekommen?","en":"Welcome! Where did you come from?","audio":"f93b6a747ced"},{"s":"F","de":"Aus Porto, in Portugal. Ich habe hier eine Stelle bei einer Logistikfirma gefunden.","en":"From Porto, in Portugal. I found a job at a logistics company here.","audio":"04e43ae3cadc"},{"s":"M","de":"Schön. Haben Sie Ihren Pass und den Mietvertrag mitgebracht?","en":"Nice. Did you bring your passport and the rental contract?","audio":"3ddef44c83c7"},{"s":"F","de":"Ja, hier sind beide. Den Arbeitsvertrag habe ich auch dabei.","en":"Yes, here are both. I have the employment contract with me too.","audio":"2d4ea5522949"},{"s":"M","de":"Sehr gut. Haben Sie das Formular schon ausgefüllt?","en":"Very good. Have you already filled in the form?","audio":"03da35cf77a3"},{"s":"F","de":"Ja, gestern Abend. Aber beim Familienstand war ich nicht sicher.","en":"Yes, yesterday evening. But I wasn't sure about the marital status.","audio":"47dd6a7c4d0d"},{"s":"M","de":"Sind Sie verheiratet?","en":"Are you married?","audio":"80ac433ed6dd"},{"s":"F","de":"Nein, ich bin ledig.","en":"No, I'm single.","audio":"c23459763ff9"},{"s":"M","de":"Dann schreiben Sie hier einfach „ledig\". Haben Sie schon eine Krankenkasse?","en":"Then simply write \"single\" here. Do you already have health insurance?","audio":"3c1790c2d82a"},{"s":"F","de":"Noch nicht. Ich habe mich aber schon im Internet informiert.","en":"Not yet. But I have already looked into it online.","audio":"8fd4d3326f25"},{"s":"M","de":"Sie müssen sich innerhalb von drei Monaten versichern. Das ist in der Schweiz Pflicht.","en":"You must get insured within three months. That's compulsory in Switzerland.","audio":"19d481709e9a"},{"s":"F","de":"Entschuldigung, können Sie das bitte wiederholen?","en":"Sorry, could you please repeat that?","audio":"15cfb9db0e00"},{"s":"M","de":"Natürlich. Die Krankenkasse ist Pflicht. Sie haben drei Monate Zeit.","en":"Of course. Health insurance is compulsory. You have three months.","audio":"76b0149449e6"},{"s":"F","de":"Alles klar, danke. Was kostet die Anmeldung?","en":"All right, thanks. What does registration cost?","audio":"1a23edcb6b23"},{"s":"M","de":"Die Gebühr beträgt vierzig Franken. Sie können bar oder mit Karte bezahlen.","en":"The fee is forty francs. You can pay in cash or by card.","audio":"e8c96d07e5f3"},{"s":"F","de":"Mit Karte, bitte. Vielen Dank für Ihre Hilfe!","en":"By card, please. Thank you very much for your help!","audio":"b4bfe3fa9301"},{"s":"M","de":"Gern geschehen. Einen schönen Tag noch!","en":"You're welcome. Have a nice day!","audio":"b8619718cb97"}],"questions":[{"type":"tf","q":"Carla ist vor einem Monat umgezogen.","a":false,"why":"Sie ist letzte Woche umgezogen."},{"type":"tf","q":"Carla hat das Formular schon ausgefüllt.","a":true,"why":"Sie hat es gestern Abend ausgefüllt."},{"type":"mc","q":"Was hat Carla noch nicht?","options":["eine Wohnung","eine Krankenkasse","einen Pass"],"a":1},{"type":"mc","q":"Wie viel Zeit hat Carla für die Krankenkasse?","options":["drei Wochen","drei Monate","ein Jahr"],"a":1},{"type":"mc","q":"Wie bezahlt Carla die Gebühr?","options":["bar","mit Karte","per Rechnung"],"a":1}]},"grammar":{"title":"Das Perfekt – haben oder sein?","summary":"Im Gespräch erzählt man Vergangenes meistens im Perfekt.","sections":[{"h":"So funktioniert das Perfekt","text":"Das Perfekt hat zwei Teile: **haben** oder **sein** (konjugiert, Position 2) und das **Partizip II** (am Satzende). Zusammen bilden sie eine Klammer.","examples":[{"de":"Ich ==habe== gestern ein Formular ==ausgefüllt==.","en":"I filled in a form yesterday.","audio":"a87fd155b659"},{"de":"Carla ==ist== nach Winterthur ==umgezogen==.","en":"Carla moved to Winterthur.","audio":"62f3e9b21b53"},{"de":"==Haben== Sie den Pass ==mitgebracht==?","en":"Did you bring the passport?","audio":"0b6fe0e5ccbb"}]},{"h":"Das Partizip II bilden","text":"Kein **ge-** bei Verben mit untrennbarer Vorsilbe (**be-, ver-, er-, ent-, emp-, zer-, unter-**) und bei Verben auf **-ieren**.","table":[["Typ","Infinitiv","Partizip II"],["regelmässig","machen, kaufen, arbeiten","ge·mach·t, ge·kauf·t, ge·arbeit·et"],["unregelmässig","finden, schreiben, kommen","ge·fund·en, ge·schrieb·en, ge·komm·en"],["trennbar","ausfüllen, mitbringen, umziehen","aus·ge·füllt, mit·ge·bracht, um·ge·zogen"],["ohne ge-","bezahlen, verstehen, unterschreiben","bezahlt, verstanden, unterschrieben"],["auf -ieren","informieren, studieren","informiert, studiert"]]},{"h":"haben oder sein?","text":"Mit **sein**: Bewegung von A nach B (*gehen, fahren, fliegen, kommen, umziehen*), Veränderung des Zustands (*aufstehen, einschlafen, werden*) und die Verben *sein, bleiben, passieren*.\nMit **haben**: fast alle anderen Verben – auch alle reflexiven Verben (*ich habe mich angemeldet*).","examples":[{"de":"Wir ==sind== mit dem Zug nach Zürich ==gefahren==.","en":"We went to Zurich by train.","audio":"01919c922e69"},{"de":"Ich ==bin== um sechs Uhr ==aufgestanden==.","en":"I got up at six o'clock.","audio":"99b3d17a91e7"},{"de":"Er ==hat== sich gestern ==angemeldet==.","en":"He registered yesterday.","audio":"20dd86c0a835"}]},{"h":"Präteritum von sein und haben","text":"Bei **sein** und **haben** benutzt man auch im Gespräch fast immer das Präteritum: *Ich war beim Arzt. Ich hatte keine Zeit.*","table":[["Person","sein","haben"],["ich","war","hatte"],["du","warst","hattest"],["er/sie/es","war","hatte"],["wir","waren","hatten"],["ihr","wart","hattet"],["sie/Sie","waren","hatten"]]}],"tip":"Achtung bei trennbaren Verben – das „ge\" steht in der Mitte: an·ge·meldet, aus·ge·füllt, um·ge·zogen."},"exercises":[{"type":"choice","title":"haben oder sein?","items":[{"q":"Ich ___ letzte Woche umgezogen.","options":["bin","habe"],"a":0,"full":"Ich bin letzte Woche umgezogen.","audio":"ebd2098dd77e"},{"q":"Wir ___ das Formular zusammen ausgefüllt.","options":["haben","sind"],"a":0,"full":"Wir haben das Formular zusammen ausgefüllt.","audio":"1c99bd6b3e73"},{"q":"Carla ___ mit dem Zug nach Zürich gefahren.","options":["ist","hat"],"a":0,"full":"Carla ist mit dem Zug nach Zürich gefahren.","audio":"befa366478b2"},{"q":"___ du dich schon angemeldet?","options":["Hast","Bist"],"a":0,"full":"Hast du dich schon angemeldet?","audio":"b1e909b1d0ee"},{"q":"Der Mann am Schalter ___ sehr freundlich gewesen.","options":["ist","hat"],"a":0,"full":"Der Mann am Schalter ist sehr freundlich gewesen.","audio":"2c31735803ed"},{"q":"Wann ___ ihr heute aufgestanden?","options":["seid","habt"],"a":0,"full":"Wann seid ihr heute aufgestanden?","audio":"00de5388c47b"},{"q":"Ich ___ lange auf meinen Termin gewartet.","options":["habe","bin"],"a":0,"full":"Ich habe lange auf meinen Termin gewartet.","audio":"2dfe772feb9a"},{"q":"Was ___ denn passiert?","options":["ist","hat"],"a":0,"full":"Was ist denn passiert?","audio":"58e3e67693cd"}]},{"type":"gap","title":"Partizip II – schreiben Sie die richtige Form","items":[{"q":"Hast du den Mietvertrag ___? (mitbringen)","a":["mitgebracht"],"full":"Hast du den Mietvertrag mitgebracht?","audio":"940936435ea8"},{"q":"Ich habe das Formular schon ___. (ausfüllen)","a":["ausgefüllt"],"full":"Ich habe das Formular schon ausgefüllt.","audio":"b62e0d5ad448"},{"q":"Carla hat eine neue Stelle ___. (finden)","a":["gefunden"],"full":"Carla hat eine neue Stelle gefunden.","audio":"3d0adae044f3"},{"q":"Wir haben die Gebühr mit Karte ___. (bezahlen)","a":["bezahlt"],"full":"Wir haben die Gebühr mit Karte bezahlt.","audio":"8a0865461573"},{"q":"Haben Sie hier schon ___? (unterschreiben)","a":["unterschrieben"],"full":"Haben Sie hier schon unterschrieben?","audio":"862e8f5e6de7"},{"q":"Ich habe mich im Internet ___. (informieren)","a":["informiert"],"full":"Ich habe mich im Internet informiert.","audio":"4fe55ecbb194"},{"q":"Sie ist im August nach Winterthur ___. (umziehen)","a":["umgezogen"],"full":"Sie ist im August nach Winterthur umgezogen.","audio":"a6b024edf875"},{"q":"Wir sind am Sonntag zu Hause ___. (bleiben)","a":["geblieben"],"full":"Wir sind am Sonntag zu Hause geblieben.","audio":"0a5d17dcde14"}]},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Ich habe mich gestern bei der Gemeinde angemeldet.","Gestern habe ich mich bei der Gemeinde angemeldet."],"tokens":["Ich","habe","mich","gestern","bei","der","Gemeinde","angemeldet."],"audio":"3e6dadf69250"},{"a":["Carla ist im September in die Schweiz gekommen.","Im September ist Carla in die Schweiz gekommen."],"tokens":["Carla","ist","im","September","in","die","Schweiz","gekommen."],"audio":"29668d2af0b6"},{"a":["Haben Sie das Formular schon unterschrieben?"],"tokens":["Haben","Sie","das","Formular","schon","unterschrieben?"],"audio":"0b30c748ef6a"},{"a":["Wir sind mit dem Bus zur Einwohnerkontrolle gefahren.","Mit dem Bus sind wir zur Einwohnerkontrolle gefahren."],"tokens":["Wir","sind","mit","dem","Bus","zur","Einwohnerkontrolle","gefahren."],"audio":"f7de7a2a2fd8"},{"a":["Was hast du am Wochenende gemacht?"],"tokens":["Was","hast","du","am","Wochenende","gemacht?"],"audio":"3391533e2d04"}]},{"type":"match","title":"Infinitiv und Partizip II","items":[{"l":"gehen","r":"gegangen"},{"l":"schreiben","r":"geschrieben"},{"l":"bringen","r":"gebracht"},{"l":"verstehen","r":"verstanden"},{"l":"anrufen","r":"angerufen"},{"l":"studieren","r":"studiert"},{"l":"fahren","r":"gefahren"},{"l":"bleiben","r":"geblieben"}]},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Ich bin letzte Woche umgezogen.","audio":"9b1f2d312796"},{"a":"Haben Sie Ihren Pass mitgebracht?","audio":"c610f6dcdfb0"},{"a":"Wir haben das Formular zusammen ausgefüllt.","audio":"c31ce4c2c360"},{"a":"Können Sie das bitte wiederholen?","audio":"73fd48a708ee"}]}],"reading":{"title":"Meine erste Woche in Winterthur","kind":"E-Mail","paras":[{"t":"Liebe Sofia","audio":"f247c2b3f1d1"},{"t":"Wie geht es dir? Ich bin jetzt schon eine Woche in Winterthur! Die ersten Tage waren sehr intensiv. Am Montag bin ich mit zwei grossen Koffern am Flughafen Zürich angekommen. Von dort bin ich mit dem Zug nach Winterthur gefahren – das hat nur zwanzig Minuten gedauert.","audio":"309c2134a32a"},{"t":"Meine Wohnung ist klein, aber hell und ruhig. Am Dienstag habe ich ein Bett und einen Tisch gekauft, und am Mittwoch hat mir ein Kollege beim Aufbauen geholfen.","audio":"3c71e8e7e277"},{"t":"Gestern war ich bei der Einwohnerkontrolle. Ich habe mich angemeldet und viele Fragen beantwortet. Der Mann am Schalter hat langsam gesprochen, deshalb habe ich fast alles verstanden. Jetzt muss ich noch eine Krankenkasse suchen – das ist hier Pflicht.","audio":"4a7f1b20c66c"},{"t":"Am Samstag habe ich die Altstadt besucht. Es hat geregnet, aber ich habe ein schönes Café gefunden und dort einen Kuchen gegessen. Die Leute sind sehr freundlich. Manchmal sprechen sie Schweizerdeutsch, und dann verstehe ich fast nichts! Zum Glück sprechen alle auch Hochdeutsch, wenn ich frage.","audio":"8c95bd446902"},{"t":"Wann besuchst du mich? Ich habe jetzt ein Sofa für Gäste!","audio":"7e17cc7c4171"},{"t":"Liebe Grüsse\nCarla","audio":"dc1f336eeb07"}],"glossary":[{"de":"intensiv","en":"intense"},{"de":"der Koffer","en":"suitcase"},{"de":"ankommen (ist angekommen)","en":"to arrive"},{"de":"aufbauen","en":"to assemble, set up"},{"de":"deshalb","en":"that's why, therefore"},{"de":"zum Glück","en":"luckily"}],"questions":[{"type":"tf","q":"Carla ist mit dem Zug vom Flughafen nach Winterthur gefahren.","a":true,"why":""},{"type":"tf","q":"Carla hat die Möbel allein aufgebaut.","a":false,"why":"Ein Kollege hat ihr geholfen."},{"type":"mc","q":"Warum hat Carla am Schalter fast alles verstanden?","options":["Der Mann hat Englisch gesprochen.","Der Mann hat langsam gesprochen.","Sie hat ein Wörterbuch benutzt."],"a":1},{"type":"mc","q":"Was hat Carla am Samstag gemacht?","options":["Sie hat die Altstadt besucht.","Sie ist nach Zürich gefahren.","Sie hat Möbel gekauft."],"a":0},{"type":"tf","q":"Carla versteht Schweizerdeutsch gut.","a":false,"why":"Sie versteht fast nichts."}]},"writing":{"task":"Sie sind neu in Ihrer Gemeinde. Schreiben Sie eine E-Mail an eine Freundin oder einen Freund (60–80 Wörter).","points":["Wann sind Sie umgezogen?","Was haben Sie in der ersten Woche gemacht?","Was war schwierig?","Laden Sie die Person zu sich ein."],"phrases":[{"de":"Ich bin am … nach … umgezogen.","en":"I moved to … on …"},{"de":"In der ersten Woche habe ich …","en":"In the first week I …"},{"de":"Schwierig war …","en":"What was difficult was …"},{"de":"Hast du Lust, mich zu besuchen?","en":"Would you like to visit me?"}],"model":"Lieber Marco\n\nIch bin am 1. September nach Winterthur umgezogen. In der ersten Woche habe ich viele Dinge gemacht: Ich habe mich bei der Gemeinde angemeldet, ein Bankkonto eröffnet und Möbel gekauft. Schwierig war das Schweizerdeutsch – ich habe am Anfang fast nichts verstanden! Aber die Leute sind sehr hilfsbereit. Hast du im Oktober Zeit? Dann kannst du mich gerne besuchen. Ich zeige dir die Altstadt.\n\nViele Grüsse\nCarla","audio":"ddeca5156e7a"},"speaking":{"task":"Am Schalter – beantworten Sie die Fragen zu Ihrer Person. Hören Sie die Frage, antworten Sie laut und vergleichen Sie dann mit dem Beispiel.","phrases":[{"de":"Ich möchte mich anmelden.","en":"I would like to register.","audio":"f33b14644810"},{"de":"Können Sie das bitte wiederholen?","en":"Could you please repeat that?","audio":"c11a494c5657"},{"de":"Können Sie bitte etwas langsamer sprechen?","en":"Could you speak a bit more slowly, please?","audio":"db67013c9fe3"},{"de":"Wie schreibt man das?","en":"How do you spell that?","audio":"e8dc9ea3c6fd"},{"de":"Was muss ich hier eintragen?","en":"What do I have to enter here?","audio":"2085797cfba3"}],"prompts":[{"q":"Wie ist Ihr Name, und woher kommen Sie?","model":"Mein Name ist Carla Ferreira. Ich komme aus Porto, in Portugal.","aq":"a1872c7a06fe","am":"ae2c7968d682"},{"q":"Seit wann wohnen Sie in der Schweiz?","model":"Ich wohne seit einer Woche in der Schweiz. Ich bin am ersten September angekommen.","aq":"ab47649be334","am":"e98153c3ab76"},{"q":"Warum sind Sie in die Schweiz gekommen?","model":"Ich habe hier eine Stelle gefunden. Ich arbeite bei einer Logistikfirma.","aq":"20b0aea8af63","am":"78a4b2f6172c"},{"q":"Was haben Sie letztes Wochenende gemacht?","model":"Am Samstag habe ich die Altstadt besucht, und am Sonntag bin ich zu Hause geblieben und habe gekocht.","aq":"3ef6f922468a","am":"7c6aafe8cee9"}]}},{"id":2,"title":"Eine Wohnung finden","subtitle":"Inserate lesen, eine Wohnung besichtigen","level":"A2","theme":"Wohnen","focus":"Nebensätze mit weil, dass und wenn","goals":[{"de":"Ich kann Wohnungsinserate verstehen und vergleichen.","en":"I can understand and compare flat adverts."},{"de":"Ich kann bei einer Besichtigung Fragen stellen und sagen, was ich suche.","en":"I can ask questions at a viewing and say what I'm looking for."},{"de":"Ich kann Gründe nennen und meine Meinung sagen (weil, dass, wenn).","en":"I can give reasons and say my opinion."}],"vocab":[{"id":"2-0","de":"die Wohnungsbesichtigung","forms":"-en","en":"flat viewing","ex":"Die Besichtigung ist am Samstag um zehn Uhr.","exEn":"The viewing is on Saturday at ten.","aw":"8e14bd9fdfcc","ae":"31e3b3aaf1e6"},{"id":"2-1","de":"das Inserat","forms":"-e","en":"advert (CH)","ex":"Ich habe das Inserat im Internet gesehen.","exEn":"I saw the advert online.","aw":"2b672ce196cf","ae":"2e97e3e5787e"},{"id":"2-2","de":"der Mietzins","forms":"-e","en":"rent (CH)","ex":"Der Mietzins ist für Winterthur ziemlich hoch.","exEn":"The rent is quite high for Winterthur.","aw":"6b0348398869","ae":"95387468c7ff"},{"id":"2-3","de":"die Nebenkosten","forms":"(Pl.)","en":"additional costs (heating, water …)","ex":"Sind die Nebenkosten inklusive?","exEn":"Are the additional costs included?","aw":"c3f50ceb66be","ae":"2019256b3748"},{"id":"2-4","de":"das Mietzinsdepot","forms":"-s","en":"rental deposit (CH)","ex":"Das Mietzinsdepot beträgt drei Monatsmieten.","exEn":"The deposit is three months' rent.","aw":"ae46aa695a5f","ae":"fa6be65cb736"},{"id":"2-5","de":"der Vermieter","forms":"-","en":"landlord","ex":"Der Vermieter wohnt im gleichen Haus.","exEn":"The landlord lives in the same building.","aw":"85715249fa57","ae":"8647174b98e6"},{"id":"2-6","de":"die Verwaltung","forms":"-en","en":"property management","ex":"Die Verwaltung hat mir heute geantwortet.","exEn":"The management company replied to me today.","aw":"bd3b64f5077b","ae":"17fb90ea315f"},{"id":"2-7","de":"der Stock","forms":"Stockwerke","en":"floor, storey","ex":"Die Wohnung liegt im dritten Stock.","exEn":"The flat is on the third floor.","aw":"59729ec053bc","ae":"3572d4594bf9"},{"id":"2-8","de":"das Erdgeschoss","forms":"-e","en":"ground floor","ex":"Im Erdgeschoss gibt es einen kleinen Garten.","exEn":"There is a small garden on the ground floor.","aw":"42e907b730be","ae":"c832b6cf9355"},{"id":"2-9","de":"einziehen","forms":"ist eingezogen","en":"to move in","ex":"Wann können wir einziehen?","exEn":"When can we move in?","aw":"ac8475c58156","ae":"3a36fc28a9e0"},{"id":"2-10","de":"ausziehen","forms":"ist ausgezogen","en":"to move out","ex":"Die alte Mieterin ist schon ausgezogen.","exEn":"The previous tenant has already moved out.","aw":"6f3860cb99d3","ae":"6d4a4c991f47"},{"id":"2-11","de":"kündigen","forms":"hat gekündigt","en":"to give notice, to cancel","ex":"Ich muss meine alte Wohnung kündigen.","exEn":"I have to give notice on my old flat.","aw":"82f6c2f53392","ae":"f84fb7d25cf2"},{"id":"2-12","de":"hell","forms":"–","en":"bright, light","ex":"Das Wohnzimmer ist schön hell.","exEn":"The living room is nice and bright.","aw":"49ad11070ae3","ae":"b45af26823e6"},{"id":"2-13","de":"ruhig","forms":"–","en":"quiet","ex":"Die Strasse ist sehr ruhig.","exEn":"The street is very quiet.","aw":"30eac6205130","ae":"52e6b18ab995"},{"id":"2-14","de":"zentral","forms":"–","en":"central","ex":"Die Wohnung liegt zentral, nahe beim Bahnhof.","exEn":"The flat is central, close to the station.","aw":"6edad344aaf1","ae":"dddbdc229256"},{"id":"2-15","de":"möbliert","forms":"–","en":"furnished","ex":"Ich suche eine möblierte Wohnung.","exEn":"I'm looking for a furnished flat.","aw":"352d3c02ece6","ae":"b730e4c6a684"},{"id":"2-16","de":"sich bewerben","forms":"hat sich beworben","en":"to apply","ex":"Ich möchte mich für die Wohnung bewerben.","exEn":"I would like to apply for the flat.","aw":"ecc17dee709a","ae":"9a9a6c75c1ae"},{"id":"2-17","de":"der Betreibungsregisterauszug","forms":"-auszüge","en":"debt register extract (CH)","ex":"Für die Bewerbung brauchen Sie einen Betreibungsregisterauszug.","exEn":"For the application you need a debt register extract.","aw":"46a0a1e29b37","ae":"f37d1a64885e"},{"id":"2-18","de":"das Haustier","forms":"-e","en":"pet","ex":"Sind Haustiere erlaubt?","exEn":"Are pets allowed?","aw":"9633066d9479","ae":"9e00a7b320dc"},{"id":"2-19","de":"erlaubt","forms":"–","en":"allowed","ex":"Rauchen ist in der Wohnung nicht erlaubt.","exEn":"Smoking is not allowed in the flat.","aw":"277a36c10a81","ae":"267f554ed83a"}],"swiss":[{"ch":"das Inserat","std":"die Anzeige","en":"advert"},{"ch":"der Mietzins","std":"die Miete","en":"rent"},{"ch":"das Mietzinsdepot","std":"die Kaution","en":"rental deposit"},{"ch":"die 3½-Zimmer-Wohnung","std":"–","en":"Swiss room count; the ½ usually stands for a large eat-in kitchen or hall"},{"ch":"der Betreibungsregisterauszug","std":"–","en":"proof that you have no unpaid debts; landlords almost always ask for it"}],"dialogue":{"title":"Bei der Wohnungsbesichtigung","intro":"Carla besichtigt eine Wohnung in Winterthur-Veltheim. Herr Baumann von der Verwaltung zeigt ihr die Wohnung.","speakers":{"F":"Carla","M":"Herr Baumann"},"lines":[{"s":"M","de":"Guten Tag, Sie sind sicher Frau Ferreira. Kommen Sie herein.","en":"Hello, you must be Ms Ferreira. Come in.","audio":"30f9ff51f7e2"},{"s":"F","de":"Guten Tag. Danke, dass ich die Wohnung heute anschauen kann.","en":"Hello. Thank you for letting me see the flat today.","audio":"03253065e6b0"},{"s":"M","de":"Gern. Das ist eine 3½-Zimmer-Wohnung im dritten Stock. Sie ist sehr hell, wie Sie sehen.","en":"You're welcome. This is a 3.5-room flat on the third floor. It's very bright, as you can see.","audio":"f36ace0b59bb"},{"s":"F","de":"Ja, wirklich schön. Ich suche eine grössere Wohnung, weil meine jetzige Wohnung nur ein Zimmer hat.","en":"Yes, really nice. I'm looking for a bigger flat because my current flat only has one room.","audio":"8f9a1bb8d626"},{"s":"M","de":"Verstehe. Wohnen Sie allein?","en":"I see. Do you live alone?","audio":"ea8647f5b5aa"},{"s":"F","de":"Im Moment schon. Aber ich hoffe, dass mein Freund im Frühling auch in die Schweiz kommt.","en":"At the moment, yes. But I hope that my boyfriend will come to Switzerland in the spring too.","audio":"35b0c8eae8fe"},{"s":"M","de":"Die Küche ist ganz neu, und hier ist der Balkon.","en":"The kitchen is brand new, and here is the balcony.","audio":"bffb85d3b0d5"},{"s":"F","de":"Toll! Wie hoch ist der Mietzins?","en":"Great! How high is the rent?","audio":"1fed783b30f5"},{"s":"M","de":"Achtzehnhundertfünfzig Franken, plus zweihundertzwanzig Franken Nebenkosten.","en":"One thousand eight hundred and fifty francs, plus two hundred and twenty francs additional costs.","audio":"4b1e13c413db"},{"s":"F","de":"Das ist nicht wenig. Muss man auch ein Mietzinsdepot bezahlen?","en":"That's not cheap. Do you also have to pay a deposit?","audio":"d47318527e78"},{"s":"M","de":"Ja, drei Monatsmieten. Das ist in der Schweiz normal.","en":"Yes, three months' rent. That's normal in Switzerland.","audio":"4bc4a780ae1a"},{"s":"F","de":"Und sind Haustiere erlaubt? Ich habe eine Katze.","en":"And are pets allowed? I have a cat.","audio":"26807625adad"},{"s":"M","de":"Eine Katze ist kein Problem. Für einen Hund braucht man aber eine Erlaubnis.","en":"A cat is no problem. For a dog, however, you need permission.","audio":"afd2523045ce"},{"s":"F","de":"Perfekt. Was muss ich machen, wenn ich mich bewerben möchte?","en":"Perfect. What do I have to do if I want to apply?","audio":"fd6212beed09"},{"s":"M","de":"Sie füllen das Anmeldeformular aus und schicken uns einen Betreibungsregisterauszug.","en":"You fill in the application form and send us a debt register extract.","audio":"aa3725bb57f4"},{"s":"F","de":"Einen Betreibungs… Entschuldigung, was ist das?","en":"A debt… Sorry, what is that?","audio":"1dd853e03a88"},{"s":"M","de":"Das Dokument zeigt, dass Sie keine Schulden haben. Sie können es online bestellen.","en":"The document shows that you have no debts. You can order it online.","audio":"52d5600f211a"},{"s":"F","de":"Ah, verstehe. Dann schicke ich Ihnen alles bis Montag.","en":"Ah, I see. Then I'll send you everything by Monday.","audio":"41a8be06cb7d"},{"s":"M","de":"Sehr gut. Wenn Sie noch Fragen haben, rufen Sie mich einfach an.","en":"Very good. If you have any more questions, just call me.","audio":"a35e74520798"}],"questions":[{"type":"tf","q":"Die Wohnung liegt im dritten Stock.","a":true,"why":""},{"type":"mc","q":"Warum sucht Carla eine neue Wohnung?","options":["Ihre Wohnung ist zu teuer.","Ihre Wohnung hat nur ein Zimmer.","Sie hat Probleme mit den Nachbarn."],"a":1},{"type":"tf","q":"Die Nebenkosten sind im Mietzins inklusive.","a":false,"why":"Man bezahlt 220 Franken extra."},{"type":"mc","q":"Was sagt Herr Baumann über Haustiere?","options":["Alle Haustiere sind verboten.","Eine Katze ist kein Problem.","Hunde sind kein Problem."],"a":1},{"type":"mc","q":"Was zeigt der Betreibungsregisterauszug?","options":["dass man keine Schulden hat","wie viel man verdient","wo man früher gewohnt hat"],"a":0}]},"grammar":{"title":"Nebensätze mit weil, dass und wenn","summary":"Im Nebensatz steht das konjugierte Verb am Ende.","sections":[{"h":"Das Verb geht ans Ende","text":"Nach **weil**, **dass** und **wenn** beginnt ein Nebensatz. Das konjugierte Verb steht dort ganz am **Ende**. Vor dem Nebensatz steht ein Komma.","examples":[{"de":"Meine Wohnung ==ist== zu klein. → Ich suche eine Wohnung, weil meine Wohnung zu klein ==ist==.","en":"My flat is too small. → I'm looking for a flat because my flat is too small.","audio":"2557eb90028f"},{"de":"Die Wohnung ==ist== noch frei. → Ich hoffe, dass die Wohnung noch frei ==ist==.","en":"I hope that the flat is still available.","audio":"7f9a4f37da2a"},{"de":"Sie ==haben== Fragen. → Wenn Sie Fragen ==haben==, rufen Sie mich an.","en":"If you have questions, call me.","audio":"5eed6c82df96"}]},{"h":"Wann benutze ich was?","table":[["Konnektor","Funktion","Beispiel"],["weil","Grund (Warum?)","…, weil die Wohnung zentral ist."],["dass","Inhalt nach sagen, denken, hoffen, wissen, finden …","Ich finde, dass die Miete zu hoch ist."],["wenn","Bedingung oder Zeit (immer wenn)","Wenn es regnet, nehme ich den Bus."]]},{"h":"Nebensatz zuerst – Verb, Verb","text":"Steht der Nebensatz am Anfang, kommt im Hauptsatz **sofort das Verb**. So stehen zwei Verben direkt nebeneinander, getrennt durch ein Komma.","examples":[{"de":"Wenn die Wohnung frei ==ist==, ==ziehe== ich im Mai ein.","en":"If the flat is available, I'll move in in May.","audio":"985c54871a73"},{"de":"Weil sie zentral ==liegt==, ==ist== die Wohnung teuer.","en":"Because it's central, the flat is expensive.","audio":"c73955d14e70"}]},{"h":"Modalverben, Perfekt und trennbare Verben","text":"Auch hier steht das **konjugierte** Verb am Ende. Trennbare Verben sind im Nebensatz wieder zusammen.","examples":[{"de":"Ich rufe an, weil ich die Wohnung besichtigen ==möchte==.","en":"I'm calling because I'd like to view the flat.","audio":"99fc3306eacb"},{"de":"Sie sagt, dass sie schon ausgezogen ==ist==.","en":"She says that she has already moved out.","audio":"7167b26c5ad5"},{"de":"Ich weiss nicht, wann er ==einzieht==.","en":"I don't know when he's moving in.","audio":"ea06221f9bdc"}]}],"tip":"weil oder denn? Beide nennen einen Grund. Nach „denn\" bleibt die normale Wortstellung (Verb auf Position 2). Ich suche eine Wohnung, denn meine Wohnung ist zu klein."},"exercises":[{"type":"choice","title":"weil, dass oder wenn?","items":[{"q":"Ich hoffe, ___ die Wohnung noch frei ist.","options":["dass","weil","wenn"],"a":0,"full":"Ich hoffe, dass die Wohnung noch frei ist.","audio":"8fab7c82a6e5"},{"q":"Carla sucht eine neue Wohnung, ___ ihre Wohnung zu klein ist.","options":["weil","dass","wenn"],"a":0,"full":"Carla sucht eine neue Wohnung, weil ihre Wohnung zu klein ist.","audio":"2e63f9c91598"},{"q":"___ Sie Fragen haben, rufen Sie mich an.","options":["Wenn","Dass","Weil"],"a":0,"full":"Wenn Sie Fragen haben, rufen Sie mich an.","audio":"0d80e35ac311"},{"q":"Der Vermieter sagt, ___ Katzen erlaubt sind.","options":["dass","wenn","weil"],"a":0,"full":"Der Vermieter sagt, dass Katzen erlaubt sind.","audio":"a2f52be7e43b"},{"q":"Wir nehmen die Wohnung, ___ sie zentral und ruhig ist.","options":["weil","dass","wenn"],"a":0,"full":"Wir nehmen die Wohnung, weil sie zentral und ruhig ist.","audio":"b0e001bb3902"},{"q":"___ es regnet, fahre ich mit dem Bus zur Arbeit.","options":["Wenn","Weil","Dass"],"a":0,"full":"Wenn es regnet, fahre ich mit dem Bus zur Arbeit.","audio":"008324f0e669"},{"q":"Es ist wichtig, ___ Sie den Mietvertrag genau lesen.","options":["dass","wenn","weil"],"a":0,"full":"Es ist wichtig, dass Sie den Mietvertrag genau lesen.","audio":"a294eb802bb8"},{"q":"Ich kann nicht zur Besichtigung kommen, ___ ich arbeiten muss.","options":["weil","dass","wenn"],"a":0,"full":"Ich kann nicht zur Besichtigung kommen, weil ich arbeiten muss.","audio":"bec632a0a818"}]},{"type":"gap","title":"Wo steht das Verb? Schreiben Sie die richtige Form.","items":[{"q":"Ich nehme die Wohnung, weil sie sehr hell ___. (sein)","a":["ist"],"full":"Ich nehme die Wohnung, weil sie sehr hell ist.","audio":"21dbbfc716f1"},{"q":"Ich hoffe, dass der Vermieter mich bald ___. (anrufen)","a":["anruft"],"full":"Ich hoffe, dass der Vermieter mich bald anruft.","audio":"7f850d9e65f3"},{"q":"Wenn du Zeit ___, komm doch zur Besichtigung mit. (haben)","a":["hast"],"full":"Wenn du Zeit hast, komm doch zur Besichtigung mit.","audio":"41a22e375e5b"},{"q":"Sie sagt, dass sie im Juni ___. (einziehen)","a":["einzieht"],"full":"Sie sagt, dass sie im Juni einzieht.","audio":"001eb1f161bc"},{"q":"Ich bin müde, weil ich den ganzen Tag Kisten getragen ___. (haben)","a":["habe"],"full":"Ich bin müde, weil ich den ganzen Tag Kisten getragen habe.","audio":"15c541696e9c"},{"q":"Weisst du, dass man hier keine Hunde halten ___? (dürfen)","a":["darf"],"full":"Weisst du, dass man hier keine Hunde halten darf?","audio":"0fa599dda64b"}]},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Ich suche eine Wohnung, weil ich mehr Platz brauche."],"tokens":["Ich","suche","eine","Wohnung,","weil","ich","mehr","Platz","brauche."],"audio":"6c9ede104ead"},{"a":["Ich glaube, dass die Nebenkosten zu hoch sind."],"tokens":["Ich","glaube,","dass","die","Nebenkosten","zu","hoch","sind."],"audio":"946b3ba84fb0"},{"a":["Wenn die Wohnung frei ist, ziehe ich im Mai ein.","Ich ziehe im Mai ein, wenn die Wohnung frei ist."],"tokens":["Wenn","die","Wohnung","frei","ist,","ziehe","ich","im","Mai","ein."],"audio":"985c54871a73"},{"a":["Er sagt, dass Haustiere nicht erlaubt sind."],"tokens":["Er","sagt,","dass","Haustiere","nicht","erlaubt","sind."],"audio":"b77746571009"},{"a":["Weil die Wohnung zentral liegt, ist sie teuer."],"tokens":["Weil","die","Wohnung","zentral","liegt,","ist","sie","teuer."],"audio":"587134f85a4f"}]},{"type":"match","title":"Was passt zusammen?","items":[{"l":"Ich rufe die Verwaltung an,","r":"weil die Heizung nicht funktioniert."},{"l":"Wenn du einen Hund hast,","r":"brauchst du eine Erlaubnis."},{"l":"Ich finde es super,","r":"dass die Wohnung einen Balkon hat."},{"l":"Wir suchen eine grössere Wohnung,","r":"weil wir ein Baby bekommen."},{"l":"Wenn die Wohnung möbliert ist,","r":"musst du keine Möbel kaufen."}]},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Ich suche eine Wohnung, weil meine Wohnung zu klein ist.","audio":"2c568c189d28"},{"a":"Sind Haustiere in dieser Wohnung erlaubt?","audio":"3a43e9241945"},{"a":"Wenn Sie Fragen haben, rufen Sie mich an.","audio":"56a581e22a88"},{"a":"Ich hoffe, dass ich die Wohnung bekomme.","audio":"dedceb9da1ce"}]}],"reading":{"title":"Drei Wohnungsinserate","kind":"Inserate","paras":[{"t":"**A – Winterthur-Veltheim**\nSchöne 3½-Zimmer-Wohnung im 2. Stock, 78 m², sonniger Balkon mit Blick ins Grüne. Neue Küche, eigene Waschmaschine und Tumbler. 5 Minuten zur Bushaltestelle. Mietzins CHF 1850.– plus CHF 220.– Nebenkosten. Haustiere auf Anfrage. Frei ab 1. Dezember.","audio":null},{"t":"**B – Winterthur-Zentrum**\nMöblierte 1½-Zimmer-Wohnung, ideal für Studierende oder Wochenaufenthalter. Nur 3 Minuten zum Hauptbahnhof. Mietzins CHF 1290.– inklusive Nebenkosten und Internet. Keine Haustiere. Mindestmietdauer 6 Monate. Frei ab sofort.","audio":null},{"t":"**C – Winterthur-Seen**\nRuhige 4½-Zimmer-Wohnung im Erdgeschoss mit kleinem Garten. Ideal für Familien: Kindergarten und Schule ganz in der Nähe. Keine eigene Waschmaschine, Waschküche im Keller. Mietzins CHF 2100.– plus CHF 250.– Nebenkosten. Haustiere willkommen. Frei ab 1. Januar.","audio":null}],"glossary":[{"de":"der Tumbler (CH)","en":"tumble dryer"},{"de":"der Wochenaufenthalter (CH)","en":"person who stays in a town only during the working week"},{"de":"auf Anfrage","en":"on request"},{"de":"die Mindestmietdauer","en":"minimum rental period"},{"de":"ab sofort","en":"immediately"},{"de":"m² (Quadratmeter)","en":"square metres"}],"questions":[{"type":"mc","q":"Familie Keller hat zwei Kinder und einen Hund. Welche Wohnung passt?","options":["A","B","C"],"a":2},{"type":"mc","q":"Luca studiert ein Semester in Winterthur und hat keine Möbel. Welche Wohnung passt?","options":["A","B","C"],"a":1},{"type":"mc","q":"Frau Suter möchte eine eigene Waschmaschine und einen Balkon. Welche Wohnung passt?","options":["A","B","C"],"a":0},{"type":"tf","q":"In Wohnung B sind die Nebenkosten im Mietzins inklusive.","a":true,"why":""},{"type":"tf","q":"Wohnung C ist ab sofort frei.","a":false,"why":"Sie ist ab dem 1. Januar frei."}]},"writing":{"task":"Sie interessieren sich für Wohnung A. Schreiben Sie eine E-Mail an die Verwaltung (60–80 Wörter).","points":["Stellen Sie sich kurz vor.","Warum interessieren Sie sich für die Wohnung? (weil …)","Bitten Sie um einen Termin für die Besichtigung.","Fragen Sie nach Haustieren."],"phrases":[{"de":"Sehr geehrte Damen und Herren","en":"Dear Sir or Madam"},{"de":"Ich habe Ihr Inserat gesehen und interessiere mich für die Wohnung.","en":"I saw your advert and I'm interested in the flat."},{"de":"Wäre eine Besichtigung am … möglich?","en":"Would a viewing on … be possible?"},{"de":"Ich möchte gerne wissen, ob …","en":"I would like to know whether …"},{"de":"Freundliche Grüsse","en":"Kind regards"}],"model":"Sehr geehrte Damen und Herren\n\nIch habe Ihr Inserat für die 3½-Zimmer-Wohnung in Veltheim gesehen und interessiere mich sehr für die Wohnung. Ich heisse Carla Ferreira, bin 32 Jahre alt und arbeite bei einer Logistikfirma in Winterthur. Ich suche eine grössere Wohnung, weil meine jetzige Wohnung nur ein Zimmer hat. Wäre eine Besichtigung am Samstag möglich? Ausserdem möchte ich gerne wissen, ob eine Katze erlaubt ist.\n\nFreundliche Grüsse\nCarla Ferreira","audio":"d960913f4533"},"speaking":{"task":"Bei der Besichtigung – beantworten Sie die Fragen der Verwaltung. Benutzen Sie weil, dass oder wenn.","phrases":[{"de":"Ist die Wohnung noch frei?","en":"Is the flat still available?","audio":"efc9d32fcafc"},{"de":"Wie hoch sind die Nebenkosten?","en":"How high are the additional costs?","audio":"d5d7224185e3"},{"de":"Ab wann ist die Wohnung frei?","en":"From when is the flat available?","audio":"728e0e8b8d2c"},{"de":"Wann kann ich die Wohnung besichtigen?","en":"When can I view the flat?","audio":"03e9d61693b7"},{"de":"Mir gefällt, dass …","en":"I like that …","audio":null}],"prompts":[{"q":"Warum suchen Sie eine neue Wohnung?","model":"Ich suche eine neue Wohnung, weil meine Wohnung zu klein ist und weil ich näher bei der Arbeit wohnen möchte.","aq":"1ea02ab8891c","am":"e23095715351"},{"q":"Wie gefällt Ihnen die Wohnung?","model":"Sie gefällt mir sehr gut. Ich finde super, dass sie so hell ist und einen Balkon hat.","aq":"940358669aa0","am":"d06be6d24a76"},{"q":"Wann möchten Sie einziehen?","model":"Wenn es möglich ist, möchte ich am ersten Dezember einziehen.","aq":"b39ec88faae8","am":"6b93d6049a35"},{"q":"Haben Sie noch Fragen?","model":"Ja. Ich möchte wissen, wie hoch die Nebenkosten sind und ob ich eine Katze haben darf.","aq":"89e0920c4c2d","am":"ee4585a2b732"}]}},{"id":3,"title":"Beim Arzt","subtitle":"Termine, Beschwerden und gute Ratschläge","level":"A2","theme":"Gesundheit","focus":"Modalverben im Präsens und Präteritum","goals":[{"de":"Ich kann telefonisch einen Termin vereinbaren.","en":"I can make an appointment by phone."},{"de":"Ich kann meine Beschwerden beschreiben und die Anweisungen der Ärztin verstehen.","en":"I can describe my symptoms and understand the doctor's instructions."},{"de":"Ich kann sagen, was ich muss, kann, darf und soll.","en":"I can say what I must, can, may and should do."}],"vocab":[{"id":"3-0","de":"der Hausarzt","forms":"Hausärzte","en":"GP, family doctor","ex":"Ich habe noch keinen Hausarzt in der Schweiz.","exEn":"I don't have a GP in Switzerland yet.","aw":"90a9408c720d","ae":"96adb2e6955e"},{"id":"3-1","de":"die Praxis","forms":"Praxen","en":"(doctor's) practice","ex":"Die Praxis ist am Mittwochnachmittag geschlossen.","exEn":"The practice is closed on Wednesday afternoon.","aw":"19514f645d67","ae":"d8e40e98abb0"},{"id":"3-2","de":"einen Termin vereinbaren","forms":"hat vereinbart","en":"to make an appointment","ex":"Ich möchte einen Termin vereinbaren.","exEn":"I'd like to make an appointment.","aw":"5e5b26f2d81b","ae":"59fe1956ddc9"},{"id":"3-3","de":"die Beschwerden","forms":"(Pl.)","en":"symptoms, complaints","ex":"Was für Beschwerden haben Sie?","exEn":"What symptoms do you have?","aw":"f801a96e5c8c","ae":"0efa5b683fd1"},{"id":"3-4","de":"das Fieber","forms":"–","en":"fever","ex":"Ich habe seit gestern Fieber.","exEn":"I've had a fever since yesterday.","aw":"6b07b3eabf3b","ae":"4758776775d6"},{"id":"3-5","de":"der Husten","forms":"–","en":"cough","ex":"Der Husten ist in der Nacht schlimmer.","exEn":"The cough is worse at night.","aw":"8c297b0cf4b7","ae":"828de14a3bcf"},{"id":"3-6","de":"die Halsschmerzen","forms":"(Pl.)","en":"sore throat","ex":"Ich habe starke Halsschmerzen.","exEn":"I have a bad sore throat.","aw":"2f41b59dd35e","ae":"b5b4c21da5c3"},{"id":"3-7","de":"die Erkältung","forms":"-en","en":"cold","ex":"Das ist nur eine Erkältung.","exEn":"It's just a cold.","aw":"c191c6ce09f2","ae":"1f168219ea4a"},{"id":"3-8","de":"wehtun","forms":"hat wehgetan","en":"to hurt","ex":"Mein Rücken tut weh.","exEn":"My back hurts.","aw":"eafda5c11c58","ae":"af2bc309d0b9"},{"id":"3-9","de":"sich krankmelden","forms":"hat sich krankgemeldet","en":"to call in sick","ex":"Ich habe mich heute Morgen krankgemeldet.","exEn":"I called in sick this morning.","aw":"845d0d0867d5","ae":"c394f0facdba"},{"id":"3-10","de":"das Arztzeugnis","forms":"-se","en":"doctor's certificate (CH)","ex":"Mein Chef braucht ein Arztzeugnis.","exEn":"My boss needs a doctor's certificate.","aw":"c62869e7f7e9","ae":"e352b15aacd4"},{"id":"3-11","de":"das Rezept","forms":"-e","en":"prescription","ex":"Mit diesem Rezept gehen Sie in die Apotheke.","exEn":"Take this prescription to the pharmacy.","aw":"d70146f0f5f8","ae":"3ee1c55bc2c6"},{"id":"3-12","de":"die Apotheke","forms":"-n","en":"pharmacy","ex":"Die Apotheke am Bahnhof ist auch am Sonntag offen.","exEn":"The pharmacy at the station is also open on Sundays.","aw":"480793244892","ae":"2ef659382cfd"},{"id":"3-13","de":"das Medikament","forms":"-e","en":"medicine","ex":"Brauche ich für dieses Medikament ein Rezept?","exEn":"Do I need a prescription for this medicine?","aw":"d2f7b2410406","ae":"cc5ea703419d"},{"id":"3-14","de":"einnehmen","forms":"hat eingenommen","en":"to take (medicine)","ex":"Nehmen Sie die Tabletten nach dem Essen ein.","exEn":"Take the tablets after meals.","aw":"9fbae18254a9","ae":"046895818c7c"},{"id":"3-15","de":"sich ausruhen","forms":"hat sich ausgeruht","en":"to rest","ex":"Sie sollten sich ein paar Tage ausruhen.","exEn":"You should rest for a few days.","aw":"6faa4f7bb253","ae":"9e995d140a0d"},{"id":"3-16","de":"der Notfall","forms":"Notfälle","en":"emergency","ex":"Im Notfall rufen Sie die Nummer 144 an.","exEn":"In an emergency, call 144.","aw":"d9f5a34de9ec","ae":"7653d8673a9b"},{"id":"3-17","de":"das Spital","forms":"Spitäler","en":"hospital (CH)","ex":"Er liegt seit Montag im Spital.","exEn":"He has been in hospital since Monday.","aw":"e44795216ea1","ae":"bce7b81db29b"},{"id":"3-18","de":"die Versichertenkarte","forms":"-n","en":"health insurance card","ex":"Bitte bringen Sie Ihre Versichertenkarte mit.","exEn":"Please bring your insurance card.","aw":"5f1fcc73b776","ae":"26d2b9ef2b90"},{"id":"3-19","de":"die Franchise","forms":"-n","en":"annual deductible (CH)","ex":"Ich habe eine hohe Franchise gewählt.","exEn":"I chose a high deductible.","aw":"4e43dc0aed3b","ae":"587105a7fc56"}],"swiss":[{"ch":"das Spital","std":"das Krankenhaus","en":"hospital"},{"ch":"das Arztzeugnis","std":"das Attest","en":"doctor's certificate"},{"ch":"die Franchise","std":"die Selbstbeteiligung","en":"the amount you pay yourself each year before insurance pays"},{"ch":"144","std":"–","en":"ambulance (Sanität); 112 also works"}],"dialogue":{"title":"In der Arztpraxis","intro":"Carla ist krank. Sie ist bei Dr. Keller, ihrem neuen Hausarzt.","speakers":{"F":"Carla","M":"Dr. Keller"},"lines":[{"s":"M","de":"Guten Tag, Frau Ferreira. Was fehlt Ihnen denn?","en":"Hello, Ms Ferreira. What seems to be the problem?","audio":"4375deae2898"},{"s":"F","de":"Guten Tag. Ich habe seit drei Tagen Halsschmerzen und Husten. Und gestern Abend hatte ich Fieber.","en":"Hello. I've had a sore throat and a cough for three days. And yesterday evening I had a fever.","audio":"b4d587d2c410"},{"s":"M","de":"Wie hoch war das Fieber?","en":"How high was the fever?","audio":"4d8d86332d90"},{"s":"F","de":"Achtunddreissig Komma fünf. Ich konnte die ganze Nacht nicht schlafen.","en":"Thirty-eight point five. I couldn't sleep all night.","audio":"b3149e70e4a4"},{"s":"M","de":"Das tut mir leid. Mussten Sie heute arbeiten?","en":"I'm sorry. Did you have to work today?","audio":"1859889f103a"},{"s":"F","de":"Nein, ich habe mich heute Morgen krankgemeldet. Aber mein Chef will ein Arztzeugnis.","en":"No, I called in sick this morning. But my boss wants a doctor's certificate.","audio":"7d21b6973635"},{"s":"M","de":"Kein Problem, das bekommen Sie. Darf ich mal in Ihren Hals schauen? Machen Sie bitte den Mund auf.","en":"No problem, you'll get that. May I have a look at your throat? Please open your mouth.","audio":"88d1ec6c2303"},{"s":"M","de":"Ja, der Hals ist ziemlich rot.","en":"Yes, the throat is quite red.","audio":"cd71011d22b3"},{"s":"F","de":"Ist es etwas Schlimmes?","en":"Is it something serious?","audio":"898608e272e6"},{"s":"M","de":"Nein, keine Sorge. Es ist eine starke Erkältung. Sie müssen keine Antibiotika nehmen.","en":"No, don't worry. It's a bad cold. You don't need to take antibiotics.","audio":"5111fd40ddd3"},{"s":"F","de":"Was kann ich denn machen?","en":"So what can I do?","audio":"4740954f6293"},{"s":"M","de":"Sie sollten viel Tee trinken und sich ausruhen. Für den Hals gebe ich Ihnen ein Rezept für Lutschtabletten.","en":"You should drink lots of tea and rest. For your throat I'll give you a prescription for lozenges.","audio":"4a7f82c93a2a"},{"s":"F","de":"Darf ich am Wochenende Sport machen? Ich wollte eigentlich joggen gehen.","en":"May I do sport at the weekend? I was actually planning to go jogging.","audio":"9d4671c63038"},{"s":"M","de":"Nein, lieber nicht. Sie dürfen erst wieder Sport machen, wenn das Fieber weg ist.","en":"No, better not. You may only do sport again once the fever has gone.","audio":"7b9b34ff4773"},{"s":"F","de":"Okay. Wie oft muss ich die Tabletten nehmen?","en":"Okay. How often do I have to take the tablets?","audio":"4fc94c15c62a"},{"s":"M","de":"Sie können alle drei Stunden eine Tablette nehmen, aber nicht mehr als sechs pro Tag.","en":"You can take one tablet every three hours, but not more than six a day.","audio":"1391f8995014"},{"s":"F","de":"Und wie lange bin ich krankgeschrieben?","en":"And how long am I on sick leave?","audio":"69ba4bf4ab0e"},{"s":"M","de":"Bis Freitag. Wenn es Ihnen am Montag nicht besser geht, kommen Sie bitte wieder.","en":"Until Friday. If you're not feeling better on Monday, please come back.","audio":"0ba2a8d5c091"},{"s":"F","de":"Gut, das mache ich. Vielen Dank!","en":"Good, I'll do that. Thank you very much!","audio":"2f260bd239cb"},{"s":"M","de":"Gute Besserung, Frau Ferreira!","en":"Get well soon, Ms Ferreira!","audio":"1bba5ca67e14"}],"questions":[{"type":"tf","q":"Carla hat seit einer Woche Halsschmerzen.","a":false,"why":"Seit drei Tagen."},{"type":"tf","q":"Carla konnte in der Nacht nicht schlafen.","a":true,"why":""},{"type":"mc","q":"Was möchte Carlas Chef?","options":["ein Rezept","ein Arztzeugnis","eine Versichertenkarte"],"a":1},{"type":"mc","q":"Was soll Carla machen?","options":["am Wochenende joggen","viel Tee trinken und sich ausruhen","Antibiotika nehmen"],"a":1},{"type":"mc","q":"Wann soll Carla wiederkommen?","options":["morgen","am Freitag","am Montag, wenn es ihr nicht besser geht"],"a":2}]},"grammar":{"title":"Modalverben – können, müssen, dürfen, sollen, wollen, möchten","summary":"Modalverben stehen auf Position 2, der Infinitiv steht am Ende.","sections":[{"h":"Was bedeuten die Modalverben?","table":[["Modalverb","Bedeutung","Beispiel"],["können","Fähigkeit, Möglichkeit","Ich kann nicht schlafen."],["müssen","Notwendigkeit, Pflicht","Ich muss zum Arzt gehen."],["dürfen","Erlaubnis","Darf ich hier parkieren?"],["nicht dürfen","Verbot","Im Spital darf man nicht rauchen."],["sollen","Rat oder Auftrag von einer anderen Person","Die Ärztin sagt, ich soll mich ausruhen."],["wollen","starker Wunsch, Plan","Ich will wieder gesund werden."],["möchten","höflicher Wunsch","Ich möchte einen Termin."]]},{"h":"Konjugation im Präsens","text":"Bei **ich** und **er/sie/es** haben Modalverben **keine Endung**, und oft ändert sich der Vokal im Singular.","table":[["Person","können","müssen","dürfen","sollen","wollen","möchten"],["ich","kann","muss","darf","soll","will","möchte"],["du","kannst","musst","darfst","sollst","willst","möchtest"],["er/sie/es","kann","muss","darf","soll","will","möchte"],["wir","können","müssen","dürfen","sollen","wollen","möchten"],["ihr","könnt","müsst","dürft","sollt","wollt","möchtet"],["sie/Sie","können","müssen","dürfen","sollen","wollen","möchten"]]},{"h":"Die Satzklammer","text":"Das Modalverb steht auf **Position 2** (in der W-Frage und im Aussagesatz) oder auf **Position 1** (Ja/Nein-Frage). Der **Infinitiv** steht am Ende.","examples":[{"de":"Ich ==muss== heute zum Arzt ==gehen==.","en":"I have to go to the doctor today.","audio":"06c7e3c5f37a"},{"de":"Wann ==können== Sie in die Praxis ==kommen==?","en":"When can you come to the practice?","audio":"2d0d608f6dff"},{"de":"==Darf== ich am Wochenende Sport ==machen==?","en":"May I do sport at the weekend?","audio":"a36d56317178"}]},{"h":"Präteritum – ohne Umlaut","text":"In der Vergangenheit benutzt man bei Modalverben fast immer das **Präteritum**. Die Endung ist **-te**, und der Umlaut fällt weg. Für **möchten** benutzt man in der Vergangenheit **wollen**.","table":[["Person","können","müssen","dürfen","sollen","wollen"],["ich","konnte","musste","durfte","sollte","wollte"],["du","konntest","musstest","durftest","solltest","wolltest"],["er/sie/es","konnte","musste","durfte","sollte","wollte"],["wir","konnten","mussten","durften","sollten","wollten"],["ihr","konntet","musstet","durftet","solltet","wolltet"],["sie/Sie","konnten","mussten","durften","sollten","wollten"]],"examples":[{"de":"Ich ==konnte== die ganze Nacht nicht ==schlafen==.","en":"I couldn't sleep all night.","audio":"54f6b6e8aea0"},{"de":"Ich ==wollte== eigentlich joggen ==gehen==.","en":"I was actually planning to go jogging.","audio":"537619e57648"}]},{"h":"Ratschläge mit sollte","text":"Für einen freundlichen Rat benutzt man oft **sollte** (Konjunktiv II): *Sie sollten sich ausruhen. Du solltest mehr trinken.* Mehr dazu in Lektion 6."}],"tip":"Achtung: „nicht müssen\" ist nicht „nicht dürfen\"! Sie müssen keine Antibiotika nehmen = es ist nicht nötig. Sie dürfen keinen Sport machen = es ist verboten."},"exercises":[{"type":"choice","title":"Welches Modalverb passt?","items":[{"q":"Die Ärztin sagt, ich ___ viel Wasser trinken.","options":["soll","darf","kann"],"a":0,"full":"Die Ärztin sagt, ich soll viel Wasser trinken.","audio":"4a2c1524d2d5"},{"q":"Im Spital ___ man nicht rauchen.","options":["darf","muss","will"],"a":0,"full":"Im Spital darf man nicht rauchen.","audio":"2bf8272b9f77"},{"q":"___ Sie mir bitte Ihre Versichertenkarte geben?","options":["Können","Müssen","Dürfen"],"a":0,"full":"Können Sie mir bitte Ihre Versichertenkarte geben?","audio":"40ddd9a03b0d"},{"q":"Sie haben keine Infektion. Sie ___ keine Antibiotika nehmen.","options":["müssen","dürfen","wollen"],"a":0,"full":"Sie haben keine Infektion. Sie müssen keine Antibiotika nehmen.","audio":"5bbe06d7fcc9"},{"q":"Gestern ___ ich nicht schlafen, weil ich so stark husten musste.","options":["konnte","durfte","sollte"],"a":0,"full":"Gestern konnte ich nicht schlafen, weil ich so stark husten musste.","audio":"3d89930fd39f"},{"q":"Mein Chef ___ unbedingt ein Arztzeugnis sehen.","options":["will","darf","soll"],"a":0,"full":"Mein Chef will unbedingt ein Arztzeugnis sehen.","audio":"53cc73415e9a"},{"q":"Als Kind ___ ich jeden Tag Gemüse essen – meine Mutter war sehr streng.","options":["musste","konnte","wollte"],"a":0,"full":"Als Kind musste ich jeden Tag Gemüse essen – meine Mutter war sehr streng.","audio":"c35e1d3c24d0"},{"q":"___ ich hier parkieren? – Ja, aber nur für Patienten.","options":["Darf","Muss","Soll"],"a":0,"full":"Darf ich hier parkieren? – Ja, aber nur für Patienten.","audio":"35162c6c7028"}]},{"type":"gap","title":"Konjugieren Sie das Modalverb","items":[{"q":"Du ___ dich ausruhen. (sollen)","a":["sollst"],"full":"Du sollst dich ausruhen.","audio":"17c9cae65d17"},{"q":"___ ihr morgen zum Arzt gehen? (müssen)","a":["Müsst"],"full":"Müsst ihr morgen zum Arzt gehen?","audio":"8f876d3ddf6c"},{"q":"Er ___ leider nicht kommen. (können)","a":["kann"],"full":"Er kann leider nicht kommen.","audio":"fbfa464341c4"},{"q":"Wir ___ gestern um acht Uhr in der Praxis sein. (müssen, Präteritum)","a":["mussten"],"full":"Wir mussten gestern um acht Uhr in der Praxis sein.","audio":"c62a40ccf21a"},{"q":"Ich ___ bitte einen Termin vereinbaren. (möchten)","a":["möchte"],"full":"Ich möchte bitte einen Termin vereinbaren.","audio":"6cd96b4b9605"},{"q":"Carla ___ letzte Woche keinen Sport machen. (dürfen, Präteritum)","a":["durfte"],"full":"Carla durfte letzte Woche keinen Sport machen.","audio":"308d8b253e08"},{"q":"___ du heute Abend mitkommen? (wollen)","a":["Willst"],"full":"Willst du heute Abend mitkommen?","audio":"ba5c2848de15"}]},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Ich muss heute zum Arzt gehen.","Heute muss ich zum Arzt gehen."],"tokens":["Ich","muss","heute","zum","Arzt","gehen."],"audio":"06c7e3c5f37a"},{"a":["Kann ich morgen einen Termin bekommen?"],"tokens":["Kann","ich","morgen","einen","Termin","bekommen?"],"audio":"d18634f67ffb"},{"a":["Gestern konnte ich nicht zur Arbeit gehen.","Ich konnte gestern nicht zur Arbeit gehen."],"tokens":["Gestern","konnte","ich","nicht","zur","Arbeit","gehen."],"audio":"aa525063cfaf"},{"a":["Im Wartezimmer darf man nicht telefonieren.","Man darf im Wartezimmer nicht telefonieren."],"tokens":["Im","Wartezimmer","darf","man","nicht","telefonieren."],"audio":"81d7e0940b2f"},{"a":["Wie oft soll ich die Tabletten nehmen?"],"tokens":["Wie","oft","soll","ich","die","Tabletten","nehmen?"],"audio":"de217bae7f7d"}]},{"type":"match","title":"Problem und Ratschlag","items":[{"l":"Ich kann nicht schlafen.","r":"Du solltest abends keinen Kaffee trinken."},{"l":"Ich habe Rückenschmerzen.","r":"Du solltest nicht so lange sitzen."},{"l":"Ich habe hohes Fieber.","r":"Du solltest zum Arzt gehen."},{"l":"Ich bin immer müde.","r":"Du solltest früher ins Bett gehen."},{"l":"Ich habe Zahnschmerzen.","r":"Du solltest einen Termin beim Zahnarzt vereinbaren."}]},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Ich habe seit drei Tagen Fieber.","audio":"a08de445f1b7"},{"a":"Sie müssen die Tabletten nach dem Essen einnehmen.","audio":"8cca5bd1d3fe"},{"a":"Darf ich morgen wieder arbeiten?","audio":"e55d1cbfa731"},{"a":"Ich möchte gerne einen Termin vereinbaren.","audio":"50b61818e73d"}]}],"reading":{"title":"Krank in der Schweiz – was muss ich wissen?","kind":"Infotext","paras":[{"t":"Wenn Sie in der Schweiz krank sind, gehen Sie normalerweise zuerst zu Ihrer Hausärztin oder zu Ihrem Hausarzt. Viele Menschen haben bei der Krankenkasse ein Hausarztmodell. Dann müssen sie immer zuerst in die Hausarztpraxis gehen – dafür bezahlen sie jeden Monat weniger. Bei anderen Modellen muss man zuerst eine Telefonberatung anrufen.","audio":"6892be8b386c"},{"t":"Für kleine Probleme wie eine Erkältung oder Kopfschmerzen können Sie auch in eine Apotheke gehen. Die Apothekerinnen und Apotheker beraten Sie gern, und viele Medikamente kann man ohne Rezept kaufen.","audio":"748c18fe93e1"},{"t":"Im Notfall dürfen Sie nicht warten: Rufen Sie sofort die Nummer 144 an, oder gehen Sie auf die Notfallstation im Spital.","audio":"00962130adea"},{"t":"Wichtig: Die Krankenkasse bezahlt nicht alles. Jede erwachsene Person hat eine Franchise. Diesen Betrag muss man jedes Jahr selbst bezahlen – mindestens 300 Franken. Danach bezahlt man meistens noch zehn Prozent der Kosten selbst. Das nennt man Selbstbehalt.","audio":"28e19ea8eb93"},{"t":"Wenn Sie krank sind und nicht arbeiten können, müssen Sie sich sofort bei Ihrem Arbeitgeber krankmelden. Bei vielen Firmen braucht man ab dem dritten Tag ein Arztzeugnis.","audio":"27532f42f259"}],"glossary":[{"de":"das Hausarztmodell","en":"insurance model where you always see your GP first"},{"de":"die Telefonberatung","en":"medical advice line"},{"de":"beraten","en":"to advise"},{"de":"die Notfallstation","en":"emergency department"},{"de":"der Betrag","en":"amount"},{"de":"der Selbstbehalt","en":"co-payment (10 % of costs)"}],"questions":[{"type":"tf","q":"Mit einem Hausarztmodell geht man zuerst zur Hausärztin oder zum Hausarzt.","a":true,"why":""},{"type":"tf","q":"In der Apotheke bekommt man nur Medikamente mit Rezept.","a":false,"why":"Viele Medikamente kann man ohne Rezept kaufen."},{"type":"mc","q":"Was macht man im Notfall?","options":["Man ruft sofort die Nummer 144 an.","Man wartet bis zum nächsten Tag.","Man geht in die Apotheke."],"a":0},{"type":"mc","q":"Was ist die Franchise?","options":["ein Betrag, den man jedes Jahr selbst bezahlt","eine Telefonberatung","ein Arztzeugnis"],"a":0},{"type":"tf","q":"Bei vielen Firmen braucht man schon am ersten Tag ein Arztzeugnis.","a":false,"why":"Oft erst ab dem dritten Tag."}]},"writing":{"task":"Sie sind krank und können diese Woche nicht arbeiten. Schreiben Sie Ihrer Chefin eine E-Mail (60–80 Wörter).","points":["Sagen Sie, dass Sie krank sind.","Was haben Sie? Wie lange sind Sie krankgeschrieben?","Wer kann Ihre Arbeit machen?","Wann kommen Sie wieder?"],"phrases":[{"de":"Leider bin ich krank und kann nicht zur Arbeit kommen.","en":"Unfortunately I'm ill and can't come to work."},{"de":"Die Ärztin hat mich bis … krankgeschrieben.","en":"The doctor has signed me off sick until …"},{"de":"Das Arztzeugnis schicke ich Ihnen …","en":"I'll send you the doctor's certificate …"},{"de":"… kann meine Aufgaben übernehmen.","en":"… can take over my tasks."}],"model":"Sehr geehrte Frau Weber\n\nLeider bin ich krank und kann diese Woche nicht zur Arbeit kommen. Ich habe eine starke Erkältung mit Fieber. Ich war heute Morgen beim Arzt, und er hat mich bis Freitag krankgeschrieben. Das Arztzeugnis schicke ich Ihnen heute noch per E-Mail. Mein Kollege Luca kann die Lieferungen am Donnerstag kontrollieren – ich habe ihn schon informiert. Am Montag bin ich hoffentlich wieder im Büro.\n\nFreundliche Grüsse\nCarla Ferreira","audio":"742862a53733"},"speaking":{"task":"Sie rufen in der Arztpraxis an. Beantworten Sie die Fragen der Praxisassistentin.","phrases":[{"de":"Ich möchte gerne einen Termin vereinbaren.","en":"I'd like to make an appointment.","audio":"221eb03c7c97"},{"de":"Ich habe seit … Tagen …","en":"I've had … for … days.","audio":null},{"de":"Mir ist schlecht.","en":"I feel sick.","audio":"f42fcf8fdb52"},{"de":"Geht es auch etwas später?","en":"Would a bit later also work?","audio":"4023ad1531fa"},{"de":"Muss ich etwas mitbringen?","en":"Do I need to bring anything?","audio":"9bfe7a79f16a"}],"prompts":[{"q":"Praxis Dr. Keller, guten Tag. Was kann ich für Sie tun?","model":"Guten Tag, hier ist Carla Ferreira. Ich möchte gerne einen Termin vereinbaren.","aq":"7b5f3f8925cc","am":"fa5e9faf8a22"},{"q":"Was für Beschwerden haben Sie?","model":"Ich habe seit drei Tagen Halsschmerzen und Husten, und gestern hatte ich auch Fieber.","aq":"14f0d3a1cb51","am":"b147a7f42930"},{"q":"Können Sie morgen um halb neun kommen?","model":"Morgen früh muss ich leider arbeiten. Geht es auch am Nachmittag?","aq":"34e39b31f820","am":"6297eb010541"},{"q":"Gut, dann um fünfzehn Uhr. Haben Sie noch eine Frage?","model":"Ja, muss ich etwas mitbringen? – Ah, die Versichertenkarte. Vielen Dank, bis morgen!","aq":"591f0ab8e5f8","am":"001f8a007845"}]}},{"id":4,"title":"Einkaufen und reklamieren","subtitle":"Produkte vergleichen, umtauschen, sich beschweren","level":"A2","theme":"Einkaufen","focus":"Adjektivendungen, Komparativ und Superlativ","goals":[{"de":"Ich kann ein Produkt reklamieren und sagen, was nicht funktioniert.","en":"I can complain about a product and say what isn't working."},{"de":"Ich kann Produkte vergleichen (günstiger, besser, am schnellsten).","en":"I can compare products."},{"de":"Ich kann Regeln für Umtausch und Rückgabe verstehen.","en":"I can understand exchange and return rules."}],"vocab":[{"id":"4-0","de":"die Reklamation","forms":"-en","en":"complaint (about a product)","ex":"Ich habe eine Reklamation.","exEn":"I have a complaint.","aw":"bb984d3681bd","ae":"81434eb9227c"},{"id":"4-1","de":"reklamieren","forms":"hat reklamiert","en":"to complain about, return as faulty","ex":"Ich möchte diesen Wasserkocher reklamieren.","exEn":"I'd like to return this kettle, it's faulty.","aw":"a0dcc02c2c62","ae":"152d035c5d20"},{"id":"4-2","de":"sich beschweren","forms":"hat sich beschwert","en":"to complain","ex":"Er hat sich beim Kundendienst beschwert.","exEn":"He complained to customer service.","aw":"9d479f7eaf8c","ae":"7e4fee877ec9"},{"id":"4-3","de":"umtauschen","forms":"hat umgetauscht","en":"to exchange","ex":"Kann ich die Jacke umtauschen?","exEn":"Can I exchange the jacket?","aw":"0d1615d8032b","ae":"f4beefeb5cbb"},{"id":"4-4","de":"die Quittung","forms":"-en","en":"receipt","ex":"Haben Sie die Quittung noch?","exEn":"Do you still have the receipt?","aw":"b1aab9d8f4a6","ae":"01c089f4e5c7"},{"id":"4-5","de":"die Garantie","forms":"-n","en":"warranty, guarantee","ex":"Das Gerät hat zwei Jahre Garantie.","exEn":"The appliance has a two-year warranty.","aw":"8898dac0dfb1","ae":"6cdbff7db849"},{"id":"4-6","de":"das Gerät","forms":"-e","en":"appliance, device","ex":"Das Gerät ist nach einer Woche kaputtgegangen.","exEn":"The appliance broke after a week.","aw":"9f61e9ead914","ae":"b392433aae6d"},{"id":"4-7","de":"kaputt","forms":"–","en":"broken","ex":"Mein Handy ist schon wieder kaputt.","exEn":"My phone is broken again.","aw":"019c649b646d","ae":"f19b80d47afa"},{"id":"4-8","de":"funktionieren","forms":"hat funktioniert","en":"to work, to function","ex":"Die Kaffeemaschine funktioniert nicht mehr.","exEn":"The coffee machine doesn't work any more.","aw":"5b71bb5112bd","ae":"952dd6a526b1"},{"id":"4-9","de":"die Grösse","forms":"-n","en":"size","ex":"Haben Sie das auch in einer anderen Grösse?","exEn":"Do you have this in another size?","aw":"7e2b8d76b723","ae":"3f792ae937e0"},{"id":"4-10","de":"anprobieren","forms":"hat anprobiert","en":"to try on","ex":"Kann ich die Hose anprobieren?","exEn":"Can I try on the trousers?","aw":"580f2f4f8497","ae":"b05d15cce348"},{"id":"4-11","de":"passen","forms":"hat gepasst","en":"to fit","ex":"Die Schuhe passen mir leider nicht.","exEn":"Unfortunately the shoes don't fit me.","aw":"04b29c25e7f6","ae":"9d3017b0a846"},{"id":"4-12","de":"die Aktion","forms":"-en","en":"special offer (CH)","ex":"Die Äpfel sind diese Woche in Aktion.","exEn":"Apples are on special offer this week.","aw":"7cb046ca11b3","ae":"dcb72053e8d8"},{"id":"4-13","de":"günstig","forms":"–","en":"inexpensive, good value","ex":"Im Internet ist es oft günstiger.","exEn":"It's often cheaper online.","aw":"080c7e6aa331","ae":"2fd6728e0c89"},{"id":"4-14","de":"der Kundendienst","forms":"–","en":"customer service","ex":"Der Kundendienst hat mir sofort geholfen.","exEn":"Customer service helped me right away.","aw":"d582c3852b06","ae":"1c2433f830b7"},{"id":"4-15","de":"das Geld zurückbekommen","forms":"hat zurückbekommen","en":"to get your money back","ex":"Bekomme ich mein Geld zurück?","exEn":"Do I get my money back?","aw":"cb3ee1b4a232","ae":"d7be5c3da750"},{"id":"4-16","de":"der Gutschein","forms":"-e","en":"voucher","ex":"Sie bekommen einen Gutschein über fünfzig Franken.","exEn":"You get a voucher for fifty francs.","aw":"ab395f9059e3","ae":"1a7e959ce99a"},{"id":"4-17","de":"die Kasse","forms":"-n","en":"checkout, till","ex":"Bitte bezahlen Sie vorne an der Kasse.","exEn":"Please pay at the checkout at the front.","aw":"a9796659fd7e","ae":"6b662859703e"},{"id":"4-18","de":"enttäuscht","forms":"–","en":"disappointed","ex":"Ich bin von der Qualität enttäuscht.","exEn":"I'm disappointed with the quality.","aw":"72f75fde2b10","ae":"8e3218d306a8"},{"id":"4-19","de":"die Verpackung","forms":"-en","en":"packaging","ex":"Bitte bringen Sie das Gerät in der Originalverpackung zurück.","exEn":"Please bring the appliance back in its original packaging.","aw":"d7ed8c14cf77","ae":"1b7289fac992"}],"swiss":[{"ch":"die Aktion","std":"das Sonderangebot","en":"special offer"},{"ch":"TWINT","std":"–","en":"Swiss mobile payment app, accepted almost everywhere"},{"ch":"das Portemonnaie","std":"der Geldbeutel","en":"wallet, purse"}],"dialogue":{"title":"Ein kaputter Wasserkocher","intro":"Carla hat letzte Woche einen Wasserkocher gekauft. Jetzt ist sie wieder im Geschäft.","speakers":{"F":"Carla","M":"Verkäufer"},"lines":[{"s":"M","de":"Guten Tag. Kann ich Ihnen helfen?","en":"Hello. Can I help you?","audio":"585f4b74672c"},{"s":"F","de":"Guten Tag. Ich habe letzte Woche diesen Wasserkocher gekauft, aber er funktioniert nicht mehr.","en":"Hello. I bought this kettle last week, but it doesn't work any more.","audio":"0d369fa88520"},{"s":"M","de":"Oh, das tut mir leid. Was ist denn das Problem?","en":"Oh, I'm sorry. What's the problem?","audio":"70f8b660032b"},{"s":"F","de":"Das Wasser wird nicht mehr heiss. Das rote Licht geht an, aber sonst passiert nichts.","en":"The water doesn't get hot any more. The red light comes on, but nothing else happens.","audio":"5e4011cbc2da"},{"s":"M","de":"Haben Sie die Quittung dabei?","en":"Do you have the receipt with you?","audio":"e8ab6e8259d0"},{"s":"F","de":"Ja, hier ist sie.","en":"Yes, here it is.","audio":"197c9617712a"},{"s":"M","de":"Danke. Das Gerät hat zwei Jahre Garantie. Möchten Sie einen neuen Wasserkocher oder lieber Ihr Geld zurück?","en":"Thanks. The appliance has a two-year warranty. Would you like a new kettle or would you prefer your money back?","audio":"43f817f7dcb4"},{"s":"F","de":"Gibt es auch ein anderes Modell? Der alte Wasserkocher war ziemlich laut.","en":"Is there another model too? The old kettle was quite loud.","audio":"fc3c5833fef2"},{"s":"M","de":"Ja, hier haben wir zum Beispiel diesen weissen Wasserkocher. Er ist leiser und schneller als Ihr altes Modell.","en":"Yes, here we have this white kettle, for example. It's quieter and faster than your old model.","audio":"f98f5ba9b31a"},{"s":"F","de":"Und was kostet er?","en":"And how much does it cost?","audio":"26cf90ee6d4b"},{"s":"M","de":"Neunundvierzig Franken. Er ist also zehn Franken teurer.","en":"Forty-nine francs. So it's ten francs more expensive.","audio":"b276fa78a45c"},{"s":"F","de":"Und der silberne da hinten?","en":"And the silver one back there?","audio":"c6db0b660909"},{"s":"M","de":"Der ist am günstigsten, nur fünfunddreissig Franken. Aber er ist kleiner – nur ein Liter.","en":"That's the cheapest, only thirty-five francs. But it's smaller – only one litre.","audio":"341e4e7f8241"},{"s":"F","de":"Das ist mir zu klein, ich trinke sehr viel Tee! Ich nehme den weissen.","en":"That's too small for me, I drink a lot of tea! I'll take the white one.","audio":"9ba01686e744"},{"s":"M","de":"Gute Wahl. Dann bezahlen Sie nur die Differenz, also zehn Franken.","en":"Good choice. Then you only pay the difference, so ten francs.","audio":"1f123a63517b"},{"s":"F","de":"Kann ich mit TWINT bezahlen?","en":"Can I pay with TWINT?","audio":"3368e11aef5f"},{"s":"M","de":"Natürlich, hier ist der QR-Code.","en":"Of course, here's the QR code.","audio":"8e438593f761"},{"s":"F","de":"Super. Vielen Dank für den guten Service!","en":"Great. Thank you for the good service!","audio":"1554c02d7d0e"}],"questions":[{"type":"tf","q":"Carla hat den Wasserkocher vor einem Jahr gekauft.","a":false,"why":"Sie hat ihn letzte Woche gekauft."},{"type":"mc","q":"Was ist das Problem?","options":["Er ist zu laut.","Das Wasser wird nicht heiss.","Das Licht funktioniert nicht."],"a":1},{"type":"mc","q":"Warum möchte Carla ein anderes Modell?","options":["Das alte Modell war zu laut.","Das alte Modell war zu teuer.","Das alte Modell war zu klein."],"a":0},{"type":"tf","q":"Der silberne Wasserkocher ist am günstigsten.","a":true,"why":""},{"type":"mc","q":"Wie viel bezahlt Carla heute?","options":["nichts","zehn Franken","neunundvierzig Franken"],"a":1}]},"grammar":{"title":"Adjektivendungen, Komparativ und Superlativ","summary":"Vor einem Nomen braucht das Adjektiv eine Endung.","sections":[{"h":"Adjektiv mit oder ohne Endung?","text":"Nach **sein, werden, bleiben** hat das Adjektiv **keine Endung**: *Der Wasserkocher ist neu.*\n**Vor** einem Nomen hat es immer eine Endung: *der neu==e== Wasserkocher, ein neu==er== Wasserkocher.*"},{"h":"Nach dem bestimmten Artikel (der, die, das, dieser …)","text":"Die Regel ist einfach: **-e** im Nominativ Singular und im Akkusativ bei *die* und *das*. Überall sonst: **-en**.","table":[["Kasus","maskulin","feminin","neutral","Plural"],["Nominativ","der neue Tisch","die neue Jacke","das neue Handy","die neuen Schuhe"],["Akkusativ","den neuen Tisch","die neue Jacke","das neue Handy","die neuen Schuhe"],["Dativ","dem neuen Tisch","der neuen Jacke","dem neuen Handy","den neuen Schuhen"]]},{"h":"Nach dem unbestimmten Artikel (ein, kein, mein …)","text":"Wenn der Artikel **keine Endung** hat (*ein Tisch, ein Handy*), zeigt das Adjektiv das Genus: **-er** (maskulin) und **-es** (neutral).","table":[["Kasus","maskulin","feminin","neutral","Plural"],["Nominativ","ein neuer Tisch","eine neue Jacke","ein neues Handy","keine neuen Schuhe"],["Akkusativ","einen neuen Tisch","eine neue Jacke","ein neues Handy","keine neuen Schuhe"],["Dativ","einem neuen Tisch","einer neuen Jacke","einem neuen Handy","keinen neuen Schuhen"]]},{"h":"Vergleichen – Komparativ und Superlativ","text":"**Komparativ:** Adjektiv + **-er** (+ *als*). **Superlativ:** **am** + Adjektiv + **-sten**. Viele kurze Adjektive bekommen einen Umlaut.\nGleich ist: **so … wie** (*Die Jacke ist so teuer wie die Hose.*).","table":[["Grundform","Komparativ","Superlativ"],["schnell","schneller","am schnellsten"],["günstig","günstiger","am günstigsten"],["teuer","teurer","am teuersten"],["gross","grösser","am grössten"],["alt","älter","am ältesten"],["gut","besser","am besten"],["viel","mehr","am meisten"],["gern","lieber","am liebsten"],["hoch","höher","am höchsten"]],"examples":[{"de":"Der weisse Wasserkocher ist ==leiser als== der alte.","en":"The white kettle is quieter than the old one.","audio":"35dfd6042325"},{"de":"Der silberne ist ==am günstigsten==.","en":"The silver one is the cheapest.","audio":"e0762b90ed12"},{"de":"Ich trinke ==lieber== Tee ==als== Kaffee.","en":"I prefer tea to coffee.","audio":"430a14e449cb"}]}],"tip":"Auch der Komparativ braucht vor dem Nomen eine Endung: ein kleiner==er== Wasserkocher, die günstiger==e== Jacke, das beste Angebot."},"exercises":[{"type":"choice","title":"Welche Endung ist richtig?","items":[{"q":"Ich möchte den ___ Wasserkocher zurückgeben.","options":["kaputten","kaputte","kaputter"],"a":0,"full":"Ich möchte den kaputten Wasserkocher zurückgeben.","audio":"57fc99c44b68"},{"q":"Haben Sie diese Jacke auch in einer ___ Grösse?","options":["kleineren","kleinere","kleiner"],"a":0,"full":"Haben Sie diese Jacke auch in einer kleineren Grösse?","audio":"ea0489cd30b1"},{"q":"Das ist ein sehr ___ Angebot!","options":["gutes","guter","gute"],"a":0,"full":"Das ist ein sehr gutes Angebot!","audio":"00e8ee6e5974"},{"q":"Die ___ Schuhe passen mir nicht.","options":["neuen","neue","neuer"],"a":0,"full":"Die neuen Schuhe passen mir nicht.","audio":"136859c4cf69"},{"q":"Ich suche einen ___ Tisch für meine Küche.","options":["runden","runder","runde"],"a":0,"full":"Ich suche einen runden Tisch für meine Küche.","audio":"cfd86636dfc2"},{"q":"Er hat mit einer ___ Kreditkarte bezahlt.","options":["alten","alte","alter"],"a":0,"full":"Er hat mit einer alten Kreditkarte bezahlt.","audio":"44e6ab921a6d"},{"q":"Wo ist die ___ Filiale?","options":["nächste","nächsten","nächster"],"a":0,"full":"Wo ist die nächste Filiale?","audio":"3f477ca6be92"},{"q":"Das ___ Handy ist leider schon kaputt.","options":["neue","neues","neuen"],"a":0,"full":"Das neue Handy ist leider schon kaputt.","audio":"922b24f8f06a"}]},{"type":"gap","title":"Komparativ oder Superlativ","items":[{"q":"Der weisse Wasserkocher ist ___ als der schwarze. (leise)","a":["leiser"],"full":"Der weisse Wasserkocher ist leiser als der schwarze.","audio":"24e1dd6c2789"},{"q":"Im Internet ist es oft ___ als im Geschäft. (günstig)","a":["günstiger"],"full":"Im Internet ist es oft günstiger als im Geschäft.","audio":"ae324bce89e9"},{"q":"Diese Jacke gefällt mir ___ als die blaue. (gut)","a":["besser"],"full":"Diese Jacke gefällt mir besser als die blaue.","audio":"a9798721a438"},{"q":"Welcher Supermarkt ist am ___? (billig)","a":["billigsten"],"full":"Welcher Supermarkt ist am billigsten?","audio":"f0fe05682d50"},{"q":"Ich trinke ___ Tee als Kaffee. (gern)","a":["lieber"],"full":"Ich trinke lieber Tee als Kaffee.","audio":"430a14e449cb"},{"q":"Die Schuhe sind zu klein. Haben Sie sie eine Nummer ___? (gross)","a":["grösser"],"full":"Die Schuhe sind zu klein. Haben Sie sie eine Nummer grösser?","audio":"5ed52a17243f"},{"q":"Zürich ist ___ als Winterthur. (teuer)","a":["teurer"],"full":"Zürich ist teurer als Winterthur.","audio":"2be5a5e9c00e"}]},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Ich möchte diese schwarze Hose umtauschen."],"tokens":["Ich","möchte","diese","schwarze","Hose","umtauschen."],"audio":"0410e991cac1"},{"a":["Haben Sie den Pullover auch in einer anderen Farbe?"],"tokens":["Haben","Sie","den","Pullover","auch","in","einer","anderen","Farbe?"],"audio":"e50170d9f378"},{"a":["Der neue Wasserkocher ist leiser als der alte."],"tokens":["Der","neue","Wasserkocher","ist","leiser","als","der","alte."],"audio":"f34d739762d4"},{"a":["Kann ich die blaue Jacke anprobieren?"],"tokens":["Kann","ich","die","blaue","Jacke","anprobieren?"],"audio":"40d628e8f478"},{"a":["Das ist das günstigste Modell im Geschäft."],"tokens":["Das","ist","das","günstigste","Modell","im","Geschäft."],"audio":"6ae289939f31"}]},{"type":"match","title":"Grundform und Komparativ","items":[{"l":"gut","r":"besser"},{"l":"viel","r":"mehr"},{"l":"gern","r":"lieber"},{"l":"hoch","r":"höher"},{"l":"teuer","r":"teurer"},{"l":"nah","r":"näher"},{"l":"gross","r":"grösser"},{"l":"alt","r":"älter"}]},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Ich möchte diesen Wasserkocher umtauschen.","audio":"8ae493f84e5d"},{"a":"Haben Sie die Quittung dabei?","audio":"2c6ddde5231f"},{"a":"Der neue Wasserkocher ist leiser als der alte.","audio":"23a3fd7a1f3c"},{"a":"Die blauen Schuhe sind am günstigsten.","audio":"73ddb881ba29"}]}],"reading":{"title":"Umtausch und Rückgabe – so einfach geht's","kind":"Aushang","paras":[{"t":"Sie sind mit einem Artikel nicht zufrieden? Kein Problem!","audio":"dec4b2062b97"},{"t":"Ungebrauchte Artikel können Sie innerhalb von 30 Tagen in jeder Filiale umtauschen. Bitte bringen Sie die Quittung und die Originalverpackung mit.","audio":"2b3621d688e3"},{"t":"Ihr Geld bekommen Sie nur bei defekten Artikeln zurück. Für ungebrauchte Artikel bekommen Sie einen Gutschein.","audio":"62d4c91a458a"},{"t":"Alle Elektrogeräte haben zwei Jahre Garantie. Wenn ein Gerät in dieser Zeit kaputtgeht, reparieren wir es kostenlos, oder Sie bekommen ein neues Gerät.","audio":"2a21629da867"},{"t":"Reduzierte Artikel aus unseren Aktionen können Sie leider nicht umtauschen.","audio":"3850cf5b98ce"},{"t":"Online gekaufte Artikel können Sie per Post zurückschicken oder in einer Filiale abgeben. Die Rücksendung ist gratis.","audio":"60f0ddf31e08"},{"t":"Haben Sie Fragen? Unser Kundendienst ist von Montag bis Samstag von 8 bis 18 Uhr per Telefon und im Chat für Sie da.","audio":"0be0b7eb28c7"}],"glossary":[{"de":"ungebraucht","en":"unused"},{"de":"innerhalb von","en":"within"},{"de":"defekt","en":"faulty"},{"de":"reduziert","en":"reduced (price)"},{"de":"abgeben","en":"to hand in, drop off"},{"de":"die Rücksendung","en":"return shipment"}],"questions":[{"type":"tf","q":"Ungebrauchte Artikel kann man innerhalb von 30 Tagen umtauschen.","a":true,"why":""},{"type":"mc","q":"Was braucht man für den Umtausch?","options":["nur die Quittung","die Quittung und die Originalverpackung","einen Gutschein"],"a":1},{"type":"mc","q":"Sie bringen einen ungebrauchten Pullover zurück. Was bekommen Sie?","options":["Ihr Geld","einen Gutschein","nichts"],"a":1},{"type":"tf","q":"Artikel aus einer Aktion kann man nicht umtauschen.","a":true,"why":""},{"type":"tf","q":"Die Rücksendung per Post kostet zehn Franken.","a":false,"why":"Die Rücksendung ist gratis."}]},"writing":{"task":"Sie haben online eine Jacke bestellt. Sie ist zu klein, und die Farbe ist anders als auf dem Foto. Schreiben Sie an den Kundendienst (60–80 Wörter).","points":["Was haben Sie wann bestellt?","Was ist das Problem?","Was möchten Sie? (umtauschen oder Geld zurück)","Fragen Sie, wie Sie die Jacke zurückschicken können."],"phrases":[{"de":"Am … habe ich bei Ihnen … bestellt.","en":"On … I ordered … from you."},{"de":"Leider gibt es ein Problem mit …","en":"Unfortunately there's a problem with …"},{"de":"Ich möchte … gegen … umtauschen.","en":"I'd like to exchange … for …"},{"de":"Falls das nicht möglich ist, …","en":"If that's not possible, …"},{"de":"Können Sie mir bitte sagen, wie …?","en":"Could you please tell me how …?"}],"model":"Sehr geehrte Damen und Herren\n\nAm 3. Oktober habe ich bei Ihnen eine blaue Winterjacke in Grösse M bestellt. Leider gibt es zwei Probleme: Die Jacke ist zu klein, und die Farbe ist viel dunkler als auf dem Foto. Ich möchte die Jacke gerne gegen eine grössere Jacke in Grösse L umtauschen. Falls das nicht möglich ist, möchte ich mein Geld zurück. Können Sie mir bitte sagen, wie ich die Jacke zurückschicken kann?\n\nFreundliche Grüsse\nCarla Ferreira","audio":"af2f6eaf67e9"},"speaking":{"task":"Im Kleidergeschäft – antworten Sie der Verkäuferin. Vergleichen Sie die Produkte.","phrases":[{"de":"Ich suche …","en":"I'm looking for …","audio":null},{"de":"Haben Sie das auch in Grösse …?","en":"Do you have this in size …?","audio":null},{"de":"Kann ich das anprobieren?","en":"Can I try it on?","audio":"ddc16d2100d6"},{"de":"Das ist mir zu teuer.","en":"That's too expensive for me.","audio":"e12d5b5dc47d"},{"de":"Ich nehme lieber …","en":"I'd rather take …","audio":null}],"prompts":[{"q":"Guten Tag, kann ich Ihnen helfen?","model":"Ja, gerne. Ich suche eine warme Jacke für den Winter.","aq":"399b1ed10c96","am":"45870c242d12"},{"q":"Welche Farbe möchten Sie?","model":"Am liebsten eine dunkle Farbe, zum Beispiel dunkelblau oder schwarz.","aq":"4c1e3be3f12f","am":"28ba636480c7"},{"q":"Wie gefällt Ihnen diese Jacke hier?","model":"Sie gefällt mir gut, aber sie ist ein bisschen zu gross. Haben Sie sie eine Nummer kleiner?","aq":"d14116e4a3a1","am":"92ce0b770f38"},{"q":"Diese kostet hundertneunzig Franken. Die andere hier ist günstiger.","model":"Die günstigere Jacke ist aber nicht so warm. Ich nehme lieber die teurere, die ist besser für den Winter.","aq":"02c1856a74e8","am":"905baf4b9a69"}]}},{"id":5,"title":"Mit Bahn und Bus","subtitle":"Auskunft am Bahnhof, Durchsagen verstehen","level":"A2","theme":"Mobilität","focus":"Wechselpräpositionen und indirekte Fragen","goals":[{"de":"Ich kann am Bahnhof Informationen über Verbindungen und Billette erfragen.","en":"I can ask for information about connections and tickets at the station."},{"de":"Ich kann Durchsagen und Informationen zu Verspätungen verstehen.","en":"I can understand announcements and information about delays."},{"de":"Ich kann höflich fragen (Können Sie mir sagen, …?).","en":"I can ask politely (Could you tell me …?)."}],"vocab":[{"id":"5-0","de":"der Fahrplan","forms":"Fahrpläne","en":"timetable","ex":"Ich schaue kurz im Fahrplan nach.","exEn":"I'll quickly check the timetable.","aw":"f50e513db3bf","ae":"a0e375b88e86"},{"id":"5-1","de":"das Billett","forms":"-e","en":"ticket (CH)","ex":"Ich habe mein Billett in der App gekauft.","exEn":"I bought my ticket in the app.","aw":"e9bf0d3f1f5d","ae":"c9c45565e377"},{"id":"5-2","de":"das Halbtax","forms":"–","en":"half-fare card (CH)","ex":"Mit dem Halbtax bezahlt man nur die Hälfte.","exEn":"With the half-fare card you only pay half.","aw":"4fe4fe8612ea","ae":"d1dda17e75a2"},{"id":"5-3","de":"das Gleis","forms":"-e","en":"track, platform number","ex":"Der Zug fährt auf Gleis sieben ab.","exEn":"The train leaves from platform seven.","aw":"8e9415ffed2f","ae":"7ebf45b68228"},{"id":"5-4","de":"umsteigen","forms":"ist umgestiegen","en":"to change (trains, buses)","ex":"Sie müssen in Zürich umsteigen.","exEn":"You have to change in Zurich.","aw":"2fad214349ff","ae":"55f98269fb3b"},{"id":"5-5","de":"einsteigen","forms":"ist eingestiegen","en":"to get on","ex":"Bitte schnell einsteigen, der Zug fährt gleich ab!","exEn":"Please get on quickly, the train is about to leave!","aw":"4b9f026e9fe4","ae":"8127ee3c329f"},{"id":"5-6","de":"aussteigen","forms":"ist ausgestiegen","en":"to get off","ex":"Wir steigen an der nächsten Haltestelle aus.","exEn":"We're getting off at the next stop.","aw":"4477f115d13b","ae":"f12b0a4b5762"},{"id":"5-7","de":"die Verspätung","forms":"-en","en":"delay","ex":"Der Zug hat zehn Minuten Verspätung.","exEn":"The train is ten minutes late.","aw":"e75832564656","ae":"828402f14cf7"},{"id":"5-8","de":"der Anschluss","forms":"Anschlüsse","en":"connection","ex":"Ich habe meinen Anschluss verpasst.","exEn":"I missed my connection.","aw":"40bc0c9a2554","ae":"6f94ebb9bcfe"},{"id":"5-9","de":"verpassen","forms":"hat verpasst","en":"to miss","ex":"Beeil dich, sonst verpassen wir den Bus!","exEn":"Hurry up, or we'll miss the bus!","aw":"08a8cdaa58e9","ae":"fd5507d34de8"},{"id":"5-10","de":"die Haltestelle","forms":"-n","en":"(bus/tram) stop","ex":"Die Haltestelle ist direkt vor dem Haus.","exEn":"The stop is right in front of the building.","aw":"badf438d7ec7","ae":"4f9e237399ac"},{"id":"5-11","de":"die Durchsage","forms":"-n","en":"announcement","ex":"Hast du die Durchsage verstanden?","exEn":"Did you understand the announcement?","aw":"ee12fe7537bc","ae":"3d7cef6a1362"},{"id":"5-12","de":"die Richtung","forms":"-en","en":"direction","ex":"Nehmen Sie den Bus in Richtung Bahnhof.","exEn":"Take the bus towards the station.","aw":"46652beedb79","ae":"4ce628a3c390"},{"id":"5-13","de":"hin und zurück","forms":"–","en":"return (ticket)","ex":"Einmal nach Luzern, hin und zurück, bitte.","exEn":"One return to Lucerne, please.","aw":"e7aaa53ebd9f","ae":"1dec01cc6ffc"},{"id":"5-14","de":"ausfallen","forms":"ist ausgefallen","en":"to be cancelled","ex":"Der Zug fällt heute wegen Bauarbeiten aus.","exEn":"The train is cancelled today due to construction work.","aw":"324a96a61b20","ae":"391bf3c1e923"},{"id":"5-15","de":"der Ersatzbus","forms":"-se","en":"replacement bus","ex":"Zwischen Winterthur und Frauenfeld fahren Ersatzbusse.","exEn":"Replacement buses run between Winterthur and Frauenfeld.","aw":"cfd25b828c6a","ae":"c4e615a90a17"},{"id":"5-16","de":"das Velo","forms":"-s","en":"bicycle (CH)","ex":"Ich fahre jeden Tag mit dem Velo zur Arbeit.","exEn":"I cycle to work every day.","aw":"07b8869be926","ae":"e467d208add7"},{"id":"5-17","de":"sich auskennen","forms":"hat sich ausgekannt","en":"to know your way around","ex":"Ich kenne mich in Bern noch nicht gut aus.","exEn":"I don't know my way around Bern well yet.","aw":"d4f5be780982","ae":"8a9a94a35191"},{"id":"5-18","de":"die Auskunft","forms":"Auskünfte","en":"information","ex":"Vielen Dank für die Auskunft!","exEn":"Thank you for the information!","aw":"9c832a33ba05","ae":"538624184106"},{"id":"5-19","de":"der Automat","forms":"-en","en":"(ticket) machine","ex":"Der Automat nimmt leider keine Karten.","exEn":"Unfortunately the machine doesn't take cards.","aw":"98885f322199","ae":"a1e1845c029b"}],"swiss":[{"ch":"das Billett","std":"die Fahrkarte","en":"ticket"},{"ch":"der Perron","std":"der Bahnsteig","en":"platform"},{"ch":"das Velo","std":"das Fahrrad","en":"bicycle"},{"ch":"das Halbtax","std":"–","en":"half-fare card – you pay about half on trains, buses and boats"},{"ch":"das GA","std":"–","en":"Generalabonnement – unlimited travel on almost all Swiss public transport"}],"dialogue":{"title":"Im Reisezentrum","intro":"Carla möchte am Samstag nach Luzern fahren. Sie fragt im Reisezentrum am Bahnhof Winterthur nach.","speakers":{"F":"Carla","M":"Mitarbeiter"},"lines":[{"s":"M","de":"Guten Tag, wie kann ich Ihnen helfen?","en":"Hello, how can I help you?","audio":"4ab24536a912"},{"s":"F","de":"Guten Tag. Ich möchte am Samstag nach Luzern fahren. Können Sie mir sagen, wann die Züge fahren?","en":"Hello. I'd like to go to Lucerne on Saturday. Could you tell me when the trains run?","audio":"d62906c8ebb7"},{"s":"M","de":"Gerne. Am Samstag fährt jede halbe Stunde ein Zug, zum Beispiel um 8.32 Uhr. Sie müssen in Zürich umsteigen.","en":"Sure. On Saturday there's a train every half hour, for example at 8:32. You have to change in Zurich.","audio":"3dcf493002e0"},{"s":"F","de":"Und wissen Sie, wie lange die Fahrt dauert?","en":"And do you know how long the journey takes?","audio":"fcfd9bfbb041"},{"s":"M","de":"Ungefähr eine Stunde und zwanzig Minuten.","en":"About one hour and twenty minutes.","audio":"96dd1f00ed9c"},{"s":"F","de":"Was kostet ein Billett hin und zurück?","en":"How much is a return ticket?","audio":"f5c61148147c"},{"s":"M","de":"Haben Sie ein Halbtax?","en":"Do you have a half-fare card?","audio":"02c5a89699c5"},{"s":"F","de":"Nein, noch nicht. Ich weiss nicht, ob sich das für mich lohnt.","en":"No, not yet. I don't know if it's worth it for me.","audio":"673420d864f2"},{"s":"M","de":"Wenn Sie oft mit dem Zug fahren, lohnt es sich bestimmt. Ohne Halbtax kostet das Billett etwa achtzig Franken, mit Halbtax nur die Hälfte.","en":"If you often travel by train, it's definitely worth it. Without a half-fare card the ticket costs about eighty francs, with it only half.","audio":"2b0fffd3851b"},{"s":"F","de":"Dann kaufe ich heute ein Halbtax. Und kann ich mein Velo in den Zug mitnehmen?","en":"Then I'll buy a half-fare card today. And can I take my bike on the train?","audio":"49e7065f9a2e"},{"s":"M","de":"Ja, aber Sie brauchen ein Velobillett. Stellen Sie das Velo bitte in den Wagen mit dem Velo-Symbol.","en":"Yes, but you need a bike ticket. Please put the bike in the carriage with the bike symbol.","audio":"37f7fbf728be"},{"s":"F","de":"Und wo finde ich diesen Wagen?","en":"And where do I find this carriage?","audio":"3c6f1e117e2a"},{"s":"M","de":"Der ist meistens am Anfang oder am Ende des Zuges. Auf dem Perron gibt es eine Anzeige.","en":"It's usually at the front or the back of the train. There's a display on the platform.","audio":"7b5697476234"},{"s":"F","de":"Super, vielen Dank für die Auskunft!","en":"Great, thank you very much for the information!","audio":"67eb5cfde9e7"},{"s":"M","de":"Gern geschehen. Gute Reise!","en":"You're welcome. Have a good trip!","audio":"7473d7ca9b2c"}],"questions":[{"type":"tf","q":"Carla muss in Zürich umsteigen.","a":true,"why":""},{"type":"mc","q":"Wie oft fährt am Samstag ein Zug nach Luzern?","options":["jede Stunde","jede halbe Stunde","alle zehn Minuten"],"a":1},{"type":"mc","q":"Wie viel kostet das Billett mit Halbtax ungefähr?","options":["achtzig Franken","vierzig Franken","zwanzig Franken"],"a":1},{"type":"tf","q":"Für das Velo braucht man kein Billett.","a":false,"why":"Man braucht ein Velobillett."},{"type":"mc","q":"Wo sieht man, wo der Velowagen ist?","options":["auf dem Perron","im Reisezentrum","im Zug"],"a":0}]},"grammar":{"title":"Wechselpräpositionen und indirekte Fragen","summary":"Wo? → Dativ. Wohin? → Akkusativ.","sections":[{"h":"Neun Präpositionen mit zwei Kasus","text":"**an, auf, hinter, in, neben, über, unter, vor, zwischen** können mit Dativ oder Akkusativ stehen.\n**Wo?** (Position, keine Bewegung zu einem Ziel) → **Dativ**. **Wohin?** (Richtung, Bewegung zu einem Ziel) → **Akkusativ**.","table":[["Wo? (Dativ)","Wohin? (Akkusativ)"],["Das Velo steht ==im== Wagen.","Ich stelle das Velo ==in den== Wagen."],["Wir warten ==auf dem== Perron.","Wir gehen ==auf den== Perron."],["Die Tasche liegt ==unter dem== Sitz.","Ich lege die Tasche ==unter den== Sitz."],["Die Jacke hängt ==an der== Tür.","Ich hänge die Jacke ==an die== Tür."],["Sie sitzt ==neben dem== Fenster.","Sie setzt sich ==neben das== Fenster."]]},{"h":"Die Artikel","text":"Kurzformen: **in dem → im, in das → ins, an dem → am, an das → ans**.","table":[["Nominativ","Dativ (wo?)","Akkusativ (wohin?)"],["der Zug","in dem (= im) Zug","in den Zug"],["die Stadt","in der Stadt","in die Stadt"],["das Kino","in dem (= im) Kino","in das (= ins) Kino"],["die Busse (Pl.)","in den Bussen","in die Busse"]]},{"h":"Verbpaare – Position und Bewegung","text":"Hinweis: In der Schweiz und in Süddeutschland sagt man *ist gestanden, ist gelegen, ist gesessen*; in Norddeutschland *hat gestanden* usw.","table":[["Wo? + Dativ","Wohin? + Akkusativ"],["stehen (ist gestanden)","stellen (hat gestellt)"],["liegen (ist gelegen)","legen (hat gelegt)"],["hängen (ist gehangen)","hängen (hat gehängt)"],["sitzen (ist gesessen)","sich setzen (hat sich gesetzt)"]]},{"h":"Indirekte Fragen – höflich fragen","text":"Mit **Können Sie mir sagen, …? / Wissen Sie, …? / Ich möchte wissen, …** wird eine Frage höflicher. Die Frage wird ein Nebensatz: Das Verb geht ans **Ende**.\nW-Frage → W-Wort bleibt. Ja/Nein-Frage → **ob**.","examples":[{"de":"Wann ==fährt== der Zug? → Können Sie mir sagen, wann der Zug ==fährt==?","en":"When does the train leave? → Could you tell me when the train leaves?","audio":"fd93b4f3397b"},{"de":"Muss ich umsteigen? → Wissen Sie, ==ob== ich umsteigen ==muss==?","en":"Do I have to change? → Do you know whether I have to change?","audio":"ce109030cefd"},{"de":"Wo ist der Automat? → Ich möchte wissen, wo der Automat ==ist==.","en":"Where is the machine? → I'd like to know where the machine is.","audio":"b3a6268181dc"}]}],"tip":"Nicht alle Bewegungen brauchen den Akkusativ: „Ich fahre ==im== Zug nach Bern.\" Man bewegt sich, aber im Zug – der Zug ist kein Ziel."},"exercises":[{"type":"choice","title":"Dativ oder Akkusativ?","items":[{"q":"Der Zug steht schon auf ___ Gleis.","options":["dem","das"],"a":0,"full":"Der Zug steht schon auf dem Gleis.","audio":"339d481a0b00"},{"q":"Ich stelle mein Velo in ___ Velowagen.","options":["den","dem"],"a":0,"full":"Ich stelle mein Velo in den Velowagen.","audio":"afe9fda11eff"},{"q":"Wir warten vor ___ Bahnhof auf dich.","options":["dem","den"],"a":0,"full":"Wir warten vor dem Bahnhof auf dich.","audio":"6b744823bc93"},{"q":"Leg deine Tasche bitte unter ___ Sitz.","options":["den","dem"],"a":0,"full":"Leg deine Tasche bitte unter den Sitz.","audio":"29b06b7e4c0d"},{"q":"Das Billett ist in ___ App.","options":["der","die"],"a":0,"full":"Das Billett ist in der App.","audio":"253596126684"},{"q":"Er setzt sich neben ___ Fenster.","options":["das","dem"],"a":0,"full":"Er setzt sich neben das Fenster.","audio":"12f76bd4dc7f"},{"q":"Die Haltestelle ist zwischen ___ Post und ___ Bank.","options":["der … der","die … die"],"a":0,"full":"Die Haltestelle ist zwischen der Post und der Bank.","audio":"7648f24509ce"},{"q":"Am Sonntag fahren wir an ___ See.","options":["den","dem"],"a":0,"full":"Am Sonntag fahren wir an den See.","audio":"ad07c7476777"}]},{"type":"gap","title":"Präposition und Artikel","items":[{"q":"Ich gehe heute Abend ___ Kino. (in + das)","a":["ins"],"full":"Ich gehe heute Abend ins Kino.","audio":"1b06f412bf90"},{"q":"Der Bus wartet ___ Bahnhof. (an + dem)","a":["am"],"full":"Der Bus wartet am Bahnhof.","audio":"b6cb890bae41"},{"q":"Wir treffen uns ___ Perron sieben. (auf + der)","a":["auf dem"],"full":"Wir treffen uns auf dem Perron sieben.","audio":"b61eaeda78c3"},{"q":"Carla steigt ___ Zug nach Bern. (in + der)","a":["in den"],"full":"Carla steigt in den Zug nach Bern.","audio":"f7375e1fcc4a"},{"q":"Das Velo steht ___ Haus. (hinter + das)","a":["hinter dem"],"full":"Das Velo steht hinter dem Haus.","audio":"5811ad2996fb"},{"q":"Ich hänge die Jacke ___ Haken. (an + der)","a":["an den"],"full":"Ich hänge die Jacke an den Haken.","audio":"d882d9490591"}]},{"type":"gap","title":"Indirekte Fragen – ergänzen Sie","items":[{"q":"Fährt der Bus zum Spital? → Wissen Sie, ___ der Bus zum Spital fährt?","a":["ob"],"full":"Wissen Sie, ob der Bus zum Spital fährt?","audio":"2fdc68385695"},{"q":"Wann kommt der Zug an? → Können Sie mir sagen, wann der Zug ___?","a":["ankommt"],"full":"Können Sie mir sagen, wann der Zug ankommt?","audio":"4bb0f0d9a046"},{"q":"Wo ist der Billettautomat? → Wissen Sie, wo der Billettautomat ___?","a":["ist"],"full":"Wissen Sie, wo der Billettautomat ist?","audio":"258e86fd4da1"},{"q":"Muss ich umsteigen? → Ich möchte wissen, ob ich umsteigen ___.","a":["muss"],"full":"Ich möchte wissen, ob ich umsteigen muss.","audio":"8d93422ae651"},{"q":"Wie lange dauert die Fahrt? → Können Sie mir sagen, wie lange die Fahrt ___?","a":["dauert"],"full":"Können Sie mir sagen, wie lange die Fahrt dauert?","audio":"878745167cf0"}]},{"type":"order","title":"Bilden Sie höfliche Fragen","items":[{"a":["Können Sie mir sagen, wann der nächste Zug fährt?"],"tokens":["Können","Sie","mir","sagen,","wann","der","nächste","Zug","fährt?"],"audio":"a43b811bcf11"},{"a":["Wissen Sie, ob der Zug Verspätung hat?"],"tokens":["Wissen","Sie,","ob","der","Zug","Verspätung","hat?"],"audio":"70b4f836d863"},{"a":["Ich möchte wissen, wie viel das Billett kostet."],"tokens":["Ich","möchte","wissen,","wie","viel","das","Billett","kostet."],"audio":"bccca7e214d2"},{"a":["Können Sie mir sagen, wo ich umsteigen muss?"],"tokens":["Können","Sie","mir","sagen,","wo","ich","umsteigen","muss?"],"audio":"a0b00eeaccc4"},{"a":["Weisst du, auf welchem Gleis der Zug abfährt?"],"tokens":["Weisst","du,","auf","welchem","Gleis","der","Zug","abfährt?"],"audio":"b250e16e4389"}]},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Können Sie mir sagen, wann der Zug nach Luzern fährt?","audio":"d9c4bc027105"},{"a":"Wir müssen in Zürich umsteigen.","audio":"bc379785c363"},{"a":"Der Zug hat zehn Minuten Verspätung.","audio":"61352497721a"},{"a":"Ich stelle mein Velo in den Velowagen.","audio":"160494db6a50"}]}],"reading":{"title":"Durchsagen und Informationen","kind":"Durchsagen","paras":[{"t":"**Durchsage am Bahnhof Winterthur**\nGleis 4: Der InterRegio nach Luzern, Abfahrt 8.32 Uhr, hat circa zehn Minuten Verspätung. Reisende nach Luzern: Ihr Anschlusszug in Zürich wartet.","audio":"ce4902a4e72a"},{"t":"**Durchsage im Zug**\nNächster Halt: Zürich Hauptbahnhof. Bitte beachten Sie: Wegen Bauarbeiten fährt dieser Zug heute auf Gleis 16 ein. Der Zug nach Luzern fährt auf Gleis 8.","audio":"e7277163770e"},{"t":"**Information: Bauarbeiten zwischen Winterthur und Frauenfeld**\nVom 10. bis 12. Oktober fallen alle Züge zwischen Winterthur und Frauenfeld aus. Zwischen den beiden Bahnhöfen fahren Ersatzbusse. Die Busse fahren auf dem Bahnhofplatz ab, direkt vor dem Haupteingang. Bitte rechnen Sie mit 20 Minuten mehr Reisezeit. Velos dürfen Sie leider nicht in die Ersatzbusse mitnehmen.","audio":"6a2854d90f6a"}],"glossary":[{"de":"circa","en":"about, approximately"},{"de":"der Anschlusszug","en":"connecting train"},{"de":"wegen","en":"because of"},{"de":"die Bauarbeiten","en":"construction work"},{"de":"einfahren","en":"to pull in (train)"},{"de":"rechnen mit","en":"to expect, allow for"}],"questions":[{"type":"tf","q":"Der Zug nach Luzern hat ungefähr zehn Minuten Verspätung.","a":true,"why":""},{"type":"mc","q":"Auf welchem Gleis kommt der Zug in Zürich an?","options":["Gleis 4","Gleis 8","Gleis 16"],"a":2},{"type":"mc","q":"Was passiert vom 10. bis 12. Oktober?","options":["Die Züge fahren nur am Abend.","Es fahren Busse statt Züge.","Der Bahnhof ist geschlossen."],"a":1},{"type":"tf","q":"Die Ersatzbusse fahren vor dem Haupteingang ab.","a":true,"why":""},{"type":"tf","q":"Man kann sein Velo in den Ersatzbus mitnehmen.","a":false,"why":"Velos darf man nicht mitnehmen."}]},"writing":{"task":"Sie haben den Zug verpasst und kommen zu spät zu einem Treffen mit einer Freundin. Schreiben Sie ihr eine Nachricht (40–60 Wörter).","points":["Entschuldigen Sie sich.","Was ist passiert?","Wann kommen Sie an?","Wo können Sie sich treffen?"],"phrases":[{"de":"Es tut mir leid, aber …","en":"I'm sorry, but …"},{"de":"Ich habe den Zug verpasst, weil …","en":"I missed the train because …"},{"de":"Ich bin um … Uhr in …","en":"I'll be in … at …"},{"de":"Wartest du im/am …?","en":"Will you wait in/at …?"}],"model":"Hallo Nina\n\nEs tut mir leid, aber ich komme etwa eine halbe Stunde später! Mein Bus hatte Verspätung, und ich habe den Zug um 10 Uhr verpasst. Jetzt nehme ich den Zug um 10.32 Uhr und bin um 11.05 Uhr in Zürich. Wartest du im Café neben dem Bahnhof auf mich? Ich lade dich zum Kaffee ein!\n\nLiebe Grüsse\nCarla","audio":"3b5f96fdae8d"},"speaking":{"task":"Am Bahnhof – Sie hören eine Situation. Fragen Sie höflich mit einer indirekten Frage.","phrases":[{"de":"Entschuldigung, können Sie mir sagen, …?","en":"Excuse me, could you tell me …?","audio":null},{"de":"Wissen Sie, ob …?","en":"Do you know whether …?","audio":null},{"de":"Ich kenne mich hier leider nicht aus.","en":"Unfortunately I don't know my way around here.","audio":"548b3a5ec111"},{"de":"Einmal nach Bern, hin und zurück, bitte.","en":"One return to Bern, please.","audio":"ceddedac09f4"},{"de":"Wo muss ich umsteigen?","en":"Where do I have to change?","audio":"a9d2821c99e0"}],"prompts":[{"q":"Sie möchten wissen, wann der letzte Zug nach Winterthur fährt.","model":"Entschuldigung, können Sie mir sagen, wann der letzte Zug nach Winterthur fährt?","aq":"f5dcab55c83c","am":"3ae7d40139dc"},{"q":"Sie wissen nicht, ob Sie in Zürich umsteigen müssen.","model":"Entschuldigung, wissen Sie, ob ich in Zürich umsteigen muss?","aq":"7f40d80bc1a1","am":"a8d448544863"},{"q":"Sie suchen die Haltestelle für den Bus Nummer zwei.","model":"Entschuldigung, ich kenne mich hier nicht aus. Wissen Sie, wo die Haltestelle für den Bus Nummer zwei ist?","aq":"63b8c32f4abf","am":"de28cbb4472d"},{"q":"Sie möchten wissen, wie viel ein Billett nach Bern kostet.","model":"Guten Tag. Können Sie mir sagen, wie viel ein Billett nach Bern kostet?","aq":"b14f02de5c25","am":"5f6b2bcf18a9"}]}},{"id":6,"title":"Nachbarn und Hausordnung","subtitle":"Waschküche, Ruhezeiten und höfliche Bitten","level":"A2/B1","theme":"Zusammenleben","focus":"Konjunktiv II – höfliche Bitten, Wünsche, Ratschläge","goals":[{"de":"Ich kann eine Hausordnung verstehen.","en":"I can understand house rules."},{"de":"Ich kann Nachbarn höflich um etwas bitten und ein Problem freundlich ansprechen.","en":"I can politely ask neighbours for something and raise a problem in a friendly way."},{"de":"Ich kann Ratschläge geben und Wünsche äussern (würde, hätte, wäre, könnte).","en":"I can give advice and express wishes."}],"vocab":[{"id":"6-0","de":"die Hausordnung","forms":"-en","en":"house rules","ex":"Die Hausordnung hängt im Treppenhaus.","exEn":"The house rules are posted in the stairwell.","aw":"31aac9294e4d","ae":"4a36298bee27"},{"id":"6-1","de":"die Nachtruhe","forms":"–","en":"night-time quiet hours","ex":"Ab zweiundzwanzig Uhr ist Nachtruhe.","exEn":"Quiet hours start at ten p.m.","aw":"bfad0021e209","ae":"31118cfdafff"},{"id":"6-2","de":"die Waschküche","forms":"-n","en":"shared laundry room (CH)","ex":"Die Waschküche ist im Keller.","exEn":"The laundry room is in the basement.","aw":"b14b29a7530e","ae":"fbfb84b7c5fc"},{"id":"6-3","de":"der Waschplan","forms":"Waschpläne","en":"laundry schedule (CH)","ex":"Laut Waschplan ist Mittwoch mein Waschtag.","exEn":"According to the schedule, Wednesday is my laundry day.","aw":"cd549dad80ec","ae":"045202d48057"},{"id":"6-4","de":"der Hauswart","forms":"-e","en":"caretaker (CH)","ex":"Rufen Sie den Hauswart an, die Heizung ist kaputt.","exEn":"Call the caretaker, the heating is broken.","aw":"19465af55cdb","ae":"8bca7274f6a9"},{"id":"6-5","de":"der Nachbar","forms":"-n","en":"neighbour","ex":"Unser Nachbar ist sehr hilfsbereit.","exEn":"Our neighbour is very helpful.","aw":"5c65ea2beabb","ae":"2f528831306b"},{"id":"6-6","de":"der Lärm","forms":"–","en":"noise","ex":"Der Lärm von der Baustelle stört mich.","exEn":"The noise from the building site bothers me.","aw":"02da35a6d2c4","ae":"cd07b5191c0d"},{"id":"6-7","de":"stören","forms":"hat gestört","en":"to disturb, bother","ex":"Entschuldigung, störe ich?","exEn":"Sorry, am I disturbing you?","aw":"aa9eceae058e","ae":"aea47fd087df"},{"id":"6-8","de":"das Treppenhaus","forms":"Treppenhäuser","en":"stairwell","ex":"Bitte keine Schuhe im Treppenhaus stehen lassen.","exEn":"Please don't leave shoes in the stairwell.","aw":"72f972ea7f9b","ae":"1da109d95eed"},{"id":"6-9","de":"der Keller","forms":"-","en":"basement, cellar","ex":"Jede Wohnung hat einen eigenen Keller.","exEn":"Every flat has its own cellar.","aw":"6a9a38a62160","ae":"d36b0d779a2b"},{"id":"6-10","de":"der Briefkasten","forms":"Briefkästen","en":"letterbox","ex":"Ich habe einen Zettel in Ihren Briefkasten gelegt.","exEn":"I put a note in your letterbox.","aw":"1eb3ff5b6f35","ae":"e2d50c5df78c"},{"id":"6-11","de":"ausleihen","forms":"hat ausgeliehen","en":"to lend, to borrow","ex":"Könnten Sie mir Ihre Leiter ausleihen?","exEn":"Could you lend me your ladder?","aw":"f361989a4f92","ae":"c21ff16f730c"},{"id":"6-12","de":"sich entschuldigen","forms":"hat sich entschuldigt","en":"to apologise","ex":"Er hat sich für den Lärm entschuldigt.","exEn":"He apologised for the noise.","aw":"ac5796703bc2","ae":"e63477bb632e"},{"id":"6-13","de":"das Missverständnis","forms":"-se","en":"misunderstanding","ex":"Das war nur ein Missverständnis.","exEn":"That was just a misunderstanding.","aw":"e28b194d44ab","ae":"79aeeeac23c2"},{"id":"6-14","de":"Rücksicht nehmen auf","forms":"hat Rücksicht genommen","en":"to be considerate of","ex":"Bitte nehmen Sie Rücksicht auf die Nachbarn.","exEn":"Please be considerate of the neighbours.","aw":"f3e59fef2cbf","ae":"a2540b5ba110"},{"id":"6-15","de":"vorschlagen","forms":"hat vorgeschlagen","en":"to suggest","ex":"Ich schlage vor, dass wir die Waschtage tauschen.","exEn":"I suggest we swap laundry days.","aw":"85bd8923524b","ae":"a56d7f2af881"},{"id":"6-16","de":"der Vorschlag","forms":"Vorschläge","en":"suggestion","ex":"Das ist ein guter Vorschlag!","exEn":"That's a good suggestion!","aw":"49d3f1c3b570","ae":"0582865b02ef"},{"id":"6-17","de":"einverstanden","forms":"–","en":"in agreement, okay with","ex":"Sind Sie damit einverstanden?","exEn":"Are you okay with that?","aw":"ac31036c61de","ae":"0540ba93a1f0"},{"id":"6-18","de":"die Lösung","forms":"-en","en":"solution","ex":"Wir finden sicher eine Lösung.","exEn":"We'll surely find a solution.","aw":"18fd4e00cafd","ae":"a482ebe532f2"},{"id":"6-19","de":"grillieren","forms":"hat grilliert","en":"to barbecue (CH)","ex":"Darf man auf dem Balkon grillieren?","exEn":"Are you allowed to barbecue on the balcony?","aw":"4c4f2d2aa094","ae":"4111b8538830"}],"swiss":[{"ch":"die Waschküche","std":"–","en":"shared laundry room; each flat has fixed laundry days"},{"ch":"der Hauswart","std":"der Hausmeister","en":"caretaker"},{"ch":"grillieren","std":"grillen","en":"to barbecue"},{"ch":"lärmig","std":"laut","en":"noisy"},{"ch":"parkieren","std":"parken","en":"to park"}],"dialogue":{"title":"Ein Missverständnis in der Waschküche","intro":"Carla wäscht an einem Dienstag. Da kommt ihr Nachbar, Herr Schmid, in die Waschküche.","speakers":{"F":"Carla","M":"Herr Schmid"},"lines":[{"s":"M","de":"Guten Abend, Frau Ferreira. Entschuldigung, aber heute ist eigentlich mein Waschtag.","en":"Good evening, Ms Ferreira. Excuse me, but today is actually my laundry day.","audio":"c0fd92775d26"},{"s":"F","de":"Oh, wirklich? Das tut mir leid! Ich dachte, dass ich am Dienstag waschen darf.","en":"Oh, really? I'm sorry! I thought I was allowed to wash on Tuesdays.","audio":"678cfc359f0e"},{"s":"M","de":"Auf dem Waschplan steht, dass Ihr Tag der Mittwoch ist. Schauen Sie, hier.","en":"The schedule says your day is Wednesday. Look, here.","audio":"3c050382f7e0"},{"s":"F","de":"Ach so, da habe ich mich geirrt. Das war ein Missverständnis.","en":"Oh, I see, I made a mistake. That was a misunderstanding.","audio":"4f1a6d6a0409"},{"s":"M","de":"Kein Problem, das kann passieren. Wie lange braucht Ihre Maschine noch?","en":"No problem, it happens. How much longer does your machine need?","audio":"5863884a9c7f"},{"s":"F","de":"Ungefähr vierzig Minuten. Könnten Sie vielleicht so lange warten? Danach würde ich die Wäsche sofort in den Tumbler legen.","en":"About forty minutes. Could you perhaps wait that long? Then I'd put the laundry in the dryer straight away.","audio":"39432fb846f8"},{"s":"M","de":"Hmm, eigentlich müsste ich um sechs Uhr weg. Aber gut, das geht schon.","en":"Hmm, I'd actually have to leave at six. But fine, that's okay.","audio":"195d132947b9"},{"s":"F","de":"Vielen Dank! Darf ich Ihnen als Dankeschön einen Kuchen backen?","en":"Thank you so much! May I bake you a cake as a thank-you?","audio":"25dad6233634"},{"s":"M","de":"Das wäre sehr nett, aber das ist wirklich nicht nötig.","en":"That would be very kind, but it's really not necessary.","audio":"390a9fc658a7"},{"s":"F","de":"Darf ich Sie noch etwas fragen? Wissen Sie, ob man auf dem Balkon grillieren darf?","en":"May I ask you something else? Do you know whether you're allowed to barbecue on the balcony?","audio":"1db35e8da1a2"},{"s":"M","de":"Mit einem Elektrogrill schon, aber nicht mit Holzkohle, wegen des Rauchs. An Ihrer Stelle würde ich aber noch den Hauswart fragen.","en":"With an electric grill, yes, but not with charcoal, because of the smoke. If I were you, I'd still ask the caretaker, though.","audio":"aa9fae381fb4"},{"s":"F","de":"Gute Idee. Und ab wann ist hier Nachtruhe?","en":"Good idea. And from when are the quiet hours here?","audio":"bb7050ab3268"},{"s":"M","de":"Ab zweiundzwanzig Uhr. Und am Sonntag sollte man nicht zu laut sein – also nicht staubsaugen und nicht bohren.","en":"From ten p.m. And on Sundays you shouldn't be too loud – so no vacuuming and no drilling.","audio":"773dd444968e"},{"s":"F","de":"Gut zu wissen! In Portugal ist das ein bisschen anders.","en":"Good to know! It's a bit different in Portugal.","audio":"3dcfdee07234"},{"s":"M","de":"Das glaube ich. Wenn Sie etwas brauchen, klingeln Sie einfach bei mir. Ich wohne im ersten Stock.","en":"I believe it. If you need anything, just ring my bell. I live on the first floor.","audio":"4b886d17aab8"},{"s":"F","de":"Das ist sehr nett. Ich hätte tatsächlich noch eine Bitte. Könnten Sie mir am Samstag Ihre Leiter ausleihen?","en":"That's very kind. Actually, I do have one more request. Could you lend me your ladder on Saturday?","audio":"55f3f60ac3d9"},{"s":"M","de":"Natürlich, kein Problem!","en":"Of course, no problem!","audio":"8cfcdb50f44d"}],"questions":[{"type":"tf","q":"Heute ist eigentlich der Waschtag von Herrn Schmid.","a":true,"why":""},{"type":"mc","q":"Wann ist Carlas Waschtag?","options":["am Dienstag","am Mittwoch","am Sonntag"],"a":1},{"type":"mc","q":"Was möchte Carla als Dankeschön machen?","options":["einen Kuchen backen","ihn zum Essen einladen","seine Wäsche waschen"],"a":0},{"type":"tf","q":"Auf dem Balkon darf man mit Holzkohle grillieren.","a":false,"why":"Nur mit einem Elektrogrill."},{"type":"mc","q":"Was möchte Carla ausleihen?","options":["eine Bohrmaschine","einen Grill","eine Leiter"],"a":2}]},"grammar":{"title":"Konjunktiv II – höflich, vorsichtig, irreal","summary":"Mit dem Konjunktiv II klingen Bitten höflicher und Ratschläge freundlicher.","sections":[{"h":"Höfliche Bitten","text":"Statt eines Imperativs (*Machen Sie die Musik leiser!*) benutzt man im Alltag viel lieber den Konjunktiv II:","examples":[{"de":"==Könnten== Sie bitte die Musik leiser machen?","en":"Could you please turn the music down?","audio":"de14d4048aba"},{"de":"==Würden== Sie mir bitte die Leiter ausleihen?","en":"Would you lend me the ladder, please?","audio":"1f5272060859"},{"de":"==Wäre== es möglich, dass ich am Samstag wasche?","en":"Would it be possible for me to do laundry on Saturday?","audio":"0dd50a2aa224"},{"de":"Ich ==hätte== eine Bitte.","en":"I have a request.","audio":"ce1b96a4f326"}]},{"h":"Die wichtigsten Formen","text":"Die Formen kommen vom Präteritum – oft mit Umlaut: *war → wäre, hatte → hätte, konnte → könnte, wurde → würde.*","table":[["Person","sein","haben","können","werden","müssen","sollen"],["ich","wäre","hätte","könnte","würde","müsste","sollte"],["du","wärst","hättest","könntest","würdest","müsstest","solltest"],["er/sie/es","wäre","hätte","könnte","würde","müsste","sollte"],["wir","wären","hätten","könnten","würden","müssten","sollten"],["ihr","wärt","hättet","könntet","würdet","müsstet","solltet"],["sie/Sie","wären","hätten","könnten","würden","müssten","sollten"]]},{"h":"würde + Infinitiv","text":"Bei den meisten anderen Verben benutzt man **würde + Infinitiv** (am Satzende).","examples":[{"de":"Ich ==würde== gern im Erdgeschoss ==wohnen==.","en":"I would like to live on the ground floor.","audio":"2836c2409a05"},{"de":"==Würden== Sie das Fenster bitte ==schliessen==?","en":"Would you close the window, please?","audio":"84ba1bc89633"}]},{"h":"Wünsche und Ratschläge","table":[["Funktion","Redemittel"],["Wunsch","Ich hätte gern … / Ich würde gern … / Es wäre schön, wenn …"],["Rat","Du solltest … / An deiner Stelle würde ich … / Wie wäre es, wenn …?"],["Vorschlag","Wir könnten … / Wäre es nicht besser, …?"]]},{"h":"Irreale Bedingung (B1)","text":"Wenn etwas nicht real ist, sondern nur eine Idee: **wenn** + Konjunktiv II, **dann** Konjunktiv II.","examples":[{"de":"Wenn ich einen Garten ==hätte==, ==würde== ich Gemüse ==pflanzen==.","en":"If I had a garden, I would plant vegetables.","audio":"6deb186f3111"},{"de":"Wenn das Wetter schöner ==wäre==, ==könnten== wir ==grillieren==.","en":"If the weather were nicer, we could have a barbecue.","audio":"a9967f764391"}]}],"tip":"Für sein, haben und die Modalverben benutzt man fast nie „würde\": Man sagt „Ich wäre froh\" und nicht „Ich würde froh sein\". Man sagt „Ich hätte Zeit\" und nicht „Ich würde Zeit haben\"."},"exercises":[{"type":"choice","title":"Welche Form passt?","items":[{"q":"___ Sie bitte etwas leiser sein?","options":["Könnten","Hätten","Wären"],"a":0,"full":"Könnten Sie bitte etwas leiser sein?","audio":"974b4fd2c121"},{"q":"Ich ___ gern einen Termin mit dem Hauswart.","options":["hätte","wäre","würde"],"a":0,"full":"Ich hätte gern einen Termin mit dem Hauswart.","audio":"90310a692d3d"},{"q":"___ es möglich, dass ich am Samstag wasche?","options":["Wäre","Hätte","Würde"],"a":0,"full":"Wäre es möglich, dass ich am Samstag wasche?","audio":"0dd50a2aa224"},{"q":"An deiner Stelle ___ ich mit dem Nachbarn sprechen.","options":["würde","hätte","wäre"],"a":0,"full":"An deiner Stelle würde ich mit dem Nachbarn sprechen.","audio":"9bbecda72b92"},{"q":"Du ___ die Hausordnung genau lesen.","options":["solltest","wärst","hättest"],"a":0,"full":"Du solltest die Hausordnung genau lesen.","audio":"c35e6af60376"},{"q":"Wenn ich mehr Zeit ___, würde ich öfter kochen.","options":["hätte","wäre","würde"],"a":0,"full":"Wenn ich mehr Zeit hätte, würde ich öfter kochen.","audio":"21bac08f8e8b"},{"q":"Wenn das Wetter schöner ___, könnten wir grillieren.","options":["wäre","hätte","würde"],"a":0,"full":"Wenn das Wetter schöner wäre, könnten wir grillieren.","audio":"a9967f764391"},{"q":"___ Sie mir bitte Ihre Leiter ausleihen?","options":["Würden","Wären","Hätten"],"a":0,"full":"Würden Sie mir bitte Ihre Leiter ausleihen?","audio":"fe4b1c807109"}]},{"type":"gap","title":"Konjunktiv II – ergänzen Sie","items":[{"q":"___ du mir kurz helfen? (können)","a":["Könntest"],"full":"Könntest du mir kurz helfen?","audio":"33c26e352bc7"},{"q":"Ich ___ lieber im Erdgeschoss wohnen. (werden)","a":["würde"],"full":"Ich würde lieber im Erdgeschoss wohnen.","audio":"8f5ef88b0cff"},{"q":"Es ___ schön, wenn wir zusammen grillieren. (sein)","a":["wäre"],"full":"Es wäre schön, wenn wir zusammen grillieren.","audio":"9ffc0831d18c"},{"q":"Wir ___ gern eine grössere Wohnung. (haben)","a":["hätten"],"full":"Wir hätten gern eine grössere Wohnung.","audio":"bffe5b45b921"},{"q":"Sie ___ den Hauswart anrufen. (sollen)","a":["sollten"],"full":"Sie sollten den Hauswart anrufen.","audio":"972079a288f8"},{"q":"___ ihr am Sonntag Zeit? (haben)","a":["Hättet"],"full":"Hättet ihr am Sonntag Zeit?","audio":"ff4c09aeaa95"}]},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Könnten Sie bitte die Musik leiser machen?"],"tokens":["Könnten","Sie","bitte","die","Musik","leiser","machen?"],"audio":"de14d4048aba"},{"a":["Ich würde gern mit Ihnen über den Waschplan sprechen."],"tokens":["Ich","würde","gern","mit","Ihnen","über","den","Waschplan","sprechen."],"audio":"70d9bdf3c389"},{"a":["An Ihrer Stelle würde ich den Hauswart fragen."],"tokens":["An","Ihrer","Stelle","würde","ich","den","Hauswart","fragen."],"audio":"dc3603280a5d"},{"a":["Wenn ich einen Garten hätte, würde ich Gemüse pflanzen.","Ich würde Gemüse pflanzen, wenn ich einen Garten hätte."],"tokens":["Wenn","ich","einen","Garten","hätte,","würde","ich","Gemüse","pflanzen."],"audio":"6deb186f3111"},{"a":["Wäre es möglich, den Waschtag zu tauschen?"],"tokens":["Wäre","es","möglich,","den","Waschtag","zu","tauschen?"],"audio":"8113a84d0e76"}]},{"type":"match","title":"Direkt → höflich","items":[{"l":"Mach die Musik leiser!","r":"Könntest du bitte die Musik leiser machen?"},{"l":"Gib mir die Leiter!","r":"Würdest du mir bitte die Leiter geben?"},{"l":"Ich will am Samstag waschen.","r":"Ich würde gern am Samstag waschen."},{"l":"Ich will einen Kaffee.","r":"Ich hätte gern einen Kaffee."},{"l":"Räumen Sie die Schuhe weg!","r":"Könnten Sie bitte die Schuhe wegräumen?"}]},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Könnten Sie bitte etwas leiser sein?","audio":"7c7082a4663c"},{"a":"Ich hätte noch eine Bitte.","audio":"b01c2b5c73dc"},{"a":"An Ihrer Stelle würde ich den Hauswart fragen.","audio":"5f28102da1e5"},{"a":"Wenn ich mehr Zeit hätte, würde ich öfter kochen.","audio":"203d5e87cb1a"}]}],"reading":{"title":"Hausordnung – Rosenweg 12","kind":"Hausordnung","paras":[{"t":"Damit sich alle im Haus wohlfühlen, bitten wir Sie, die folgenden Regeln zu beachten.","audio":"8261af0cc736"},{"t":"**Ruhezeiten:** Von 22 bis 7 Uhr und von 12 bis 13 Uhr ist Ruhezeit. Am Sonntag und an Feiertagen bitten wir Sie, den ganzen Tag auf lärmige Arbeiten wie Staubsaugen oder Bohren zu verzichten.","audio":"6b58c863e424"},{"t":"**Waschküche:** Bitte halten Sie sich an den Waschplan. Wenn Sie Ihren Waschtag tauschen möchten, sprechen Sie mit Ihren Nachbarn. Reinigen Sie nach dem Waschen die Maschinen und das Sieb vom Tumbler.","audio":"4a9630b2fb70"},{"t":"**Treppenhaus:** Schuhe, Velos und Kinderwagen dürfen nicht im Treppenhaus stehen. Für Velos gibt es einen Veloraum im Keller.","audio":"1218bc065683"},{"t":"**Balkon:** Grillieren ist nur mit Gas- oder Elektrogrills erlaubt. Bitte schütteln Sie keine Teppiche über das Geländer.","audio":"9b411f9d0021"},{"t":"**Probleme:** Bei Schäden oder Problemen, z. B. mit der Heizung oder dem Wasser, wenden Sie sich bitte an den Hauswart, Herrn Rossi. Im Notfall ist er auch am Wochenende erreichbar.","audio":"e69b6c448fc9"},{"t":"Ihre Verwaltung","audio":"8cef3ad23b33"}],"glossary":[{"de":"sich wohlfühlen","en":"to feel comfortable"},{"de":"verzichten auf","en":"to refrain from, do without"},{"de":"lärmig (CH)","en":"noisy"},{"de":"das Sieb","en":"filter, sieve"},{"de":"das Geländer","en":"railing"},{"de":"sich wenden an","en":"to contact, turn to"},{"de":"erreichbar","en":"reachable"}],"questions":[{"type":"tf","q":"Am Sonntag sollte man nicht staubsaugen.","a":true,"why":""},{"type":"mc","q":"Was machen Sie, wenn Sie Ihren Waschtag tauschen möchten?","options":["Ich frage den Hauswart.","Ich spreche mit meinen Nachbarn.","Ich schreibe der Verwaltung."],"a":1},{"type":"mc","q":"Wo stellt man sein Velo hin?","options":["ins Treppenhaus","in den Veloraum im Keller","auf den Balkon"],"a":1},{"type":"tf","q":"Auf dem Balkon darf man mit Holzkohle grillieren.","a":false,"why":"Nur Gas- oder Elektrogrills sind erlaubt."},{"type":"tf","q":"Der Hauswart ist im Notfall auch am Wochenende erreichbar.","a":true,"why":""}]},"writing":{"task":"Ihr Nachbar hört jeden Abend bis Mitternacht laute Musik. Schreiben Sie ihm eine höfliche Nachricht (60–80 Wörter).","points":["Stellen Sie sich kurz vor.","Beschreiben Sie das Problem.","Bitten Sie höflich um eine Lösung.","Machen Sie einen Vorschlag."],"phrases":[{"de":"Ich bin Ihre neue Nachbarin / Ihr neuer Nachbar aus dem … Stock.","en":"I'm your new neighbour from the … floor."},{"de":"Leider ist es am Abend oft …","en":"Unfortunately it's often … in the evening."},{"de":"Könnten Sie bitte …?","en":"Could you please …?"},{"de":"Vielleicht könnten wir …","en":"Perhaps we could …"}],"model":"Lieber Herr Brunner\n\nIch bin Ihre neue Nachbarin aus dem zweiten Stock. Leider ist Ihre Musik am Abend oft sehr laut, manchmal bis Mitternacht. Ich muss jeden Morgen um sechs Uhr aufstehen und kann dann nicht gut schlafen. Könnten Sie die Musik ab 22 Uhr bitte etwas leiser machen? Vielleicht könnten wir auch kurz zusammen sprechen – ich würde Sie gern auf einen Kaffee einladen.\n\nFreundliche Grüsse\nCarla Ferreira","audio":"a29ca5f26f07"},"speaking":{"task":"Sie hören eine Situation. Bitten Sie höflich um etwas oder geben Sie einen Rat.","phrases":[{"de":"Könnten Sie bitte …?","en":"Could you please …?","audio":null},{"de":"Ich hätte eine Bitte.","en":"I have a request.","audio":"ce1b96a4f326"},{"de":"Wäre es möglich, dass …?","en":"Would it be possible that …?","audio":null},{"de":"An deiner Stelle würde ich …","en":"If I were you, I would …","audio":null},{"de":"Wie wäre es, wenn …?","en":"How about if …?","audio":null}],"prompts":[{"q":"Ihr Nachbar stellt sein Velo immer vor Ihre Tür. Bitten Sie ihn höflich, das Velo in den Veloraum zu stellen.","model":"Entschuldigung, Herr Schmid. Könnten Sie Ihr Velo bitte in den Veloraum stellen? Ich komme sonst kaum in meine Wohnung.","aq":"618bb178588a","am":"5b05690f1dee"},{"q":"Sie brauchen am Samstag eine Bohrmaschine. Fragen Sie Ihre Nachbarin.","model":"Hallo Frau Rossi, ich hätte eine Bitte. Könnten Sie mir am Samstag Ihre Bohrmaschine ausleihen?","aq":"3df1f4490f11","am":"76309e006ae4"},{"q":"Eine Freundin hat oft Streit mit ihrem Nachbarn. Geben Sie ihr einen Rat.","model":"An deiner Stelle würde ich einmal in Ruhe mit ihm sprechen. Vielleicht könntet ihr zusammen eine Lösung finden.","aq":"5a9cce512158","am":"13154dffdac4"},{"q":"Was würden Sie machen, wenn Sie ein Haus mit Garten hätten?","model":"Wenn ich ein Haus mit Garten hätte, würde ich Gemüse pflanzen und im Sommer oft mit Freunden grillieren.","aq":"2a3705390325","am":"23909e7456bd"}]}},{"id":7,"title":"Arbeit und Bewerbung","subtitle":"Stelleninserate, Bewerbung, Vorstellungsgespräch","level":"B1","theme":"Arbeit","focus":"Relativsätze (Nominativ, Akkusativ, Dativ, mit Präposition)","goals":[{"de":"Ich kann ein Stelleninserat verstehen und die wichtigsten Anforderungen erkennen.","en":"I can understand a job advert and identify the main requirements."},{"de":"Ich kann in einem Vorstellungsgespräch über meine Erfahrung und meine Stärken sprechen.","en":"I can talk about my experience and strengths in a job interview."},{"de":"Ich kann Personen und Dinge genauer beschreiben (Relativsätze).","en":"I can describe people and things more precisely."}],"vocab":[{"id":"7-0","de":"die Stelle","forms":"-n","en":"job, position","ex":"Ich habe eine neue Stelle gefunden.","exEn":"I've found a new job.","aw":"72bbcab3d8bf","ae":"4046dfc8cb3a"},{"id":"7-1","de":"das Stelleninserat","forms":"-e","en":"job advert (CH)","ex":"Das Stelleninserat war auf der Website der Firma.","exEn":"The job advert was on the company's website.","aw":"516b15e5c05a","ae":"e7001cb40eb3"},{"id":"7-2","de":"die Bewerbung","forms":"-en","en":"application","ex":"Ich habe meine Bewerbung gestern abgeschickt.","exEn":"I sent off my application yesterday.","aw":"7574a3cb9655","ae":"933c45ca09c4"},{"id":"7-3","de":"der Lebenslauf","forms":"Lebensläufe","en":"CV, résumé","ex":"Mein Lebenslauf ist zwei Seiten lang.","exEn":"My CV is two pages long.","aw":"934d90988915","ae":"da63157bc9d6"},{"id":"7-4","de":"das Vorstellungsgespräch","forms":"-e","en":"job interview","ex":"Morgen habe ich ein Vorstellungsgespräch.","exEn":"I have a job interview tomorrow.","aw":"252c3df08f95","ae":"163a06b0e43b"},{"id":"7-5","de":"die Erfahrung","forms":"-en","en":"experience","ex":"Ich habe fünf Jahre Erfahrung in der Logistik.","exEn":"I have five years' experience in logistics.","aw":"ac57a6ad9066","ae":"eedaf0e2bc08"},{"id":"7-6","de":"die Kenntnisse","forms":"(Pl.)","en":"knowledge, skills","ex":"Gute Deutschkenntnisse sind wichtig.","exEn":"Good German skills are important.","aw":"bf9b0ff3ab7c","ae":"c40d1977e9d0"},{"id":"7-7","de":"die Voraussetzung","forms":"-en","en":"requirement","ex":"Ein Führerschein ist Voraussetzung für diese Stelle.","exEn":"A driving licence is a requirement for this job.","aw":"e95e803c4eee","ae":"7738acc6adbe"},{"id":"7-8","de":"die Aufgabe","forms":"-n","en":"task, duty","ex":"Was sind Ihre Aufgaben?","exEn":"What are your duties?","aw":"0ce80fbf99b3","ae":"cc2a83cc7518"},{"id":"7-9","de":"verantwortlich für","forms":"–","en":"responsible for","ex":"Ich bin für die Tourenplanung verantwortlich.","exEn":"I'm responsible for route planning.","aw":"73ec0dce420d","ae":"7b846206b40d"},{"id":"7-10","de":"der Lohn","forms":"Löhne","en":"wage, salary","ex":"Der Lohn ist höher als bei meiner alten Stelle.","exEn":"The salary is higher than at my old job.","aw":"7e8e440416a5","ae":"4d1240353aa5"},{"id":"7-11","de":"das Pensum","forms":"Pensen","en":"workload in percent (CH)","ex":"Die Stelle hat ein Pensum von achtzig Prozent.","exEn":"The job is an eighty percent position.","aw":"2e358e412369","ae":"1988dd8d7e74"},{"id":"7-12","de":"die Teilzeit","forms":"–","en":"part-time","ex":"Ich möchte lieber Teilzeit arbeiten.","exEn":"I'd rather work part-time.","aw":"210ab03c1e59","ae":"b8ce8b36282a"},{"id":"7-13","de":"die Probezeit","forms":"-en","en":"probation period","ex":"Die Probezeit dauert drei Monate.","exEn":"The probation period lasts three months.","aw":"2330d26e6d10","ae":"5bf68bd02aee"},{"id":"7-14","de":"die Kündigungsfrist","forms":"-en","en":"notice period","ex":"Meine Kündigungsfrist beträgt zwei Monate.","exEn":"My notice period is two months.","aw":"479d4d0159cf","ae":"ea2af824175e"},{"id":"7-15","de":"der Arbeitgeber","forms":"-","en":"employer","ex":"Mein Arbeitgeber bezahlt den Deutschkurs.","exEn":"My employer pays for the German course.","aw":"4f3407d4e8d7","ae":"d4f5eeae171a"},{"id":"7-16","de":"die Weiterbildung","forms":"-en","en":"further training","ex":"Die Firma bietet viele Weiterbildungen an.","exEn":"The company offers a lot of further training.","aw":"c1f64892c9bb","ae":"f534f8effb67"},{"id":"7-17","de":"das Arbeitszeugnis","forms":"-se","en":"employer's reference","ex":"Mein Arbeitszeugnis ist sehr gut.","exEn":"My reference is very good.","aw":"55990501a0ea","ae":"79702e8f207c"},{"id":"7-18","de":"zuverlässig","forms":"–","en":"reliable","ex":"Sie ist sehr zuverlässig und pünktlich.","exEn":"She is very reliable and punctual.","aw":"5a6b6964183e","ae":"301877b52716"},{"id":"7-19","de":"selbstständig","forms":"–","en":"independent(ly)","ex":"In dieser Position muss man selbstständig arbeiten.","exEn":"In this position you have to work independently.","aw":"6dcbb966d2c7","ae":"1fac4c5a0655"}],"swiss":[{"ch":"das Pensum","std":"–","en":"workload in percent – 100 % is full-time, 80 % is four days a week"},{"ch":"der Lohn","std":"das Gehalt","en":"salary (in Switzerland \"Lohn\" is used for all jobs)"},{"ch":"die/der Lernende","std":"die/der Auszubildende","en":"apprentice"},{"ch":"die Ferien","std":"der Urlaub","en":"holidays from work"}],"dialogue":{"title":"Das Vorstellungsgespräch","intro":"Carla hat sich als Teamleiterin bei der Nordlog AG beworben. Herr Graf aus der Personalabteilung führt das Gespräch.","speakers":{"F":"Carla","M":"Herr Graf"},"lines":[{"s":"M","de":"Frau Ferreira, schön, dass Sie da sind. Erzählen Sie doch bitte kurz etwas über sich.","en":"Ms Ferreira, nice that you're here. Please tell us a little about yourself.","audio":"d7eec775949d"},{"s":"F","de":"Gern. Ich komme aus Portugal und lebe seit einem Jahr in Winterthur. Zurzeit arbeite ich als Disponentin bei einer Firma, die Ersatzteile für Maschinen transportiert.","en":"Of course. I'm from Portugal and have been living in Winterthur for a year. At the moment I work as a dispatcher at a company that transports spare parts for machines.","audio":"ca3f37c88d8b"},{"s":"M","de":"Was genau sind dort Ihre Aufgaben?","en":"What exactly are your duties there?","audio":"36099e240d48"},{"s":"F","de":"Ich plane die Touren für unsere Fahrer und bin für die Kommunikation mit den Kunden verantwortlich. Das ist eine Arbeit, die mir viel Spass macht.","en":"I plan the routes for our drivers and I'm responsible for communication with customers. It's work that I really enjoy.","audio":"887c6014d797"},{"s":"M","de":"Und warum möchten Sie die Stelle wechseln?","en":"And why do you want to change jobs?","audio":"38fcd3e97117"},{"s":"F","de":"Ich suche eine Stelle, in der ich mehr Verantwortung übernehmen kann. In Ihrem Inserat steht, dass die Teamleiterin ein Team von sechs Personen führt. Das finde ich sehr spannend.","en":"I'm looking for a job in which I can take on more responsibility. Your advert says that the team leader manages a team of six people. I find that very exciting.","audio":"8bbb04ab6382"},{"s":"M","de":"Haben Sie schon Führungserfahrung?","en":"Do you already have management experience?","audio":"24c37fd6d1fc"},{"s":"F","de":"Ja. In Portugal habe ich zwei Jahre lang ein kleines Team geleitet. Die Kollegen, mit denen ich damals gearbeitet habe, schreiben mir heute noch.","en":"Yes. In Portugal I led a small team for two years. The colleagues I worked with back then still write to me today.","audio":"43b2ff4e5b81"},{"s":"M","de":"Sehr schön. Und wie sieht es mit Ihren Deutschkenntnissen aus? Unsere Kunden sprechen fast alle Deutsch oder Schweizerdeutsch.","en":"Very nice. And what about your German skills? Almost all our customers speak German or Swiss German.","audio":"ebc34dd5092d"},{"s":"F","de":"Ich lerne jeden Tag und mache im Frühling die fide-Prüfung. Schweizerdeutsch verstehe ich schon ein bisschen, aber sprechen kann ich es noch nicht.","en":"I study every day and I'm taking the fide exam in the spring. I can already understand a bit of Swiss German, but I can't speak it yet.","audio":"f01d49b26ae5"},{"s":"M","de":"Das kommt schon noch! Haben Sie Fragen an uns?","en":"That will come! Do you have any questions for us?","audio":"4ea71e767318"},{"s":"F","de":"Ja. Ist die Stelle ein Hundert-Prozent-Pensum, oder wären auch achtzig Prozent möglich?","en":"Yes. Is the job a hundred percent position, or would eighty percent also be possible?","audio":"0f4306fbd70d"},{"s":"M","de":"Wir suchen jemanden für hundert Prozent, aber nach der Probezeit können wir gern darüber sprechen.","en":"We're looking for someone at one hundred percent, but after the probation period we'd be happy to discuss it.","audio":"98f52c551d66"},{"s":"F","de":"Und gibt es bei Ihnen Möglichkeiten zur Weiterbildung?","en":"And are there opportunities for further training with you?","audio":"3328651571b6"},{"s":"M","de":"Ja, wir bezahlen zum Beispiel Kurse, die mit der Arbeit zu tun haben – auch Deutschkurse.","en":"Yes, for example we pay for courses that are related to the work – including German courses.","audio":"8a4f39430dfe"},{"s":"F","de":"Das klingt sehr gut.","en":"That sounds very good.","audio":"80d3d5e34cde"},{"s":"M","de":"Wir melden uns bis Ende nächster Woche bei Ihnen. Vielen Dank für das Gespräch!","en":"We'll get back to you by the end of next week. Thank you very much for the interview!","audio":"af123bec7a5e"},{"s":"F","de":"Ich danke Ihnen. Auf Wiedersehen!","en":"Thank you. Goodbye!","audio":"a6439b090a06"}],"questions":[{"type":"tf","q":"Carla arbeitet zurzeit als Disponentin.","a":true,"why":""},{"type":"mc","q":"Warum möchte Carla die Stelle wechseln?","options":["Sie möchte mehr verdienen.","Sie möchte mehr Verantwortung übernehmen.","Sie hat Probleme mit dem Chef."],"a":1},{"type":"mc","q":"Wie gross ist das Team, das die Teamleiterin führt?","options":["vier Personen","sechs Personen","zehn Personen"],"a":1},{"type":"tf","q":"Carla spricht schon gut Schweizerdeutsch.","a":false,"why":"Sie versteht ein bisschen, aber sie kann es noch nicht sprechen."},{"type":"mc","q":"Was sagt Herr Graf zum Pensum?","options":["Achtzig Prozent sind sofort möglich.","Nach der Probezeit kann man darüber sprechen.","Die Stelle ist nur Teilzeit."],"a":1}]},"grammar":{"title":"Relativsätze","summary":"Ein Relativsatz beschreibt ein Nomen genauer. Das Verb steht am Ende.","sections":[{"h":"Zwei Sätze – ein Satz","text":"Der Relativsatz steht direkt **nach dem Nomen**, das er beschreibt. Er beginnt mit einem **Relativpronomen** und endet mit dem **konjugierten Verb**.","examples":[{"de":"Das ist eine Arbeit. Die Arbeit macht mir Spass. → Das ist eine Arbeit, ==die== mir Spass ==macht==.","en":"That's a job that I enjoy.","audio":"780b4022c0a0"},{"de":"Die Firma transportiert Ersatzteile. → Ich arbeite bei einer Firma, ==die== Ersatzteile ==transportiert==.","en":"I work for a company that transports spare parts.","audio":"02240b434d03"}]},{"h":"Die Relativpronomen","text":"**Genus und Zahl** kommen vom Nomen davor. **Der Kasus** kommt vom Verb im Relativsatz.","table":[["Kasus","maskulin","feminin","neutral","Plural"],["Nominativ","der","die","das","die"],["Akkusativ","den","die","das","die"],["Dativ","dem","der","dem","==denen=="]]},{"h":"Welcher Kasus?","examples":[{"de":"Nominativ → Der Kollege, ==der== im dritten Stock arbeitet, heisst Luca. (Er arbeitet …)","en":"The colleague who works on the third floor is called Luca.","audio":"f1eacdde38be"},{"de":"Akkusativ → Der Lebenslauf, ==den== ich geschrieben habe, ist zwei Seiten lang. (Ich habe ihn geschrieben.)","en":"The CV I wrote is two pages long.","audio":"5334248bea7a"},{"de":"Dativ → Die Chefin, ==der== ich die Bewerbung geschickt habe, heisst Frau Graf. (Ich habe ihr … geschickt.)","en":"The boss I sent the application to is called Ms Graf.","audio":"f3c328d0460d"}]},{"h":"Relativsatz mit Präposition","text":"Braucht das Verb eine Präposition, steht sie **vor** dem Relativpronomen. Bei Orten kann man auch **wo** sagen.","examples":[{"de":"Das sind die Kollegen, ==mit denen== ich arbeite.","en":"Those are the colleagues I work with.","audio":"bd94058c2e3c"},{"de":"Ich suche eine Stelle, ==in der== ich mehr Verantwortung habe.","en":"I'm looking for a job in which I have more responsibility.","audio":"8ec28bc5460e"},{"de":"Winterthur ist die Stadt, ==wo== ich wohne.","en":"Winterthur is the town where I live.","audio":"45e3a5678050"}]}],"tip":"Achtung beim Dativ Plural: Das Relativpronomen heisst „denen\", nicht „den\". Die Kunden, mit denen ich telefoniere, sind sehr freundlich."},"exercises":[{"type":"choice","title":"Welches Relativpronomen?","items":[{"q":"Das ist die Stelle, ___ mich interessiert.","options":["die","der","das"],"a":0,"full":"Das ist die Stelle, die mich interessiert.","audio":"8e41cf4943f2"},{"q":"Der Lebenslauf, ___ du mir geschickt hast, ist sehr gut.","options":["den","der","dem"],"a":0,"full":"Der Lebenslauf, den du mir geschickt hast, ist sehr gut.","audio":"50b69bcfc86c"},{"q":"Wie heisst der Kollege, ___ du geholfen hast?","options":["dem","den","der"],"a":0,"full":"Wie heisst der Kollege, dem du geholfen hast?","audio":"68971ec554f9"},{"q":"Das sind die Kunden, mit ___ ich jeden Tag telefoniere.","options":["denen","den","die"],"a":0,"full":"Das sind die Kunden, mit denen ich jeden Tag telefoniere.","audio":"24df6e9a45bb"},{"q":"Ich arbeite in einem Team, ___ sehr international ist.","options":["das","dem","der"],"a":0,"full":"Ich arbeite in einem Team, das sehr international ist.","audio":"7274f3773766"},{"q":"Die Firma, für ___ ich arbeite, hat zweihundert Mitarbeitende.","options":["die","der","das"],"a":0,"full":"Die Firma, für die ich arbeite, hat zweihundert Mitarbeitende.","audio":"f834e392da7e"},{"q":"Wo ist das Formular, ___ ich unterschreiben muss?","options":["das","dem","den"],"a":0,"full":"Wo ist das Formular, das ich unterschreiben muss?","audio":"872cf942b7c8"},{"q":"Herr Graf ist der Mann, ___ das Vorstellungsgespräch führt.","options":["der","den","dem"],"a":0,"full":"Herr Graf ist der Mann, der das Vorstellungsgespräch führt.","audio":"6b8b37a884d9"}]},{"type":"gap","title":"Ergänzen Sie das Relativpronomen (mit Präposition, wenn nötig)","items":[{"q":"Das ist die Chefin, ___ ich sehr schätze.","a":["die"],"full":"Das ist die Chefin, die ich sehr schätze.","audio":"8165ca1de1a6"},{"q":"Ich suche eine Stelle, ___ ich mehr Verantwortung habe. (in)","a":["in der"],"full":"Ich suche eine Stelle, in der ich mehr Verantwortung habe.","audio":"8ec28bc5460e"},{"q":"Kennst du den Kollegen, ___ im dritten Stock arbeitet?","a":["der"],"full":"Kennst du den Kollegen, der im dritten Stock arbeitet?","audio":"22fef265e740"},{"q":"Die Kurse, ___ die Firma bezahlt, sind sehr gut.","a":["die"],"full":"Die Kurse, die die Firma bezahlt, sind sehr gut.","audio":"cd9594e61104"},{"q":"Das Team, mit ___ ich arbeite, ist super.","a":["dem"],"full":"Das Team, mit dem ich arbeite, ist super.","audio":"03396eaee96f"},{"q":"Die Lernenden, ___ ich helfe, sind sehr motiviert.","a":["denen"],"full":"Die Lernenden, denen ich helfe, sind sehr motiviert.","audio":"d156eb0b28be"}]},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Das ist eine Arbeit, die mir viel Spass macht."],"tokens":["Das","ist","eine","Arbeit,","die","mir","viel","Spass","macht."],"audio":"d86f5ee8f2df"},{"a":["Ich suche eine Stelle, in der ich mehr Verantwortung habe."],"tokens":["Ich","suche","eine","Stelle,","in","der","ich","mehr","Verantwortung","habe."],"audio":"8ec28bc5460e"},{"a":["Der Lebenslauf, den ich geschrieben habe, ist zwei Seiten lang."],"tokens":["Der","Lebenslauf,","den","ich","geschrieben","habe,","ist","zwei","Seiten","lang."],"audio":"5334248bea7a"},{"a":["Die Kollegen, mit denen ich arbeite, sind sehr nett."],"tokens":["Die","Kollegen,","mit","denen","ich","arbeite,","sind","sehr","nett."],"audio":"7ea75de05f31"},{"a":["Winterthur ist die Stadt, in der ich seit einem Jahr lebe."],"tokens":["Winterthur","ist","die","Stadt,","in","der","ich","seit","einem","Jahr","lebe."],"audio":"474154ce977f"}]},{"type":"match","title":"Was ist das? Definitionen mit Relativsätzen","items":[{"l":"Ein Lebenslauf ist ein Dokument,","r":"in dem man seine Ausbildung und Berufserfahrung beschreibt."},{"l":"Eine Arbeitgeberin ist eine Person oder Firma,","r":"die Menschen eine Stelle gibt."},{"l":"Die Probezeit ist die Zeit,","r":"in der man schnell kündigen kann."},{"l":"Ein Arbeitszeugnis ist ein Dokument,","r":"das der alte Arbeitgeber schreibt."},{"l":"Lernende sind junge Leute,","r":"die eine Lehre machen."}]},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Das ist eine Arbeit, die mir viel Spass macht.","audio":"88d2487f05a3"},{"a":"Ich suche eine Stelle mit mehr Verantwortung.","audio":"30bf334bddf0"},{"a":"Die Kollegen, mit denen ich arbeite, sind sehr nett.","audio":"13c068bc155a"},{"a":"Wir melden uns bis Ende nächster Woche bei Ihnen.","audio":"3323e8455351"}]}],"reading":{"title":"Stelleninserat – Teamleiterin / Teamleiter Logistik","kind":"Stelleninserat","paras":[{"t":"**Nordlog AG – Ihre Partnerin für Logistik in der Ostschweiz**\nFür unser Lager in Winterthur suchen wir per 1. Januar oder nach Vereinbarung eine Teamleiterin oder einen Teamleiter Logistik (80–100 %).","audio":"a82cc254a32e"},{"t":"**Ihre Aufgaben:** Sie führen ein Team von sechs Mitarbeitenden und planen die Einsätze. Sie sind für die Qualität und die Pünktlichkeit der Lieferungen verantwortlich. Für unsere Kundinnen und Kunden sind Sie die wichtigste Ansprechperson.","audio":"ffee40b53ced"},{"t":"**Ihr Profil:** Sie haben eine abgeschlossene Ausbildung in der Logistik oder eine ähnliche Ausbildung und mindestens drei Jahre Berufserfahrung, idealerweise auch Führungserfahrung. Sie sprechen gut Deutsch (mindestens B1); Englisch ist von Vorteil. Sie arbeiten selbstständig und zuverlässig und bleiben auch in stressigen Situationen ruhig.","audio":"f8b8859c8879"},{"t":"**Wir bieten:** ein junges, internationales Team, moderne Arbeitsplätze, flexible Arbeitszeiten, fünf Wochen Ferien und bezahlte Weiterbildungen.","audio":"c9a880fc9025"},{"t":"Interessiert? Dann senden Sie Ihre vollständigen Unterlagen – Lebenslauf, Zeugnisse und Motivationsschreiben – bis zum 31. Oktober über unser Online-Portal. Wir freuen uns auf Sie!","audio":"48b2eaac7a5e"}],"glossary":[{"de":"nach Vereinbarung","en":"by arrangement"},{"de":"der Einsatz","en":"shift, assignment"},{"de":"die Ansprechperson","en":"contact person"},{"de":"abgeschlossen","en":"completed"},{"de":"von Vorteil","en":"an advantage"},{"de":"die Unterlagen (Pl.)","en":"documents"}],"questions":[{"type":"tf","q":"Die Stelle ist auch mit einem Pensum von 80 Prozent möglich.","a":true,"why":""},{"type":"mc","q":"Wie viele Personen führt die Teamleiterin oder der Teamleiter?","options":["drei","sechs","acht"],"a":1},{"type":"mc","q":"Welche Sprachkenntnisse braucht man?","options":["Deutsch, mindestens B1","Englisch auf C1-Niveau","Französisch"],"a":0},{"type":"tf","q":"Man braucht mindestens fünf Jahre Berufserfahrung.","a":false,"why":"Man braucht mindestens drei Jahre."},{"type":"mc","q":"Was bietet die Firma?","options":["ein Geschäftsauto","fünf Wochen Ferien","eine Wohnung"],"a":1}]},"writing":{"task":"Schreiben Sie eine kurze Bewerbung auf das Stelleninserat (80–100 Wörter).","points":["Warum schreiben Sie?","Welche Erfahrung haben Sie?","Warum interessiert Sie die Stelle?","Wann können Sie anfangen?"],"phrases":[{"de":"Mit grossem Interesse habe ich Ihr Inserat gelesen.","en":"I read your advert with great interest."},{"de":"Zurzeit arbeite ich als … bei …","en":"I currently work as … at …"},{"de":"Ich suche eine Stelle, in der …","en":"I'm looking for a job in which …"},{"de":"Ich könnte am … anfangen.","en":"I could start on …"},{"de":"Über eine Einladung zu einem Vorstellungsgespräch würde ich mich sehr freuen.","en":"I would be very pleased to be invited to an interview."}],"model":"Sehr geehrte Frau Graf\n\nMit grossem Interesse habe ich Ihr Inserat für die Stelle als Teamleiterin Logistik gelesen. Zurzeit arbeite ich als Disponentin bei einer Firma in Winterthur, wo ich die Touren für zwölf Fahrer plane. In Portugal habe ich zwei Jahre lang ein kleines Team geleitet. Jetzt suche ich eine Stelle, in der ich wieder mehr Verantwortung übernehmen kann. Ich arbeite selbstständig und zuverlässig, und mein Deutsch verbessere ich jeden Tag. Ich könnte am 1. Februar anfangen. Über eine Einladung zu einem Vorstellungsgespräch würde ich mich sehr freuen.\n\nFreundliche Grüsse\nCarla Ferreira","audio":"355226fec43e"},"speaking":{"task":"Im Vorstellungsgespräch – beantworten Sie die Fragen ausführlich (drei bis vier Sätze).","phrases":[{"de":"Zurzeit arbeite ich als …","en":"At the moment I work as …","audio":null},{"de":"Ich habe … Jahre Erfahrung in …","en":"I have … years' experience in …","audio":null},{"de":"Meine Stärken sind …","en":"My strengths are …","audio":null},{"de":"Ich suche eine Stelle, in der …","en":"I'm looking for a job in which …","audio":null},{"de":"Wann könnte ich anfangen?","en":"When could I start?","audio":"efe54aaa22d2"}],"prompts":[{"q":"Erzählen Sie bitte etwas über Ihre berufliche Erfahrung.","model":"Ich arbeite seit einem Jahr als Disponentin in Winterthur. Vorher war ich fünf Jahre bei einer Logistikfirma in Porto, wo ich auch ein kleines Team geleitet habe.","aq":"79db14ca966b","am":"bc1e6e596bc6"},{"q":"Was sind Ihre Stärken?","model":"Ich bin zuverlässig und gut organisiert, und ich bleibe auch in stressigen Situationen ruhig. Meine Kollegen sagen, dass ich gut zuhören kann.","aq":"572ea2b589b2","am":"dfe6b655cc2e"},{"q":"Beschreiben Sie eine Aufgabe, die Ihnen besonders gut gefällt.","model":"Am liebsten mache ich Aufgaben, bei denen ich Probleme lösen und mit Menschen sprechen kann – zum Beispiel, wenn eine Lieferung nicht pünktlich ist.","aq":"618cc771284f","am":"0bbb219f2bfc"},{"q":"Wo sehen Sie sich in fünf Jahren?","model":"In fünf Jahren möchte ich ein grösseres Team führen und sehr gut Deutsch sprechen. Vielleicht verstehe ich dann auch Schweizerdeutsch!","aq":"024f69f9923d","am":"5f7fb9f058ff"}]}},{"id":8,"title":"Freizeit und Vereine","subtitle":"Hobbys, Pläne und Leute kennenlernen","level":"B1","theme":"Freizeit","focus":"Verben mit Präpositionen, da-/wo-Wörter, Infinitiv mit zu","goals":[{"de":"Ich kann über meine Hobbys und Interessen sprechen.","en":"I can talk about my hobbies and interests."},{"de":"Ich kann einen Zeitungsartikel über einen Verein verstehen.","en":"I can understand a newspaper article about a club."},{"de":"Ich kann Verben mit Präpositionen richtig benutzen (sich freuen auf, sich interessieren für …).","en":"I can use verbs with prepositions correctly."}],"vocab":[{"id":"8-0","de":"der Verein","forms":"-e","en":"club, association","ex":"In der Schweiz gibt es sehr viele Vereine.","exEn":"There are a great many clubs in Switzerland.","aw":"5609e277669c","ae":"a38e41b98475"},{"id":"8-1","de":"das Mitglied","forms":"-er","en":"member","ex":"Ich bin seit zwei Jahren Mitglied im Turnverein.","exEn":"I've been a member of the gymnastics club for two years.","aw":"fed93849f1bb","ae":"4b723718de94"},{"id":"8-2","de":"der Mitgliederbeitrag","forms":"-beiträge","en":"membership fee (CH)","ex":"Der Mitgliederbeitrag kostet fünfzig Franken pro Jahr.","exEn":"The membership fee is fifty francs a year.","aw":"4e5c115cfda7","ae":"11a0088bde99"},{"id":"8-3","de":"sich interessieren für","forms":"hat sich interessiert","en":"to be interested in","ex":"Ich interessiere mich für Fotografie.","exEn":"I'm interested in photography.","aw":"984ee70b8b1f","ae":"adacac5c4e58"},{"id":"8-4","de":"sich freuen auf","forms":"hat sich gefreut","en":"to look forward to","ex":"Ich freue mich auf das Wochenende.","exEn":"I'm looking forward to the weekend.","aw":"0f7ca9678d0e","ae":"82f85f6d30db"},{"id":"8-5","de":"sich freuen über","forms":"hat sich gefreut","en":"to be pleased about","ex":"Sie hat sich sehr über die Blumen gefreut.","exEn":"She was very pleased about the flowers.","aw":"6f22384877c8","ae":"5398f235fcca"},{"id":"8-6","de":"teilnehmen an","forms":"hat teilgenommen","en":"to take part in","ex":"Nimmst du am Sommerfest teil?","exEn":"Are you taking part in the summer party?","aw":"310d45729c87","ae":"fb526f08d4c7"},{"id":"8-7","de":"sich erinnern an","forms":"hat sich erinnert","en":"to remember","ex":"Ich erinnere mich gut an meinen ersten Tag in der Schweiz.","exEn":"I remember my first day in Switzerland well.","aw":"01b2cb5ce1c4","ae":"ac299bce4007"},{"id":"8-8","de":"träumen von","forms":"hat geträumt","en":"to dream of","ex":"Er träumt von einer Reise nach Japan.","exEn":"He dreams of a trip to Japan.","aw":"4d7661940c9d","ae":"19a84123fe80"},{"id":"8-9","de":"sich kümmern um","forms":"hat sich gekümmert","en":"to take care of","ex":"Wer kümmert sich um die Getränke?","exEn":"Who's taking care of the drinks?","aw":"6a4e6f58dc94","ae":"25cbf72fd318"},{"id":"8-10","de":"Lust haben auf","forms":"hatte Lust","en":"to feel like","ex":"Hast du Lust auf einen Kaffee?","exEn":"Do you feel like a coffee?","aw":"9c48a1f7f487","ae":"0ab2a94af478"},{"id":"8-11","de":"der Ausflug","forms":"Ausflüge","en":"outing, excursion","ex":"Am Sonntag machen wir einen Ausflug an den See.","exEn":"On Sunday we're making a trip to the lake.","aw":"343b54ffd6e5","ae":"27b76ddf3dab"},{"id":"8-12","de":"die Veranstaltung","forms":"-en","en":"event","ex":"Die Veranstaltung beginnt um neunzehn Uhr.","exEn":"The event starts at seven p.m.","aw":"4c6f58bee877","ae":"7c9bab52af9f"},{"id":"8-13","de":"ehrenamtlich","forms":"–","en":"voluntary, unpaid","ex":"Sie arbeitet ehrenamtlich im Quartierverein.","exEn":"She volunteers in the neighbourhood association.","aw":"f1d47da5ef0b","ae":"aa36cf4abd3f"},{"id":"8-14","de":"der Chor","forms":"Chöre","en":"choir","ex":"Meine Schwester singt in einem Chor.","exEn":"My sister sings in a choir.","aw":"e526965e38de","ae":"0d8939cd567c"},{"id":"8-15","de":"die Probe","forms":"-n","en":"rehearsal","ex":"Die Chorprobe ist jeden Dienstag.","exEn":"Choir rehearsal is every Tuesday.","aw":"3f820d92f346","ae":"cd1f56a08551"},{"id":"8-16","de":"die Wanderung","forms":"-en","en":"hike","ex":"Die Wanderung dauert ungefähr vier Stunden.","exEn":"The hike takes about four hours.","aw":"67cfbbda5da3","ae":"d63887efa742"},{"id":"8-17","de":"sich entspannen","forms":"hat sich entspannt","en":"to relax","ex":"Am Abend entspanne ich mich mit einem Buch.","exEn":"In the evening I relax with a book.","aw":"13a13234f996","ae":"3049d3467ef2"},{"id":"8-18","de":"anfangen mit","forms":"hat angefangen","en":"to start (with)","ex":"Ich habe letztes Jahr mit Yoga angefangen.","exEn":"I started yoga last year.","aw":"cf021ed14eb6","ae":"e262572ad9ae"},{"id":"8-19","de":"aufhören mit","forms":"hat aufgehört","en":"to stop, give up","ex":"Er hat mit dem Rauchen aufgehört.","exEn":"He has stopped smoking.","aw":"b3829b1179c9","ae":"92a15a492a9f"}],"swiss":[{"ch":"der Mitgliederbeitrag","std":"der Mitgliedsbeitrag","en":"membership fee"},{"ch":"das Quartier","std":"das Viertel","en":"neighbourhood"},{"ch":"der Neuzuzüger","std":"der Neubürger","en":"newcomer to a town; many towns hold a welcome event for them"}],"dialogue":{"title":"Hast du Lust mitzukommen?","intro":"In der Mittagspause spricht Carla mit ihrem Kollegen Luca über das Wochenende.","speakers":{"F":"Carla","M":"Luca"},"lines":[{"s":"M","de":"Na, Carla, hast du schon Pläne fürs Wochenende?","en":"So, Carla, do you have plans for the weekend yet?","audio":"6928f177f421"},{"s":"F","de":"Noch nicht. Ehrlich gesagt habe ich keine Lust, schon wieder allein zu Hause zu sitzen. Ich möchte mehr Leute kennenlernen.","en":"Not yet. To be honest, I don't feel like sitting at home alone again. I'd like to get to know more people.","audio":"16cae25f6f51"},{"s":"M","de":"Warum gehst du nicht in einen Verein? So habe ich hier die meisten meiner Freunde gefunden.","en":"Why don't you join a club? That's how I found most of my friends here.","audio":"fb738bb5a7a1"},{"s":"F","de":"In einen Verein? Woran denkst du denn?","en":"A club? What are you thinking of?","audio":"c3e9765b91d6"},{"s":"M","de":"Ich bin zum Beispiel in einem Wanderverein. Wir machen jeden Monat einen Ausflug in die Berge. Am Samstag wandern wir auf den Säntis.","en":"I'm in a hiking club, for example. We go on a trip to the mountains every month. On Saturday we're hiking up the Säntis.","audio":"79cb3ceca785"},{"s":"F","de":"Das klingt toll! Ich interessiere mich sehr für die Berge, aber ich habe keine gute Ausrüstung.","en":"That sounds great! I'm very interested in the mountains, but I don't have good gear.","audio":"3630f3fc4e6c"},{"s":"M","de":"Darum musst du dich nicht kümmern. Gute Schuhe reichen am Anfang. Wie wäre es, wenn du einfach einmal mitkommst?","en":"You don't need to worry about that. Good shoes are enough at the start. How about just coming along once?","audio":"eaebb5354f77"},{"s":"F","de":"Gern! Ich freue mich schon darauf. Kostet das etwas?","en":"I'd love to! I'm already looking forward to it. Does it cost anything?","audio":"c0265222e99c"},{"s":"M","de":"Nicht viel. Der Mitgliederbeitrag ist fünfzig Franken pro Jahr, aber beim ersten Mal ist es gratis.","en":"Not much. The membership fee is fifty francs a year, but the first time is free.","audio":"661a4e228528"},{"s":"F","de":"Super. Weisst du, ich träume auch davon, in einem Chor zu singen. In Porto habe ich jahrelang gesungen.","en":"Great. You know, I also dream of singing in a choir. In Porto I sang for years.","audio":"f8d28affbec2"},{"s":"M","de":"Wirklich? Meine Schwester singt in einem Chor in der Altstadt. Sie suchen immer neue Stimmen. Ich kann sie fragen, wann die Proben sind.","en":"Really? My sister sings in a choir in the old town. They're always looking for new voices. I can ask her when the rehearsals are.","audio":"3227b4752315"},{"s":"F","de":"Das wäre wunderbar! Aber vielleicht ist mein Deutsch noch nicht gut genug …","en":"That would be wonderful! But maybe my German isn't good enough yet …","audio":"41d22d03c248"},{"s":"M","de":"Keine Angst. Sie singen sowieso oft auf Englisch oder Latein. Und in der Pause kannst du Deutsch üben.","en":"Don't worry. They often sing in English or Latin anyway. And you can practise German in the break.","audio":"34f7f7852b23"},{"s":"F","de":"Stimmt. Ich erinnere mich noch gut an meine erste Chorprobe in Porto – da war ich auch sehr nervös.","en":"True. I still remember my first choir rehearsal in Porto well – I was very nervous then too.","audio":"d09c8d719261"},{"s":"M","de":"Siehst du! Ich schicke dir heute Abend die Infos für Samstag. Und vergiss nicht, etwas zu essen mitzunehmen!","en":"See! I'll send you the info for Saturday tonight. And don't forget to bring something to eat!","audio":"aa7fd8182e15"},{"s":"F","de":"Mache ich. Danke, Luca!","en":"Will do. Thanks, Luca!","audio":"b682e975509f"}],"questions":[{"type":"tf","q":"Carla möchte mehr Leute kennenlernen.","a":true,"why":""},{"type":"mc","q":"Was macht Lucas Verein?","options":["Er macht jeden Monat einen Ausflug in die Berge.","Er spielt jede Woche Fussball.","Er singt in einem Chor."],"a":0},{"type":"tf","q":"Beim ersten Mal muss Carla fünfzig Franken bezahlen.","a":false,"why":"Beim ersten Mal ist es gratis."},{"type":"mc","q":"Wovon träumt Carla?","options":["von einem Haus in den Bergen","davon, in einem Chor zu singen","von einer Reise nach Porto"],"a":1},{"type":"mc","q":"Was soll Carla am Samstag mitnehmen?","options":["etwas zu essen","Wanderstöcke","ein Liederbuch"],"a":0}]},"grammar":{"title":"Verben mit Präpositionen, da-/wo-Wörter und zu + Infinitiv","summary":"Viele Verben haben eine feste Präposition. Lernen Sie Verb, Präposition und Kasus immer zusammen.","sections":[{"h":"Feste Präpositionen","table":[["Verb","Präposition","Beispiel"],["sich interessieren","für + Akk.","Ich interessiere mich für Musik."],["sich freuen","auf + Akk. (Zukunft)","Ich freue mich auf den Ausflug."],["sich freuen","über + Akk. (jetzt / vorher)","Ich freue mich über dein Geschenk."],["teilnehmen","an + Dat.","Sie nimmt an einem Kurs teil."],["sich erinnern","an + Akk.","Ich erinnere mich an den Tag."],["träumen","von + Dat.","Er träumt von einem Garten."],["sich kümmern","um + Akk.","Wer kümmert sich um den Hund?"],["warten","auf + Akk.","Wir warten auf den Bus."],["denken","an + Akk.","Ich denke oft an meine Familie."],["Angst haben","vor + Dat.","Sie hat Angst vor Hunden."]]},{"h":"Fragen – wo(r)- oder Präposition + wen/wem","text":"Fragt man nach einer **Sache**: **wo + Präposition** (vor einem Vokal: **wor-**). Fragt man nach einer **Person**: **Präposition + wen / wem**.","examples":[{"de":"==Wofür== interessierst du dich? – Für Musik.","en":"What are you interested in? – Music.","audio":"8993138568bf"},{"de":"==Worauf== wartest du? – Auf den Bus.","en":"What are you waiting for? – The bus.","audio":"566c0a7eaf27"},{"de":"==Auf wen== wartest du? – Auf Luca.","en":"Who are you waiting for? – Luca.","audio":"617d900dcd39"}]},{"h":"da(r)-Wörter","text":"Statt Präposition + Sache sagt man oft **da + Präposition** (vor einem Vokal: **dar-**). Bei Personen benutzt man ein Pronomen.","text2":"Ein **da-Wort** kann auch einen ganzen Nebensatz oder einen zu-Infinitiv ankündigen: *Ich träume ==davon==, in einem Chor zu singen. Ich freue mich ==darauf==, dass du kommst.*","examples":[{"de":"Freust du dich auf den Ausflug? – Ja, ich freue mich ==darauf==.","en":"Are you looking forward to the trip? – Yes, I'm looking forward to it.","audio":"eba4e9ed1985"},{"de":"Denkst du an den Termin? – Ja, ich denke ==daran==.","en":"Are you thinking about the appointment? – Yes, I'm thinking about it.","audio":"a6312af168c5"},{"de":"Denkst du an deine Mutter? – Ja, ich denke oft ==an sie==.","en":"Do you think about your mother? – Yes, I often think about her.","audio":"ad187b709e07"}]},{"h":"Infinitiv mit zu","text":"Nach vielen Ausdrücken steht ein **Infinitiv mit zu** am Satzende: *Lust haben, Zeit haben, vergessen, versuchen, anfangen, aufhören, es ist schön / wichtig / schwierig …*\nBei trennbaren Verben steht **zu** in der Mitte: *mit==zu==kommen, kennen==zu==lernen.*","examples":[{"de":"Hast du Lust, am Samstag ==mitzukommen==?","en":"Do you feel like coming along on Saturday?","audio":"d5591a96f8fd"},{"de":"Vergiss nicht, etwas zu essen ==mitzunehmen==.","en":"Don't forget to bring something to eat.","audio":"5a7bec54fe17"},{"de":"Es ist schön, neue Leute ==kennenzulernen==.","en":"It's nice to meet new people.","audio":"625825ddc728"}]}],"tip":"Kein „zu\" nach Modalverben: „Ich möchte mitkommen\" (nicht „Ich möchte mitzukommen\"). Und: sich freuen auf = etwas kommt noch; sich freuen über = etwas ist schon da."},"exercises":[{"type":"choice","title":"Welche Präposition passt?","items":[{"q":"Ich interessiere mich ___ Musik.","options":["für","an","auf"],"a":0,"full":"Ich interessiere mich für Musik.","audio":"f1983b750ae4"},{"q":"Wir freuen uns schon ___ die Ferien.","options":["auf","über","für"],"a":0,"full":"Wir freuen uns schon auf die Ferien.","audio":"2e6fb9610fc0"},{"q":"Nimmst du am Samstag ___ der Wanderung teil?","options":["an","auf","für"],"a":0,"full":"Nimmst du am Samstag an der Wanderung teil?","audio":"bb6a317d9ca9"},{"q":"Er erinnert sich gern ___ seine Kindheit.","options":["an","von","über"],"a":0,"full":"Er erinnert sich gern an seine Kindheit.","audio":"ae9e3305328d"},{"q":"Sie träumt ___ einem eigenen Garten.","options":["von","über","für"],"a":0,"full":"Sie träumt von einem eigenen Garten.","audio":"4f7fa1be92f6"},{"q":"Wer kümmert sich ___ die Katze, wenn du weg bist?","options":["um","für","auf"],"a":0,"full":"Wer kümmert sich um die Katze, wenn du weg bist?","audio":"006271e9e327"},{"q":"Ich habe mich sehr ___ dein Geschenk gefreut.","options":["über","auf","an"],"a":0,"full":"Ich habe mich sehr über dein Geschenk gefreut.","audio":"2b1c623831f4"},{"q":"Warte bitte ___ mich!","options":["auf","für","an"],"a":0,"full":"Warte bitte auf mich!","audio":"5bfed64ee2cf"}]},{"type":"gap","title":"wo(r)- oder da(r)-?","items":[{"q":"___ interessierst du dich? – Für Fotografie.","a":["Wofür"],"full":"Wofür interessierst du dich? – Für Fotografie.","audio":"65dc3ef797c0"},{"q":"___ wartest du? – Auf den Bus.","a":["Worauf"],"full":"Worauf wartest du? – Auf den Bus.","audio":"566c0a7eaf27"},{"q":"Freust du dich auf das Konzert? – Ja, ich freue mich sehr ___.","a":["darauf"],"full":"Freust du dich auf das Konzert? – Ja, ich freue mich sehr darauf.","audio":"e2c5a4b16bdf"},{"q":"Denkst du an den Termin? – Ja, ich denke ___.","a":["daran"],"full":"Denkst du an den Termin? – Ja, ich denke daran.","audio":"a6312af168c5"},{"q":"___ träumst du? – Von einer Reise nach Japan.","a":["Wovon"],"full":"Wovon träumst du? – Von einer Reise nach Japan.","audio":"4c3134beace1"},{"q":"Nimmst du an dem Kurs teil? – Nein, ich nehme nicht ___ teil.","a":["daran"],"full":"Nimmst du an dem Kurs teil? – Nein, ich nehme nicht daran teil.","audio":"4c7cf6837d3f"}]},{"type":"gap","title":"Infinitiv mit zu","items":[{"q":"Ich habe keine Lust, heute ___. (kochen)","a":["zu kochen"],"full":"Ich habe keine Lust, heute zu kochen.","audio":"09c60c04e291"},{"q":"Vergiss nicht, etwas zu essen ___. (mitnehmen)","a":["mitzunehmen"],"full":"Vergiss nicht, etwas zu essen mitzunehmen.","audio":"5a7bec54fe17"},{"q":"Es ist schön, neue Leute ___. (kennenlernen)","a":["kennenzulernen"],"full":"Es ist schön, neue Leute kennenzulernen.","audio":"625825ddc728"},{"q":"Ich versuche, jeden Tag Deutsch ___. (sprechen)","a":["zu sprechen"],"full":"Ich versuche, jeden Tag Deutsch zu sprechen.","audio":"95ab3e3e4bdd"},{"q":"Wann hast du angefangen, Klavier ___? (spielen)","a":["zu spielen"],"full":"Wann hast du angefangen, Klavier zu spielen?","audio":"910f41cd26ee"},{"q":"Hast du Zeit, am Samstag ___? (mitkommen)","a":["mitzukommen"],"full":"Hast du Zeit, am Samstag mitzukommen?","audio":"15c3b7bbad9f"}]},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Ich interessiere mich schon lange für Fotografie."],"tokens":["Ich","interessiere","mich","schon","lange","für","Fotografie."],"audio":"e6cfcc8ed93e"},{"a":["Wir freuen uns auf den Ausflug in die Berge."],"tokens":["Wir","freuen","uns","auf","den","Ausflug","in","die","Berge."],"audio":"fca2d72eae87"},{"a":["Ich träume davon, in einem Chor zu singen."],"tokens":["Ich","träume","davon,","in","einem","Chor","zu","singen."],"audio":"b58b594e484a"},{"a":["Hast du Lust, am Samstag mitzukommen?"],"tokens":["Hast","du","Lust,","am","Samstag","mitzukommen?"],"audio":"d5591a96f8fd"},{"a":["Woran denkst du gerade?"],"tokens":["Woran","denkst","du","gerade?"],"audio":"899dea7d136c"}]},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Ich interessiere mich sehr für die Berge.","audio":"8a9cf7ee5b9c"},{"a":"Hast du Lust, am Samstag mitzukommen?","audio":"722355d4b3c4"},{"a":"Ich freue mich schon darauf.","audio":"d1743f0dcd50"},{"a":"Vergiss nicht, etwas zu essen mitzunehmen.","audio":"107e54979106"}]}],"reading":{"title":"Mitmachen im Quartier","kind":"Zeitungsartikel","paras":[{"t":"In der Schweiz gibt es sehr viele Vereine – für Sport, Musik, Kultur, Natur und vieles mehr. Wer neu in einer Gemeinde ist, findet in einem Verein schnell Kontakt. Wir haben mit Sandra Meier gesprochen. Sie ist seit acht Jahren Präsidentin des Quartiervereins Rosenberg.","audio":"bbe82f5ab6cf"},{"t":"„Unser Verein kümmert sich um das Leben im Quartier\", erzählt sie. „Wir organisieren jedes Jahr ein Sommerfest, einen Flohmarkt und im Dezember einen kleinen Weihnachtsmarkt. Ausserdem gibt es jeden Mittwoch einen Mittagstisch für ältere Menschen.\" Alle Mitglieder arbeiten ehrenamtlich, also ohne Lohn.","audio":"fef53eb53256"},{"t":"Besonders freut sich Sandra Meier darüber, dass immer mehr Neuzuzüger mitmachen. „Letztes Jahr hat eine Familie aus Syrien am Sommerfest gekocht. Nach einer Stunde war das ganze Essen weg!\" Viele neue Mitglieder erzählen, dass sie im Verein ihre ersten Schweizer Freunde gefunden haben – und dass sie dort viel Deutsch üben konnten.","audio":"a3328d8bcd2a"},{"t":"Wer Lust hat, mitzumachen, kann einfach an einer Veranstaltung teilnehmen. Der Mitgliederbeitrag kostet 30 Franken pro Jahr, für Familien 50 Franken. Man muss aber nicht Mitglied sein, um zu helfen. „Jede Hilfe ist willkommen\", sagt Sandra Meier, „auch nur für einen Nachmittag.\"","audio":"241bfec94e6d"}],"glossary":[{"de":"die Präsidentin","en":"president, chair"},{"de":"der Flohmarkt","en":"flea market"},{"de":"der Mittagstisch","en":"shared lunch (often for seniors)"},{"de":"der Neuzuzüger (CH)","en":"newcomer to a town"},{"de":"mitmachen","en":"to join in"},{"de":"willkommen","en":"welcome"}],"questions":[{"type":"tf","q":"Sandra Meier ist seit acht Jahren Präsidentin des Vereins.","a":true,"why":""},{"type":"mc","q":"Was organisiert der Verein nicht?","options":["ein Sommerfest","einen Flohmarkt","ein Fussballturnier"],"a":2},{"type":"tf","q":"Die Mitglieder bekommen einen kleinen Lohn.","a":false,"why":"Sie arbeiten ehrenamtlich, also ohne Lohn."},{"type":"mc","q":"Worüber freut sich Sandra Meier besonders?","options":["dass immer mehr Neuzuzüger mitmachen","dass der Verein viel Geld hat","dass das Sommerfest so gross ist"],"a":0},{"type":"mc","q":"Was muss man machen, wenn man helfen möchte?","options":["Mitglied werden","fünfzig Franken bezahlen","einfach an einer Veranstaltung teilnehmen"],"a":2}]},"writing":{"task":"Sie möchten beim Quartierverein mitmachen. Schreiben Sie eine E-Mail an Frau Meier (80–100 Wörter).","points":["Stellen Sie sich vor.","Wofür interessieren Sie sich?","Wobei möchten Sie helfen?","Stellen Sie eine Frage zum nächsten Treffen."],"phrases":[{"de":"Ich habe den Artikel über … gelesen.","en":"I read the article about …"},{"de":"Ich interessiere mich für …","en":"I'm interested in …"},{"de":"Ich hätte Lust, bei … mitzuhelfen.","en":"I'd like to help with …"},{"de":"Können Sie mir sagen, wann …?","en":"Could you tell me when …?"},{"de":"Ich freue mich darauf, Sie kennenzulernen.","en":"I look forward to meeting you."}],"model":"Liebe Frau Meier\n\nIch habe im Gemeindeblatt den Artikel über den Quartierverein gelesen. Ich heisse Carla, komme aus Portugal und wohne seit einem Jahr im Rosenberg-Quartier. Ich interessiere mich sehr für Ihre Arbeit, weil ich gern neue Leute kennenlernen möchte. Am liebsten würde ich beim Sommerfest helfen – ich koche gern und könnte portugiesische Spezialitäten machen. Ausserdem hätte ich Lust, beim Mittagstisch mitzuhelfen. Können Sie mir sagen, wann das nächste Treffen stattfindet? Ich freue mich darauf, Sie kennenzulernen.\n\nHerzliche Grüsse\nCarla Ferreira","audio":"535a6c411300"},"speaking":{"task":"Sprechen Sie über Ihre Freizeit. Antworten Sie in drei bis vier Sätzen.","phrases":[{"de":"In meiner Freizeit …","en":"In my free time …","audio":null},{"de":"Ich interessiere mich für …","en":"I'm interested in …","audio":null},{"de":"Ich freue mich auf …","en":"I'm looking forward to …","audio":null},{"de":"Ich habe (keine) Lust, … zu …","en":"I (don't) feel like …","audio":null},{"de":"Ich bin Mitglied in …","en":"I'm a member of …","audio":null}],"prompts":[{"q":"Was machen Sie gern in Ihrer Freizeit?","model":"In meiner Freizeit gehe ich gern wandern, und ich singe gern. Am Wochenende treffe ich mich oft mit Freunden.","aq":"464df6622414","am":"40f2970a96fd"},{"q":"Wofür interessieren Sie sich besonders?","model":"Ich interessiere mich besonders für Musik und für die Natur. Deshalb möchte ich in einem Chor singen und öfter in den Bergen wandern.","aq":"26c518f3485a","am":"65fdcab0dda4"},{"q":"Worauf freuen Sie sich im Moment?","model":"Ich freue mich auf den Ausflug am Samstag. Wir wandern mit dem Verein auf den Säntis.","aq":"f5dd83297aac","am":"b116c375eacf"},{"q":"Sind Vereine eine gute Idee für Leute, die neu in der Schweiz sind? Warum?","model":"Ja, ich finde schon. In einem Verein lernt man schnell Leute kennen, und man kann Deutsch üben. Ausserdem lernt man viel über das Leben in der Schweiz.","aq":"69e6e94d415e","am":"232d5e4e4661"}]}},{"id":9,"title":"Abfall und Umwelt","subtitle":"Recycling nach Schweizer Regeln","level":"B1","theme":"Umwelt","focus":"Passiv (Präsens, Präteritum, mit Modalverb) und um … zu / damit","goals":[{"de":"Ich kann ein Merkblatt der Gemeinde über Abfall verstehen.","en":"I can understand a municipal leaflet about waste."},{"de":"Ich kann erklären, wie etwas gemacht wird (Passiv).","en":"I can explain how something is done (passive)."},{"de":"Ich kann sagen, warum man etwas macht (um … zu, damit).","en":"I can say why something is done."}],"vocab":[{"id":"9-0","de":"der Abfall","forms":"Abfälle","en":"waste, rubbish","ex":"Wohin kommt dieser Abfall?","exEn":"Where does this rubbish go?","aw":"d25745d82544","ae":"9a8bccfce9ca"},{"id":"9-1","de":"der Gebührensack","forms":"-säcke","en":"official fee-paid rubbish bag (CH)","ex":"Ohne Gebührensack wird der Abfall nicht mitgenommen.","exEn":"Without an official bag the rubbish isn't collected.","aw":"58e68ffc7997","ae":"1f6d100f6ebf"},{"id":"9-2","de":"trennen","forms":"hat getrennt","en":"to separate, sort","ex":"In der Schweiz trennt man den Abfall sehr genau.","exEn":"In Switzerland people sort their waste very carefully.","aw":"be229a78c4f5","ae":"804cb2d1d4a3"},{"id":"9-3","de":"entsorgen","forms":"hat entsorgt","en":"to dispose of","ex":"Wo kann ich alte Möbel entsorgen?","exEn":"Where can I dispose of old furniture?","aw":"7eab783482ef","ae":"e56b9a34e133"},{"id":"9-4","de":"das Altpapier","forms":"–","en":"waste paper","ex":"Das Altpapier wird einmal im Monat gesammelt.","exEn":"Waste paper is collected once a month.","aw":"6fa825704c00","ae":"c5b98b421219"},{"id":"9-5","de":"der Karton","forms":"-s","en":"cardboard","ex":"Karton und Papier kommen nicht ins gleiche Bündel.","exEn":"Cardboard and paper don't go in the same bundle.","aw":"cdc680862ac1","ae":"845f5a4345a8"},{"id":"9-6","de":"bündeln","forms":"hat gebündelt","en":"to bundle, tie up","ex":"Das Papier muss mit einer Schnur gebündelt werden.","exEn":"The paper has to be tied up with string.","aw":"fd7382ab268f","ae":"856a265ca1da"},{"id":"9-7","de":"die Sammelstelle","forms":"-n","en":"collection point","ex":"Glas bringe ich zur Sammelstelle beim Schulhaus.","exEn":"I take glass to the collection point by the school.","aw":"67d40e6afe3a","ae":"223fdbc367a5"},{"id":"9-8","de":"die PET-Flasche","forms":"-n","en":"plastic (PET) bottle","ex":"PET-Flaschen gibt man im Supermarkt zurück.","exEn":"You return PET bottles at the supermarket.","aw":"79eef320dcb9","ae":"d67b5bc41a93"},{"id":"9-9","de":"das Grüngut","forms":"–","en":"green waste (CH)","ex":"Das Grüngut wird im Sommer jede Woche abgeholt.","exEn":"Green waste is collected every week in summer.","aw":"5124b0fa7170","ae":"fe6b049ce259"},{"id":"9-10","de":"die Batterie","forms":"-n","en":"battery","ex":"Alte Batterien darf man nicht in den Abfall werfen.","exEn":"You mustn't throw old batteries in the rubbish.","aw":"a7a89038a75f","ae":"8d5b701aed17"},{"id":"9-11","de":"abholen","forms":"hat abgeholt","en":"to collect, pick up","ex":"Der Abfall wird am Dienstag abgeholt.","exEn":"The rubbish is collected on Tuesday.","aw":"2a1e2938efef","ae":"877e8be31b9d"},{"id":"9-12","de":"bereitstellen","forms":"hat bereitgestellt","en":"to put out (ready)","ex":"Stellen Sie die Säcke erst am Morgen bereit.","exEn":"Only put the bags out in the morning.","aw":"fdcc247233cd","ae":"b52792d0476e"},{"id":"9-13","de":"die Busse","forms":"-n","en":"fine (CH)","ex":"Er musste eine Busse von hundert Franken bezahlen.","exEn":"He had to pay a fine of a hundred francs.","aw":"655e2c6a862e","ae":"0fd041972b83"},{"id":"9-14","de":"die Umwelt","forms":"–","en":"environment","ex":"Recycling ist gut für die Umwelt.","exEn":"Recycling is good for the environment.","aw":"fa059f8dfe84","ae":"86e4dfa94b74"},{"id":"9-15","de":"schützen","forms":"hat geschützt","en":"to protect","ex":"Wir wollen die Natur schützen.","exEn":"We want to protect nature.","aw":"6e03f1bf2ce5","ae":"74c7e7d6cbbf"},{"id":"9-16","de":"der Abfallkalender","forms":"-","en":"waste collection calendar","ex":"Im Abfallkalender stehen alle Termine.","exEn":"All the dates are in the waste calendar.","aw":"b33c87933a6e","ae":"d23ff6eadd5a"},{"id":"9-17","de":"recyceln","forms":"hat recycelt","en":"to recycle","ex":"Aus alten Flaschen werden neue Flaschen recycelt.","exEn":"Old bottles are recycled into new ones.","aw":"4cfd98ee0210","ae":"89caf604db70"},{"id":"9-18","de":"wegwerfen","forms":"hat weggeworfen","en":"to throw away","ex":"Wirf das nicht weg, das kann man noch reparieren!","exEn":"Don't throw that away, it can still be repaired!","aw":"dce933c72304","ae":"510c56885ab8"},{"id":"9-19","de":"verboten","forms":"–","en":"forbidden, prohibited","ex":"Abfall im Wald zu entsorgen ist verboten.","exEn":"Dumping rubbish in the forest is prohibited.","aw":"29cae5fb9137","ae":"1595b26624f7"}],"swiss":[{"ch":"der Kehricht","std":"der Restmüll","en":"household rubbish"},{"ch":"der Gebührensack","std":"–","en":"official paid rubbish bag; ordinary bags are not collected"},{"ch":"die Busse","std":"das Bussgeld","en":"fine"},{"ch":"der Werkhof","std":"der Bauhof","en":"municipal depot, often with a recycling point"},{"ch":"das Schulhaus","std":"das Schulgebäude","en":"school building"}],"dialogue":{"title":"Der Sack wurde nicht abgeholt","intro":"Carla trifft ihre Nachbarin Frau Rossi im Treppenhaus. Frau Rossi hat ein Problem bemerkt.","speakers":{"F":"Carla","W":"Frau Rossi"},"lines":[{"s":"W","de":"Hallo Frau Ferreira! Haben Sie kurz Zeit? Ich möchte Ihnen etwas zeigen.","en":"Hello Ms Ferreira! Do you have a moment? I'd like to show you something.","audio":"116dd9403c55"},{"s":"F","de":"Hallo Frau Rossi. Ja, natürlich. Was ist los?","en":"Hello Ms Rossi. Yes, of course. What's up?","audio":"f9c9e79b6772"},{"s":"W","de":"Gestern stand ein Abfallsack vor dem Haus, der nicht abgeholt wurde. Ich glaube, er gehört Ihnen.","en":"Yesterday there was a rubbish bag in front of the building that wasn't collected. I think it's yours.","audio":"b62646c02d39"},{"s":"F","de":"Oh nein! Warum wurde er denn nicht abgeholt?","en":"Oh no! Why wasn't it collected?","audio":"bc97cefa8a3f"},{"s":"W","de":"Weil es kein offizieller Gebührensack war. Hier werden nur die offiziellen Säcke mitgenommen. Die kann man im Supermarkt kaufen.","en":"Because it wasn't an official fee bag. Only official bags are taken here. You can buy them at the supermarket.","audio":"2a74c88760d0"},{"s":"F","de":"Das wusste ich nicht! In Portugal wird der Abfall einfach in grosse Container geworfen.","en":"I didn't know that! In Portugal rubbish is simply thrown into big containers.","audio":"a394e8330516"},{"s":"W","de":"Hier ist es ein bisschen komplizierter. Aber keine Sorge, ich erkläre es Ihnen. Altpapier und Karton werden separat gesammelt, einmal im Monat.","en":"Here it's a bit more complicated. But don't worry, I'll explain it to you. Waste paper and cardboard are collected separately, once a month.","audio":"4bee8cf3feea"},{"s":"F","de":"Und wie wird das Papier bereitgestellt?","en":"And how is the paper put out?","audio":"2390da541e0e"},{"s":"W","de":"Es wird gebündelt, also mit einer Schnur zusammengebunden, und am Morgen an die Strasse gestellt. Die Daten stehen im Abfallkalender.","en":"It's bundled, so tied together with string, and put out on the street in the morning. The dates are in the waste calendar.","audio":"1171c68b132e"},{"s":"F","de":"Und was mache ich mit Glasflaschen?","en":"And what do I do with glass bottles?","audio":"4f57fc54b771"},{"s":"W","de":"Glas bringt man zur Sammelstelle beim Schulhaus. Aber bitte nicht am Sonntag oder am Abend, damit die Nachbarn nicht gestört werden.","en":"You take glass to the collection point by the school. But please not on Sundays or in the evening, so that the neighbours aren't disturbed.","audio":"fc9f8180c8c4"},{"s":"F","de":"Und PET-Flaschen?","en":"And PET bottles?","audio":"647e2f0e547d"},{"s":"W","de":"Die können Sie im Supermarkt zurückgeben. Dort werden auch alte Batterien angenommen.","en":"You can return those at the supermarket. Old batteries are accepted there too.","audio":"b6cf261aafc1"},{"s":"F","de":"Warum ist das alles so genau geregelt?","en":"Why is all this so precisely regulated?","audio":"97a0f0c99006"},{"s":"W","de":"Um Rohstoffe zu sparen und die Umwelt zu schützen. Und die Gebührensäcke sind teuer, damit die Leute weniger Abfall produzieren.","en":"To save raw materials and protect the environment. And the fee bags are expensive so that people produce less rubbish.","audio":"bc569050ee22"},{"s":"F","de":"Das macht Sinn. Bekommt man eigentlich eine Busse, wenn man es falsch macht?","en":"That makes sense. Do you actually get a fine if you do it wrong?","audio":"5cdd95dbaa4e"},{"s":"W","de":"Das kann passieren. Aber beim ersten Mal wird man meistens nur informiert.","en":"That can happen. But the first time you're usually just informed.","audio":"17589a3a44e5"},{"s":"F","de":"Vielen Dank, Frau Rossi! Ich kaufe heute noch Gebührensäcke.","en":"Thank you so much, Ms Rossi! I'll buy fee bags today.","audio":"2f91edd4558e"},{"s":"W","de":"Gern geschehen. Den Abfallkalender lege ich Ihnen in den Briefkasten.","en":"You're welcome. I'll put the waste calendar in your letterbox.","audio":"1c86fe113880"}],"questions":[{"type":"tf","q":"Carlas Abfallsack wurde nicht abgeholt.","a":true,"why":""},{"type":"mc","q":"Warum wurde der Sack nicht abgeholt?","options":["Er war zu schwer.","Es war kein offizieller Gebührensack.","Er stand am falschen Tag vor dem Haus."],"a":1},{"type":"mc","q":"Wie wird das Altpapier bereitgestellt?","options":["in einem Gebührensack","gebündelt an der Strasse","in einem Container im Keller"],"a":1},{"type":"tf","q":"Glas darf man am Sonntag zur Sammelstelle bringen.","a":false,"why":"Nicht am Sonntag und nicht am Abend."},{"type":"mc","q":"Warum sind die Gebührensäcke teuer?","options":["damit die Leute weniger Abfall produzieren","damit die Gemeinde mehr Geld hat","um die Säcke zu recyceln"],"a":0}]},"grammar":{"title":"Das Passiv und um … zu / damit","summary":"Im Passiv ist die Handlung wichtig, nicht die Person.","sections":[{"h":"Aktiv oder Passiv?","text":"**Aktiv:** Wer macht etwas? *Die Müllabfuhr holt den Abfall ab.*\n**Passiv:** Was passiert? *Der Abfall ==wird== ==abgeholt==.* – Wer es macht, ist nicht wichtig oder nicht bekannt. (Wenn nötig: **von** + Dativ: *von der Müllabfuhr*.)"},{"h":"Passiv Präsens – werden + Partizip II","table":[["Person","werden","Beispiel"],["ich","werde","Ich werde informiert."],["du","wirst","Du wirst abgeholt."],["er/sie/es","wird","Der Abfall wird abgeholt."],["wir","werden","Wir werden eingeladen."],["ihr","werdet","Ihr werdet gefragt."],["sie/Sie","werden","Die Flaschen werden recycelt."]],"examples":[{"de":"Papier und Karton ==werden== separat ==gesammelt==.","en":"Paper and cardboard are collected separately.","audio":"0cf1eda61ce7"},{"de":"Hier ==wird== viel ==recycelt==.","en":"A lot is recycled here.","audio":"e4dcfe1dc4f7"}]},{"h":"Passiv Präteritum – wurde + Partizip II","text":"Für die Vergangenheit benutzt man im Passiv meistens das **Präteritum**: *ich wurde, du wurdest, er/sie/es wurde, wir wurden, ihr wurdet, sie wurden.*","examples":[{"de":"Der Sack ==wurde== nicht ==abgeholt==.","en":"The bag wasn't collected.","audio":"526c92457a8b"},{"de":"Die Sammelstelle ==wurde== letztes Jahr ==gebaut==.","en":"The collection point was built last year.","audio":"4be690822640"}]},{"h":"Passiv mit Modalverb","text":"Modalverb (Position 2) … **Partizip II + werden** (am Ende).","examples":[{"de":"Das Papier ==muss== ==gebündelt werden==.","en":"The paper has to be bundled.","audio":"36661d04b4f8"},{"de":"Batterien ==dürfen== nicht in den Abfall ==geworfen werden==.","en":"Batteries must not be thrown in the rubbish.","audio":"e52e6336d116"}]},{"h":"Ziel und Zweck – um … zu oder damit?","text":"**um … zu + Infinitiv:** nur wenn das Subjekt in beiden Teilen **gleich** ist.\n**damit + Nebensatz:** immer möglich, und **nötig**, wenn die Subjekte **verschieden** sind.","examples":[{"de":"Ich trenne den Abfall, ==um== die Umwelt ==zu schützen==. (ich … ich)","en":"I sort my waste to protect the environment.","audio":"d9e030536004"},{"de":"Die Säcke sind teuer, ==damit== die Leute weniger Abfall ==produzieren==. (die Säcke … die Leute)","en":"The bags are expensive so that people produce less rubbish.","audio":"e1d992db3b39"}]}],"tip":"„werden\" hat drei Aufgaben: Vollverb (Es wird kalt.), Futur (Ich werde morgen kommen.) und Passiv (Der Abfall wird abgeholt.). Beim Passiv steht immer ein Partizip II am Ende."},"exercises":[{"type":"choice","title":"Welche Form von werden?","items":[{"q":"Der Abfall ___ jeden Dienstag abgeholt.","options":["wird","werden","wirst"],"a":0,"full":"Der Abfall wird jeden Dienstag abgeholt.","audio":"1d3df9a9cbbf"},{"q":"Die Flaschen ___ im Supermarkt zurückgegeben.","options":["werden","wird","werdet"],"a":0,"full":"Die Flaschen werden im Supermarkt zurückgegeben.","audio":"b93e6ff14bf2"},{"q":"Gestern ___ mein Velo gestohlen.","options":["wurde","wird","werden"],"a":0,"full":"Gestern wurde mein Velo gestohlen.","audio":"8767a8be328b"},{"q":"Das Papier muss gebündelt ___.","options":["werden","wird","worden"],"a":0,"full":"Das Papier muss gebündelt werden.","audio":"36661d04b4f8"},{"q":"In der Schweiz ___ sehr viel recycelt.","options":["wird","werden","ist"],"a":0,"full":"In der Schweiz wird sehr viel recycelt.","audio":"fbb772a4d4c5"},{"q":"Letztes Jahr ___ zwei neue Sammelstellen gebaut.","options":["wurden","wurde","werden"],"a":0,"full":"Letztes Jahr wurden zwei neue Sammelstellen gebaut.","audio":"e62a4609ed64"},{"q":"Batterien dürfen nicht in den Abfall geworfen ___.","options":["werden","wird","worden"],"a":0,"full":"Batterien dürfen nicht in den Abfall geworfen werden.","audio":"e52e6336d116"},{"q":"Wann ___ das Altpapier abgeholt?","options":["wird","werden","wirst"],"a":0,"full":"Wann wird das Altpapier abgeholt?","audio":"7d6391cb9663"}]},{"type":"gap","title":"Ergänzen Sie das Partizip II","items":[{"q":"Der Abfall wird jeden Dienstag ___. (abholen)","a":["abgeholt"],"full":"Der Abfall wird jeden Dienstag abgeholt.","audio":"1d3df9a9cbbf"},{"q":"Glas wird nach Farben ___. (trennen)","a":["getrennt"],"full":"Glas wird nach Farben getrennt.","audio":"8d6e3c414e53"},{"q":"Die Säcke werden im Supermarkt ___. (verkaufen)","a":["verkauft"],"full":"Die Säcke werden im Supermarkt verkauft.","audio":"cb2ecaca556b"},{"q":"Das Altpapier muss ___ werden. (bündeln)","a":["gebündelt"],"full":"Das Altpapier muss gebündelt werden.","audio":"059240b4b4ec"},{"q":"PET-Flaschen werden zu neuen Flaschen ___. (recyceln)","a":["recycelt"],"full":"PET-Flaschen werden zu neuen Flaschen recycelt.","audio":"6fa752e96ea9"},{"q":"Hier darf kein Abfall ___ werden. (wegwerfen)","a":["weggeworfen"],"full":"Hier darf kein Abfall weggeworfen werden.","audio":"977f216e1cf1"}]},{"type":"choice","title":"um … zu oder damit?","items":[{"q":"Ich trenne den Abfall, ___ die Umwelt zu schützen.","options":["um","damit"],"a":0,"full":"Ich trenne den Abfall, um die Umwelt zu schützen.","audio":"d9e030536004"},{"q":"Wir kaufen Gebührensäcke, ___ der Abfall abgeholt wird.","options":["damit","um"],"a":0,"full":"Wir kaufen Gebührensäcke, damit der Abfall abgeholt wird.","audio":"ea487fb8a2cc"},{"q":"Frau Rossi erklärt alles, ___ Carla keine Busse bekommt.","options":["damit","um"],"a":0,"full":"Frau Rossi erklärt alles, damit Carla keine Busse bekommt.","audio":"d81ca66544b9"},{"q":"Ich gehe in den Supermarkt, ___ die PET-Flaschen zurückzugeben.","options":["um","damit"],"a":0,"full":"Ich gehe in den Supermarkt, um die PET-Flaschen zurückzugeben.","audio":"c64f9c207f67"},{"q":"Die Säcke sind teuer, ___ die Leute weniger Abfall produzieren.","options":["damit","um"],"a":0,"full":"Die Säcke sind teuer, damit die Leute weniger Abfall produzieren.","audio":"e1d992db3b39"},{"q":"Er steht früh auf, ___ das Altpapier an die Strasse zu stellen.","options":["um","damit"],"a":0,"full":"Er steht früh auf, um das Altpapier an die Strasse zu stellen.","audio":"c831027ab797"}]},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Der Abfall wird jeden Dienstag abgeholt.","Jeden Dienstag wird der Abfall abgeholt."],"tokens":["Der","Abfall","wird","jeden","Dienstag","abgeholt."],"audio":"1d3df9a9cbbf"},{"a":["Das Altpapier muss gebündelt werden."],"tokens":["Das","Altpapier","muss","gebündelt","werden."],"audio":"059240b4b4ec"},{"a":["Mein Sack wurde gestern nicht abgeholt.","Gestern wurde mein Sack nicht abgeholt."],"tokens":["Mein","Sack","wurde","gestern","nicht","abgeholt."],"audio":"024eaa4bcc1e"},{"a":["Ich trenne den Abfall, um die Umwelt zu schützen."],"tokens":["Ich","trenne","den","Abfall,","um","die","Umwelt","zu","schützen."],"audio":"d9e030536004"},{"a":["Sie bringt das Glas zur Sammelstelle, damit es recycelt wird."],"tokens":["Sie","bringt","das","Glas","zur","Sammelstelle,","damit","es","recycelt","wird."],"audio":"8ef77e278a6e"}]},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Der Abfall wird am Dienstag abgeholt.","audio":"48996b4b169b"},{"a":"Das Altpapier muss gebündelt werden.","audio":"0d74a49e0f48"},{"a":"Warum wurde mein Sack nicht abgeholt?","audio":"7602e2066b18"},{"a":"Wir trennen den Abfall, um die Umwelt zu schützen.","audio":"5cdff0dbdac8"}]}],"reading":{"title":"Abfall richtig entsorgen – Merkblatt für Neuzuzüger","kind":"Merkblatt","paras":[{"t":"**Kehricht:** Der normale Abfall wird jeden Dienstag abgeholt. Es werden nur offizielle Gebührensäcke mitgenommen. Die Säcke können in allen Supermärkten der Gemeinde gekauft werden. Bitte stellen Sie die Säcke erst am Dienstagmorgen vor 7 Uhr an die Strasse, damit sie nicht von Tieren geöffnet werden.","audio":"399e504830b1"},{"t":"**Altpapier und Karton:** Papier und Karton werden jeden ersten Mittwoch im Monat gesammelt. Sie müssen gebündelt werden – Papier in Taschen oder Schachteln wird nicht mitgenommen.","audio":"c750b0aa718f"},{"t":"**Glas und Metall:** Diese Materialien werden an der Sammelstelle beim Werkhof angenommen. Glas wird dort nach Farben getrennt: weiss, braun und grün. Einwurfzeiten: Montag bis Samstag, 8 bis 19 Uhr.","audio":"b7d7cae34bdf"},{"t":"**PET und Batterien:** PET-Flaschen und Batterien können in allen Verkaufsstellen zurückgegeben werden.","audio":"996fc979c276"},{"t":"**Grüngut:** Garten- und Küchenabfälle werden in der grünen Tonne gesammelt. Die Tonne wird im Sommer jede Woche und im Winter alle zwei Wochen geleert.","audio":"32549485de5b"},{"t":"**Wichtig:** Wer Abfall illegal entsorgt, zum Beispiel im Wald oder in fremden Containern, muss mit einer Busse rechnen. Bei Fragen hilft Ihnen die Gemeindeverwaltung gern weiter.","audio":"c3dd730e06b2"}],"glossary":[{"de":"der Kehricht (CH)","en":"household rubbish"},{"de":"die Schachtel","en":"box"},{"de":"der Werkhof (CH)","en":"municipal depot"},{"de":"die Einwurfzeiten","en":"times when you may drop items in"},{"de":"die Verkaufsstelle","en":"shop, point of sale"},{"de":"leeren","en":"to empty"}],"questions":[{"type":"tf","q":"Der normale Abfall wird jeden Dienstag abgeholt.","a":true,"why":""},{"type":"mc","q":"Wann soll man die Gebührensäcke an die Strasse stellen?","options":["am Montagabend","am Dienstagmorgen vor 7 Uhr","am Dienstagmittag"],"a":1},{"type":"tf","q":"Altpapier in einer Tasche wird auch mitgenommen.","a":false,"why":"Es muss gebündelt werden."},{"type":"mc","q":"Wo kann man Batterien zurückgeben?","options":["nur beim Werkhof","in allen Verkaufsstellen","in der grünen Tonne"],"a":1},{"type":"mc","q":"Was passiert, wenn man Abfall im Wald entsorgt?","options":["Man muss mit einer Busse rechnen.","Nichts.","Der Abfall wird gratis abgeholt."],"a":0}]},"writing":{"task":"Ein Freund zieht bald in die Schweiz. Er fragt Sie, wie das mit dem Abfall funktioniert. Schreiben Sie ihm eine E-Mail (80–100 Wörter).","points":["Was ist anders als in Ihrem Heimatland?","Wie wird der Abfall getrennt? (Passiv)","Geben Sie einen Tipp.","Was denken Sie über die Regeln?"],"phrases":[{"de":"Das ist ganz anders als in …","en":"That's quite different from …"},{"de":"Der Abfall wird …","en":"The rubbish is …"},{"de":"Mein Tipp – …","en":"My tip – …"},{"de":"Ich finde die Regeln gut / streng, weil …","en":"I think the rules are good / strict because …"}],"model":"Hallo Pedro\n\nDu hast mich gefragt, wie das mit dem Abfall in der Schweiz funktioniert. Das ist ganz anders als in Portugal! Der normale Abfall wird nur in offiziellen Gebührensäcken mitgenommen – die kannst du im Supermarkt kaufen. Papier und Karton werden separat gesammelt und müssen gebündelt werden. Glas bringst du zur Sammelstelle, und PET-Flaschen gibst du im Supermarkt zurück. Mein Tipp: Hol dir sofort den Abfallkalender, damit du keine Busse bekommst! Am Anfang ist es kompliziert, aber ich finde die Regeln gut, weil so viel recycelt wird.\n\nBis bald!\nCarla","audio":"27b62db24d0e"},"speaking":{"task":"Vergleichen Sie und sagen Sie Ihre Meinung. Antworten Sie in drei bis vier Sätzen.","phrases":[{"de":"Bei uns wird …","en":"In my country … is …","audio":null},{"de":"Im Vergleich zu …","en":"Compared with …","audio":null},{"de":"Ich finde es gut / nicht so gut, dass …","en":"I think it's good / not so good that …","audio":null},{"de":"Meiner Meinung nach …","en":"In my opinion …","audio":null},{"de":"um … zu / damit …","en":"in order to / so that …","audio":null}],"prompts":[{"q":"Wie wird der Abfall in Ihrem Heimatland entsorgt?","model":"In Portugal wird der Abfall meistens in grosse Container auf der Strasse geworfen. Glas und Papier werden auch getrennt, aber nicht so genau wie hier.","aq":"d91e89ec2496","am":"02cef98cd31d"},{"q":"Was finden Sie an den Schweizer Regeln gut, und was ist schwierig?","model":"Ich finde gut, dass so viel recycelt wird. Schwierig ist, dass man so viele Regeln und Termine kennen muss.","aq":"e74609755337","am":"aaac9e27e984"},{"q":"Was machen Sie persönlich, um die Umwelt zu schützen?","model":"Ich fahre mit dem Velo oder mit dem Zug, und ich trenne meinen Abfall. Ausserdem versuche ich, möglichst wenig Plastik zu kaufen.","aq":"6146378c20c1","am":"ab9f716e142c"},{"q":"Sind Gebührensäcke Ihrer Meinung nach eine gute Idee?","model":"Ja, ich finde sie gut, weil die Leute dann weniger Abfall produzieren. Aber für Familien mit wenig Geld sind sie vielleicht zu teuer.","aq":"81f4a4766061","am":"4d2f75a235a0"}]}},{"id":10,"title":"Ein Unfall mit dem Velo","subtitle":"Erzählen, was passiert ist, und einen Unfall melden","level":"B1","theme":"Notfall und Versicherung","focus":"Präteritum, Plusquamperfekt und temporale Nebensätze (als, wenn, bevor, nachdem, während)","goals":[{"de":"Ich kann einen Unfall telefonisch melden und Fragen dazu beantworten.","en":"I can report an accident by phone and answer questions about it."},{"de":"Ich kann einen kurzen schriftlichen Bericht über ein Ereignis verstehen und schreiben.","en":"I can understand and write a short written report about an event."},{"de":"Ich kann Ereignisse zeitlich ordnen (als, bevor, nachdem, während).","en":"I can put events in time order."}],"vocab":[{"id":"10-0","de":"der Unfall","forms":"Unfälle","en":"accident","ex":"Wann ist der Unfall passiert?","exEn":"When did the accident happen?","aw":"802447c9914e","ae":"ca72e940f08d"},{"id":"10-1","de":"passieren","forms":"ist passiert","en":"to happen","ex":"Zum Glück ist nichts Schlimmes passiert.","exEn":"Luckily nothing serious happened.","aw":"088d8a93de88","ae":"82ab1306c9a9"},{"id":"10-2","de":"stürzen","forms":"ist gestürzt","en":"to fall (over)","ex":"Sie ist mit dem Velo gestürzt.","exEn":"She fell off her bike.","aw":"bd7bc3e67525","ae":"fbc7cacd8cc2"},{"id":"10-3","de":"sich verletzen","forms":"hat sich verletzt","en":"to injure yourself","ex":"Hast du dich verletzt?","exEn":"Did you hurt yourself?","aw":"e3c92f6be2c1","ae":"7942128d2727"},{"id":"10-4","de":"die Verletzung","forms":"-en","en":"injury","ex":"Die Verletzung ist nicht gefährlich.","exEn":"The injury isn't dangerous.","aw":"d1276e6b82d1","ae":"7e4fee5168ed"},{"id":"10-5","de":"bremsen","forms":"hat gebremst","en":"to brake","ex":"Ich habe zu spät gebremst.","exEn":"I braked too late.","aw":"1017b68e1644","ae":"9a6264f77ef3"},{"id":"10-6","de":"ausweichen","forms":"ist ausgewichen","en":"to swerve, get out of the way","ex":"Er ist dem Auto im letzten Moment ausgewichen.","exEn":"He swerved around the car at the last moment.","aw":"140319501dfb","ae":"199346db83f8"},{"id":"10-7","de":"der Zeuge","forms":"-n","en":"witness","ex":"Gab es Zeugen?","exEn":"Were there any witnesses?","aw":"04fb55c0e9ef","ae":"ebe0ae8f89e0"},{"id":"10-8","de":"die Versicherung","forms":"-en","en":"insurance","ex":"Die Versicherung übernimmt die Kosten.","exEn":"The insurance covers the costs.","aw":"fb5f9f42f0d3","ae":"e32886d5a317"},{"id":"10-9","de":"der Schaden","forms":"Schäden","en":"damage","ex":"Am Auto gibt es keinen grossen Schaden.","exEn":"There's no major damage to the car.","aw":"45f89a06748a","ae":"f5be18ec39eb"},{"id":"10-10","de":"melden","forms":"hat gemeldet","en":"to report","ex":"Sie müssen den Unfall innerhalb von drei Tagen melden.","exEn":"You have to report the accident within three days.","aw":"944374aa6e3f","ae":"913db6295c4d"},{"id":"10-11","de":"die Unfallmeldung","forms":"-en","en":"accident report form","ex":"Füllen Sie bitte die Unfallmeldung aus.","exEn":"Please fill in the accident report.","aw":"1303a200cd2d","ae":"14cc142070ef"},{"id":"10-12","de":"die Ambulanz","forms":"-en","en":"ambulance (CH)","ex":"Die Ambulanz war nach zehn Minuten da.","exEn":"The ambulance was there after ten minutes.","aw":"0db1f053ee09","ae":"0bd479d3bdec"},{"id":"10-13","de":"die Behandlung","forms":"-en","en":"(medical) treatment","ex":"Die Behandlung dauert ungefähr sechs Wochen.","exEn":"The treatment takes about six weeks.","aw":"f1f05afa134a","ae":"ca61643f556a"},{"id":"10-14","de":"gebrochen","forms":"–","en":"broken (bone)","ex":"Der Arm ist zum Glück nicht gebrochen.","exEn":"Luckily the arm isn't broken.","aw":"fb094926fbbe","ae":"b4e1c48ef2b4"},{"id":"10-15","de":"das Handgelenk","forms":"-e","en":"wrist","ex":"Mein Handgelenk tut sehr weh.","exEn":"My wrist hurts a lot.","aw":"211295cd2f95","ae":"a240612be9e7"},{"id":"10-16","de":"die Kreuzung","forms":"-en","en":"crossroads, junction","ex":"An dieser Kreuzung passieren oft Unfälle.","exEn":"Accidents often happen at this junction.","aw":"eec2ee13ef42","ae":"0531766316e2"},{"id":"10-17","de":"der Fussgängerstreifen","forms":"-","en":"zebra crossing (CH)","ex":"Bitte über den Fussgängerstreifen gehen!","exEn":"Please use the zebra crossing!","aw":"166d00f776c2","ae":"875e93176eaf"},{"id":"10-18","de":"der Velohelm","forms":"-e","en":"bike helmet (CH)","ex":"Ohne Velohelm fahre ich nie.","exEn":"I never ride without a helmet.","aw":"778a2784c56e","ae":"074f525ec052"},{"id":"10-19","de":"vorsichtig","forms":"–","en":"careful","ex":"Fahr bitte vorsichtig, die Strasse ist nass!","exEn":"Please ride carefully, the road is wet!","aw":"5a9a8b8b0b6f","ae":"22acfaa661d3"}],"swiss":[{"ch":"die Ambulanz","std":"der Rettungswagen","en":"ambulance"},{"ch":"der Fussgängerstreifen","std":"der Zebrastreifen","en":"zebra crossing"},{"ch":"der Velostreifen","std":"der Radweg","en":"cycle lane"},{"ch":"die Unfallversicherung","std":"–","en":"if you work at least 8 hours a week, your employer's insurance also covers accidents in your free time"}],"dialogue":{"title":"Einen Unfall melden","intro":"Carla hatte einen Unfall mit dem Velo. Sie ruft die Unfallversicherung ihres Arbeitgebers an.","speakers":{"F":"Carla","M":"Herr Huber"},"lines":[{"s":"M","de":"Unfallabteilung, Huber, guten Tag. Wie kann ich Ihnen helfen?","en":"Accident department, Huber speaking, hello. How can I help you?","audio":"5776526dd9ca"},{"s":"F","de":"Guten Tag, hier ist Carla Ferreira. Ich möchte einen Unfall melden. Mein Arbeitgeber hat gesagt, dass ich Sie anrufen soll.","en":"Hello, this is Carla Ferreira. I'd like to report an accident. My employer told me to call you.","audio":"a8631f9f778b"},{"s":"M","de":"Das tut mir leid. Wann ist der Unfall passiert?","en":"I'm sorry to hear that. When did the accident happen?","audio":"a9d87b6f5799"},{"s":"F","de":"Letzten Donnerstag, am Abend. Ich war mit dem Velo auf dem Heimweg von der Arbeit.","en":"Last Thursday, in the evening. I was cycling home from work.","audio":"03267c887c79"},{"s":"M","de":"Können Sie mir erzählen, was genau passiert ist?","en":"Can you tell me what exactly happened?","audio":"19acc9308788"},{"s":"F","de":"Ja. Als ich zu einer Kreuzung gekommen bin, ist plötzlich ein Lieferwagen aus einer Einfahrt gefahren. Ich habe sofort gebremst, aber die Strasse war nass, weil es vorher stark geregnet hatte.","en":"Yes. When I got to a junction, a van suddenly pulled out of a driveway. I braked immediately, but the road was wet because it had rained heavily before.","audio":"25f51a7fec29"},{"s":"M","de":"Und dann?","en":"And then?","audio":"a85e1fdd406a"},{"s":"F","de":"Ich wollte ausweichen, und dabei bin ich gestürzt. Ich bin auf die rechte Hand gefallen.","en":"I tried to swerve, and I fell. I landed on my right hand.","audio":"1fe558f96086"},{"s":"M","de":"Haben Sie sich schwer verletzt?","en":"Were you badly hurt?","audio":"8f5c7d06e48c"},{"s":"F","de":"Das Handgelenk ist gebrochen. Nachdem mich die Ambulanz ins Spital gebracht hatte, wurde es geröntgt und eingegipst. Jetzt habe ich sechs Wochen einen Gips.","en":"My wrist is broken. After the ambulance had taken me to hospital, it was X-rayed and put in a cast. Now I have a cast for six weeks.","audio":"a7b86ecd584c"},{"s":"M","de":"Das klingt schmerzhaft. Haben Sie einen Velohelm getragen?","en":"That sounds painful. Were you wearing a bike helmet?","audio":"7a55e49eae15"},{"s":"F","de":"Ja, zum Glück. Der Helm ist kaputt, aber mein Kopf nicht!","en":"Yes, luckily. The helmet is broken, but my head isn't!","audio":"eda33910db2a"},{"s":"M","de":"Sehr gut. Gab es Zeugen?","en":"Very good. Were there any witnesses?","audio":"0c47f144717c"},{"s":"F","de":"Ja, eine Frau hat alles gesehen, während sie am Fussgängerstreifen gewartet hat. Sie hat mir ihre Telefonnummer gegeben.","en":"Yes, a woman saw everything while she was waiting at the zebra crossing. She gave me her phone number.","audio":"8e41f3bf3390"},{"s":"M","de":"Perfekt. Und hat der Fahrer angehalten?","en":"Perfect. And did the driver stop?","audio":"e23b4179e610"},{"s":"F","de":"Ja, er ist sofort ausgestiegen und hat mir geholfen. Bevor die Ambulanz kam, hat er auch die Polizei angerufen.","en":"Yes, he got out straight away and helped me. Before the ambulance came, he also called the police.","audio":"faa9a6fc8fb7"},{"s":"M","de":"Gut. Bitte füllen Sie die Unfallmeldung online aus und schicken Sie uns den Arztbericht. Die Kosten für die Behandlung übernehmen wir.","en":"Good. Please fill in the accident report online and send us the medical report. We'll cover the treatment costs.","audio":"cc55c0ea5828"},{"s":"F","de":"Und was ist mit meinem Velo? Es hat einen grossen Schaden.","en":"And what about my bike? It's badly damaged.","audio":"37fba6240c90"},{"s":"M","de":"Das müssen Sie mit der Versicherung des Fahrers klären. Für Sachschäden sind wir leider nicht zuständig.","en":"You'll need to sort that out with the driver's insurance. Unfortunately we're not responsible for property damage.","audio":"5f5b2509ec4d"},{"s":"F","de":"Verstehe. Vielen Dank für Ihre Hilfe.","en":"I understand. Thank you for your help.","audio":"265eff93df66"},{"s":"M","de":"Gern geschehen. Ich wünsche Ihnen gute Besserung!","en":"You're welcome. I wish you a speedy recovery!","audio":"d30f42674311"}],"questions":[{"type":"tf","q":"Der Unfall ist am Morgen passiert.","a":false,"why":"Er ist am Abend auf dem Heimweg passiert."},{"type":"mc","q":"Warum ist Carla gestürzt?","options":["Sie ist zu schnell gefahren.","Sie wollte einem Lieferwagen ausweichen.","Sie hat den Velohelm vergessen."],"a":1},{"type":"mc","q":"Was hat sich Carla verletzt?","options":["den Kopf","das Knie","das Handgelenk"],"a":2},{"type":"tf","q":"Eine Zeugin hat den Unfall gesehen.","a":true,"why":""},{"type":"mc","q":"Wer bezahlt den Schaden am Velo?","options":["die Unfallversicherung von Carla","Das muss Carla mit der Versicherung des Fahrers klären.","die Polizei"],"a":1}]},"grammar":{"title":"Erzählen – Präteritum, Plusquamperfekt und temporale Nebensätze","summary":"In geschriebenen Texten erzählt man im Präteritum. Temporale Konnektoren ordnen die Ereignisse.","sections":[{"h":"Das Präteritum","text":"In Berichten, Geschichten und Zeitungstexten benutzt man das **Präteritum**. Regelmässige Verben bekommen **-te**. Unregelmässige Verben ändern den Vokal und haben bei *ich* und *er/sie/es* **keine Endung**.","table":[["Person","bremsen (regelmässig)","fahren (unregelmässig)"],["ich","bremste","fuhr"],["du","bremstest","fuhrst"],["er/sie/es","bremste","fuhr"],["wir","bremsten","fuhren"],["ihr","bremstet","fuhrt"],["sie/Sie","bremsten","fuhren"]]},{"h":"Wichtige unregelmässige Verben","table":[["Infinitiv","Präteritum","Infinitiv","Präteritum"],["kommen","kam","sehen","sah"],["gehen","ging","fallen","fiel"],["geben","gab","rufen","rief"],["stehen","stand","helfen","half"],["bringen","brachte","denken","dachte"],["wissen","wusste","tragen","trug"]]},{"h":"als oder wenn?","text":"**als** – ein einziges Mal in der Vergangenheit (oder eine Zeitperiode: *als ich ein Kind war*).\n**wenn** – immer wieder (*jedes Mal, wenn …*) und in der Gegenwart oder Zukunft.","examples":[{"de":"==Als== ich zur Kreuzung kam, fuhr plötzlich ein Auto los.","en":"When I got to the junction, a car suddenly pulled out.","audio":"a699481e3801"},{"de":"==Wenn== es regnet, fahre ich immer langsam.","en":"Whenever it rains, I always ride slowly.","audio":"2bff3c2082a3"}]},{"h":"bevor, nachdem, während","table":[["Konnektor","Bedeutung","Beispiel"],["bevor","zuerst der Hauptsatz, dann der Nebensatz","Bevor ich losfahre, setze ich den Helm auf."],["nachdem","zuerst der Nebensatz, dann der Hauptsatz","Nachdem der Arzt mich untersucht hatte, bekam ich einen Gips."],["während","gleichzeitig","Während sie wartete, sah sie den Unfall."]]},{"h":"Das Plusquamperfekt – die Vergangenheit vor der Vergangenheit","text":"**hatte / war + Partizip II**. Man benutzt es für etwas, das **vor** einem anderen Ereignis in der Vergangenheit passiert ist – besonders nach **nachdem**.","examples":[{"de":"Die Strasse war nass, weil es vorher ==geregnet hatte==.","en":"The road was wet because it had rained before.","audio":"51186118ac2d"},{"de":"Nachdem die Ambulanz ==gekommen war==, ging alles sehr schnell.","en":"After the ambulance had arrived, everything happened very quickly.","audio":"51838fc43ae8"}]}],"tip":"Im Gespräch benutzt man meistens das Perfekt – in der Schweiz fast immer. Aber bei sein, haben und den Modalverben benutzt man auch mündlich das Präteritum: war, hatte, wollte, konnte."},"exercises":[{"type":"choice","title":"Welcher Konnektor passt?","items":[{"q":"___ ich zur Kreuzung kam, fuhr plötzlich ein Auto los.","options":["Als","Wenn","Bevor"],"a":0,"full":"Als ich zur Kreuzung kam, fuhr plötzlich ein Auto los.","audio":"a699481e3801"},{"q":"___ es regnet, fahre ich immer mit dem Bus.","options":["Wenn","Als","Nachdem"],"a":0,"full":"Wenn es regnet, fahre ich immer mit dem Bus.","audio":"ff5bc030a6f5"},{"q":"___ ich losfahre, setze ich immer den Helm auf.","options":["Bevor","Nachdem","Als"],"a":0,"full":"Bevor ich losfahre, setze ich immer den Helm auf.","audio":"fe96f3232ac4"},{"q":"___ der Arzt die Hand geröntgt hatte, bekam ich einen Gips.","options":["Nachdem","Bevor","Während"],"a":0,"full":"Nachdem der Arzt die Hand geröntgt hatte, bekam ich einen Gips.","audio":"6c485595cb41"},{"q":"___ die Frau wartete, sah sie den Unfall.","options":["Während","Bevor","Nachdem"],"a":0,"full":"Während die Frau wartete, sah sie den Unfall.","audio":"693852d17ffd"},{"q":"___ ich ein Kind war, fuhr ich jeden Tag mit dem Velo zur Schule.","options":["Als","Wenn","Während"],"a":0,"full":"Als ich ein Kind war, fuhr ich jeden Tag mit dem Velo zur Schule.","audio":"b4d9bcd509b6"},{"q":"Jedes Mal, ___ ich an diese Kreuzung komme, bin ich jetzt sehr vorsichtig.","options":["wenn","als","bevor"],"a":0,"full":"Jedes Mal, wenn ich an diese Kreuzung komme, bin ich jetzt sehr vorsichtig.","audio":"94af4a242bea"},{"q":"___ ich den Gips habe, fahre ich mit dem Bus zur Arbeit.","options":["Seit","Als","Bevor"],"a":0,"full":"Seit ich den Gips habe, fahre ich mit dem Bus zur Arbeit.","audio":"d641c46d5e2d"}]},{"type":"gap","title":"Präteritum – schreiben Sie die richtige Form","items":[{"q":"Gestern ___ ich mit dem Velo zur Arbeit. (fahren)","a":["fuhr"],"full":"Gestern fuhr ich mit dem Velo zur Arbeit.","audio":"3effe1916bea"},{"q":"Plötzlich ___ ein Auto aus der Einfahrt. (kommen)","a":["kam"],"full":"Plötzlich kam ein Auto aus der Einfahrt.","audio":"86e1e8aa6f7f"},{"q":"Ich ___ sofort. (bremsen)","a":["bremste"],"full":"Ich bremste sofort.","audio":"a416d904556c"},{"q":"Eine Frau ___ den Unfall. (sehen)","a":["sah"],"full":"Eine Frau sah den Unfall.","audio":"d822b5d7102b"},{"q":"Der Fahrer ___ die Polizei. (rufen)","a":["rief"],"full":"Der Fahrer rief die Polizei.","audio":"07d856c3e0c5"},{"q":"Wir ___ zwei Stunden im Spital. (warten)","a":["warteten"],"full":"Wir warteten zwei Stunden im Spital.","audio":"ccf1cbd5c7b7"},{"q":"Ich ___ auf die rechte Hand. (fallen)","a":["fiel"],"full":"Ich fiel auf die rechte Hand.","audio":"8eb63290517d"},{"q":"Zum Glück ___ ich einen Helm. (tragen)","a":["trug"],"full":"Zum Glück trug ich einen Helm.","audio":"635450131137"}]},{"type":"gap","title":"Plusquamperfekt nach „nachdem\"","items":[{"q":"Nachdem es stark ___ hatte, war die Strasse nass. (regnen)","a":["geregnet"],"full":"Nachdem es stark geregnet hatte, war die Strasse nass.","audio":"8a9ad0ddc4fa"},{"q":"Nachdem die Ambulanz ___ war, ging alles sehr schnell. (kommen)","a":["gekommen"],"full":"Nachdem die Ambulanz gekommen war, ging alles sehr schnell.","audio":"51838fc43ae8"},{"q":"Nachdem ich die Unfallmeldung ___ hatte, rief ich meine Chefin an. (ausfüllen)","a":["ausgefüllt"],"full":"Nachdem ich die Unfallmeldung ausgefüllt hatte, rief ich meine Chefin an.","audio":"173cf19fbb84"},{"q":"Nachdem wir im Spital ___ waren, fuhren wir nach Hause. (sein)","a":["gewesen"],"full":"Nachdem wir im Spital gewesen waren, fuhren wir nach Hause.","audio":"18523eca2581"},{"q":"Nachdem der Arzt mich ___ hatte, bekam ich einen Gips. (untersuchen)","a":["untersucht"],"full":"Nachdem der Arzt mich untersucht hatte, bekam ich einen Gips.","audio":"6d6c9b397de5"}]},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Als ich zur Kreuzung kam, fuhr ein Auto aus der Einfahrt."],"tokens":["Als","ich","zur","Kreuzung","kam,","fuhr","ein","Auto","aus","der","Einfahrt."],"audio":"b3f948a737b6"},{"a":["Bevor ich losfahre, setze ich den Helm auf.","Ich setze den Helm auf, bevor ich losfahre."],"tokens":["Bevor","ich","losfahre,","setze","ich","den","Helm","auf."],"audio":"cdf3d1c0c208"},{"a":["Nachdem der Arzt mich untersucht hatte, bekam ich einen Gips."],"tokens":["Nachdem","der","Arzt","mich","untersucht","hatte,","bekam","ich","einen","Gips."],"audio":"6d6c9b397de5"},{"a":["Während sie wartete, sah sie den Unfall.","Sie sah den Unfall, während sie wartete."],"tokens":["Während","sie","wartete,","sah","sie","den","Unfall."],"audio":"409c4f360aa4"},{"a":["Wenn es regnet, fahre ich immer langsam.","Ich fahre immer langsam, wenn es regnet."],"tokens":["Wenn","es","regnet,","fahre","ich","immer","langsam."],"audio":"2bff3c2082a3"}]},{"type":"match","title":"Infinitiv und Präteritum","items":[{"l":"kommen","r":"kam"},{"l":"fahren","r":"fuhr"},{"l":"sehen","r":"sah"},{"l":"fallen","r":"fiel"},{"l":"rufen","r":"rief"},{"l":"geben","r":"gab"},{"l":"wissen","r":"wusste"},{"l":"helfen","r":"half"}]},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Als ich zur Kreuzung kam, fuhr plötzlich ein Auto los.","audio":"2904dce2631b"},{"a":"Ich wollte ausweichen und bin gestürzt.","audio":"796e6f603c96"},{"a":"Nachdem der Arzt mich untersucht hatte, bekam ich einen Gips.","audio":"84594c0bb960"},{"a":"Gab es Zeugen?","audio":"ae6430d24b3c"}]}],"reading":{"title":"Unfallmeldung – Schilderung des Unfalls","kind":"Bericht","paras":[{"t":"Am Donnerstagabend fuhr ich gegen 18 Uhr mit dem Velo von der Arbeit nach Hause. Vorher hatte es stark geregnet, und die Strasse war noch nass. Ich fuhr auf dem Velostreifen in Richtung Zentrum.","audio":"1fc7541ce318"},{"t":"Als ich zur Kreuzung mit der Bahnhofstrasse kam, fuhr plötzlich ein grauer Lieferwagen rückwärts aus einer Einfahrt. Der Fahrer hatte mich nicht gesehen. Ich bremste sofort und versuchte, nach links auszuweichen. Dabei rutschte mein Hinterrad weg, und ich stürzte auf die rechte Hand.","audio":"5b57e2b4d5e7"},{"t":"Der Fahrer stieg sofort aus und half mir. Eine Fussgängerin, die am Fussgängerstreifen gewartet hatte, hatte den Unfall beobachtet. Sie gab mir ihre Kontaktdaten. Bevor die Ambulanz kam, rief der Fahrer auch die Polizei.","audio":"dd6c4352078b"},{"t":"Im Spital stellte man fest, dass mein rechtes Handgelenk gebrochen war. Ich bin für sechs Wochen krankgeschrieben. Mein Velo wurde stark beschädigt, und mein Velohelm ist ebenfalls kaputt.","audio":"7636c9f08284"},{"t":"Carla Ferreira","audio":"40f9135d1b44"}],"glossary":[{"de":"gegen 18 Uhr","en":"around 6 p.m."},{"de":"rückwärts","en":"backwards, in reverse"},{"de":"wegrutschen","en":"to slip away"},{"de":"beobachten","en":"to observe"},{"de":"feststellen","en":"to find, establish"},{"de":"beschädigt","en":"damaged"}],"questions":[{"type":"tf","q":"Die Strasse war nass, weil es vorher geregnet hatte.","a":true,"why":""},{"type":"mc","q":"Was machte der Lieferwagen?","options":["Er fuhr zu schnell.","Er fuhr rückwärts aus einer Einfahrt.","Er hielt am Fussgängerstreifen."],"a":1},{"type":"tf","q":"Der Fahrer fuhr nach dem Unfall einfach weiter.","a":false,"why":"Er stieg sofort aus und half."},{"type":"mc","q":"Wer hat den Unfall beobachtet?","options":["ein Polizist","eine Fussgängerin","ein anderer Velofahrer"],"a":1},{"type":"mc","q":"Was ist kaputt?","options":["nur das Velo","das Velo und der Helm","der Lieferwagen"],"a":1}]},"writing":{"task":"Sie hatten einen kleinen Unfall. Schreiben Sie einer Freundin eine E-Mail und erzählen Sie, was passiert ist (80–100 Wörter).","points":["Wann und wo ist es passiert?","Was ist passiert? (als, nachdem, bevor …)","Wie geht es Ihnen jetzt?","Was können Sie im Moment nicht machen?"],"phrases":[{"de":"Stell dir vor, …","en":"Imagine …"},{"de":"Als ich …, …","en":"When I …"},{"de":"Zuerst … dann … danach …","en":"First … then … after that …"},{"de":"Zum Glück … / Leider …","en":"Luckily … / Unfortunately …"},{"de":"Im Moment kann ich nicht …","en":"At the moment I can't …"}],"model":"Liebe Sofia\n\nStell dir vor, letzte Woche hatte ich einen Unfall mit dem Velo! Als ich am Donnerstagabend nach Hause fuhr, kam plötzlich ein Lieferwagen aus einer Einfahrt. Ich bremste, aber die Strasse war nass, und ich stürzte. Nachdem mich die Ambulanz ins Spital gebracht hatte, wurde mein Handgelenk geröntgt – es ist gebrochen. Jetzt habe ich sechs Wochen einen Gips. Zum Glück hatte ich einen Helm! Im Moment kann ich nicht Velo fahren und nur mit der linken Hand schreiben – deshalb ist diese E-Mail so kurz. Wie geht es dir?\n\nLiebe Grüsse\nCarla","audio":"c1c67a947a44"},"speaking":{"task":"Erzählen Sie von Erlebnissen. Benutzen Sie als, bevor, nachdem oder während.","phrases":[{"de":"Als ich …, …","en":"When I …","audio":null},{"de":"Bevor ich …, …","en":"Before I …","audio":null},{"de":"Nachdem ich … hatte / war, …","en":"After I had …","audio":null},{"de":"Zum Glück … / Leider …","en":"Luckily … / Unfortunately …","audio":null},{"de":"Am Ende …","en":"In the end …","audio":null}],"prompts":[{"q":"Erzählen Sie von einem Erlebnis, bei dem etwas schiefgegangen ist.","model":"Als ich in die Schweiz gekommen bin, habe ich am ersten Tag meinen Koffer im Zug vergessen. Zum Glück hat ihn jemand gefunden und beim Fundbüro abgegeben.","aq":"8bbd05d975e1","am":"ea8dbe8a99b3"},{"q":"Was machen Sie, bevor Sie morgens aus dem Haus gehen?","model":"Bevor ich aus dem Haus gehe, trinke ich einen Kaffee und schaue, wie das Wetter wird. Wenn es regnet, fahre ich mit dem Bus und nicht mit dem Velo.","aq":"71fefbc9ac72","am":"92c18aacdae5"},{"q":"Was haben Sie gemacht, nachdem Sie in der Schweiz angekommen waren?","model":"Nachdem ich angekommen war, habe ich mich zuerst bei der Gemeinde angemeldet. Danach habe ich eine Krankenkasse gesucht und ein Bankkonto eröffnet.","aq":"f8cc40c1cd6f","am":"1eed680df30f"},{"q":"Was hat Ihnen am meisten geholfen, als Sie neu hier waren?","model":"Als ich neu hier war, haben mir meine Nachbarn und meine Kollegen am meisten geholfen. Sie haben mir viel erklärt, zum Beispiel, wie man den Abfall trennt.","aq":"d25062503db9","am":"9f4be9cd7704"}]}}],"audioMissing":0};
